    { id: "basilica-santuario-de-sao-sebastiao-capuchinhos", nome: "Basílica Santuário de São Sebastião — Capuchinhos", bairro: "tijuca", lat: -22.919046, lng: -43.214904, categoria: "Religião", descricao: "Localizada na Tijuca, a Basílica Santuário de São Sebastião, conhecida como Igreja dos Capuchinhos, é um importante marco religioso e histórico do Rio de Janeiro. Dedicada ao padroeiro da cidade, São Sebastião, foi inaugurada em 15 de agosto de 1931, após a transferência de importantes elementos históricos da antiga Igreja de São Sebastião, que ficava no Morro do Castelo e foi demolida em 1922. Entre seus principais tesouros estão os restos mortais de Estácio de Sá, fundador da cidade, o marco de fundação do Rio de Janeiro, de 1565, e uma imagem de São Sebastião datada de 1563. Tombada pelo município em 2003, a basílica preserva parte importante da memória religiosa e da própria formação histórica da cidade.", importancia: null, endereco: "Rua Haddock Lobo, 266", imagem: {"src": "assets/img/basilica-santuario-de-sao-sebastiao-capuchinhos.jpg", "alt": "Basílica Santuário de São Sebastião — Capuchinhos", "fonte": "partiu__lugaresss.docx"} },
    { id: "basilica-de-sao-francisco-xavier", nome: "Basílica de São Francisco Xavier", bairro: "tijuca", lat: -22.920122, lng: -43.224171, categoria: "Religião", descricao: "Localizada na Tijuca, a Basílica de São Francisco Xavier é um dos templos religiosos mais antigos e importantes da região. Sua origem remonta ao século XVI, quando os jesuítas estabeleceram uma ermida dedicada ao santo na antiga região do Engenho Velho. Ao longo dos séculos, a construção passou por diversas transformações, incluindo uma importante reconstrução iniciada em 1805, da qual permanecem elementos como a fachada e as torres decoradas com azulejos. A igreja está diretamente ligada à formação histórica da Tijuca, tendo contribuído para o desenvolvimento religioso e social do bairro. Em novembro de 2025, recebeu oficialmente o título de Basílica Menor, em reconhecimento à sua relevância religiosa e histórica.", importancia: null, endereco: "Rua São Francisco Xavier, 75", imagem: {"src": "assets/img/basilica-de-sao-francisco-xavier.jpg", "alt": "Basílica de São Francisco Xavier", "fonte": "partiu__lugaresss.docx"} },
    { id: "basilica-santa-teresinha-do-menino-jesus", nome: "Basílica Santa Teresinha do Menino Jesus", bairro: "tijuca", lat: -22.913083, lng: -43.217254, categoria: "Religião", descricao: "Localizada na Rua Mariz e Barros, na Tijuca, a Basílica de Santa Teresinha do Menino Jesus é um importante espaço de devoção católica dedicado à santa francesa conhecida como Santa Teresinha do Menino Jesus, também chamada de Santa Teresa de Lisieux. Sua espiritualidade é marcada pela chamada Pequena Via, baseada na simplicidade, na humildade e na confiança em Deus. O templo integra o conjunto de edificações religiosas de valor histórico e arquitetônico do bairro, sendo reconhecido como bem protegido pelo patrimônio municipal desde 2003. Sua presença representa a influência da devoção a Santa Teresinha na vida religiosa carioca.", importancia: null, endereco: "Rua Mariz e Barros, 254", imagem: {"src": "assets/img/basilica-santa-teresinha-do-menino-jesus.jpg", "alt": "Basílica Santa Teresinha do Menino Jesus", "fonte": "partiu__lugaresss.docx"} },
    { id: "santuario-de-nossa-senhora-das-gracas-da-medalha-milagrosa", nome: "Santuário de Nossa Senhora das Graças da Medalha Milagrosa", bairro: "tijuca", lat: -22.915241, lng: -43.214509, categoria: "Religião", descricao: "Localizado na Rua Doutor Satamini, na Tijuca, o Santuário de Nossa Senhora das Graças da Medalha Milagrosa é um importante centro de devoção mariana no Rio de Janeiro. Sua dedicação está relacionada às aparições de Nossa Senhora a Santa Catarina Labouré, em 1830, na França, episódio que deu origem à Medalha Milagrosa. A devoção à medalha se espalhou por diversos países, tornando-se um símbolo de fé e proteção para os católicos. O conjunto religioso também preserva uma capela primitiva e integra a relação de bens protegidos pelo patrimônio cultural do município desde 2003.", importancia: null, endereco: "Rua Dr. Satamini, 333", imagem: {"src": "assets/img/santuario-de-nossa-senhora-das-gracas-da-medalha-milagrosa.jpg", "alt": "Santuário de Nossa Senhora das Graças da Medalha Milagrosa", "fonte": "partiu__lugaresss.docx"} },
    { id: "igreja-de-santo-afonso", nome: "Igreja de Santo Afonso", bairro: "tijuca", lat: -22.922661, lng: -43.233478, categoria: "Religião", descricao: "Localizada na Rua Barão de Mesquita, na Tijuca, a Igreja de Santo Afonso é um importante marco religioso e arquitetônico do bairro. Sua história está ligada à chegada dos missionários redentoristas ao Rio de Janeiro, em 1903, que identificaram a necessidade de construir um novo templo para atender à população da região. Inaugurada em 7 de junho de 1907, foi a primeira igreja do Brasil dedicada a Santo Afonso Maria de Ligório, fundador da Congregação do Santíssimo Redentor. Sua arquitetura apresenta influências dos estilos neorromânico e bizantino, com detalhes ornamentais tanto no exterior quanto no interior. Tombada pelo município em 2003, a igreja permanece como uma referência histórica e religiosa da Tijuca.", importancia: null, endereco: "Rua Barão de Mesquita, 275", imagem: {"src": "assets/img/igreja-de-santo-afonso.jpg", "alt": "Igreja de Santo Afonso", "fonte": "partiu__lugaresss.docx"} },
    { id: "igreja-dos-sagrados-coracoes", nome: "Igreja dos Sagrados Corações", bairro: "tijuca", lat: -22.926389, lng: -43.235805, categoria: "Religião", descricao: "Localizada na Rua Conde de Bonfim, na Tijuca, a Igreja Matriz dos Sagrados Corações é um importante espaço de celebração e devoção católica do bairro. Dedicada aos Sagrados Corações de Jesus e Maria, sua tradição religiosa está relacionada à espiritualidade que valoriza o amor, a compaixão e a fé cristã. Além de sua função como local de oração e realização de atividades comunitárias, o templo integra o conjunto de edificações religiosas reconhecidas pelo patrimônio cultural municipal, tendo sido incluído na relação de bens protegidos em 2003. Sua presença contribui para a diversidade histórica e religiosa da região.", importancia: null, endereco: "Rua Conde de Bonfim, 474", imagem: {"src": "assets/img/igreja-dos-sagrados-coracoes.jpg", "alt": "Igreja dos Sagrados Corações", "fonte": "partiu__lugaresss.docx"} },
    { id: "igreja-nossa-senhora-do-libano", nome: "Igreja Nossa Senhora do Líbano", bairro: "tijuca", lat: -22.930818, lng: -43.239276, categoria: "Religião", descricao: "Localizada na Rua Conde de Bonfim, na Tijuca, a Igreja Nossa Senhora do Líbano é um importante símbolo da presença da comunidade libanesa e da tradição cristã maronita no Rio de Janeiro. A criação da paróquia maronita ocorreu em 1946, refletindo a organização religiosa dos imigrantes e descendentes libaneses na cidade. Em 1951, foi lançada a pedra fundamental do atual templo, cuja construção foi concluída em 1960. A igreja preserva elementos da tradição oriental cristã e representa a contribuição da imigração libanesa para a formação cultural e religiosa carioca. Seu valor histórico também é reconhecido pelo município, que a incluiu entre os bens protegidos em 2003.", importancia: null, endereco: "Rua Conde de Bonfim, 638", imagem: {"src": "assets/img/igreja-nossa-senhora-do-libano.jpg", "alt": "Igreja Nossa Senhora do Líbano", "fonte": "partiu__lugaresss.docx"} },
    { id: "igreja-nossa-senhora-da-conceicao", nome: "Igreja Nossa Senhora da Conceição", bairro: "tijuca", lat: -22.93976, lng: -43.24925, categoria: "Religião", descricao: "Localizada na região da Tijuca, a Igreja Nossa Senhora da Conceição é um importante patrimônio religioso e arquitetônico do bairro. Dedicada à Imaculada Conceição, a igreja está ligada à atuação da Ordem Terceira de São Francisco da Penitência, instituição religiosa que também mantém edificações históricas nas proximidades. Seu conjunto arquitetônico representa parte da tradição católica e da história social da região. Reconhecida por seu valor histórico e arquitetônico, a igreja recebeu tombamento definitivo pelo município em 2003, garantindo a proteção de suas características e de sua importância para a memória carioca.", importancia: null, endereco: "Rua Conde de Bonfim, 1036", imagem: {"src": "assets/img/igreja-nossa-senhora-da-conceicao.jpg", "alt": "Igreja Nossa Senhora da Conceição", "fonte": "partiu__lugaresss.docx"} },
    { id: "templo-uniao-israel", nome: "Templo União Israel", bairro: "tijuca", lat: -22.930469, lng: -43.23564, categoria: "Religião", descricao: "Localizado na Rua José Higino, na Tijuca, o Templo União Israel é um espaço de culto e convivência da comunidade judaica carioca. Ligado à tradição judaica sefaradita, o templo representa a diversidade religiosa e cultural presente no bairro, além de contribuir para a preservação das práticas, celebrações e tradições do judaísmo. Sua existência também evidencia a presença e a participação das comunidades judaicas na formação da identidade cultural do Rio de Janeiro, tornando-se um importante ponto de referência religiosa para seus frequentadores.", importancia: null, endereco: "Rua José Higino, 375", imagem: {"src": "assets/img/templo-uniao-israel.jpg", "alt": "Templo União Israel", "fonte": "partiu__lugaresss.docx"} },
    { id: "congregacao-espirita-francisco-de-paula", nome: "Congregação Espírita Francisco de Paula", bairro: "tijuca", lat: -22.922713, lng: -43.228101, categoria: "Religião", descricao: "Localizada na Rua Conselheiro Zenha, na Tijuca, a Congregação Espírita Francisco de Paula é uma instituição dedicada ao estudo e à prática da Doutrina Espírita. Fundada em 23 de abril de 1929, sua origem está relacionada à iniciativa de um grupo de 20 pessoas que se reuniu com o objetivo de estabelecer uma nova organização espírita. Ao longo de sua trajetória, a instituição passou a desenvolver atividades como reuniões públicas, estudos doutrinários, evangelização e trabalhos de assistência. Com uma história de quase um século, representa a continuidade da tradição espírita e da atuação comunitária no bairro da Tijuca.", importancia: null, endereco: "Rua Conselheiro Zenha, 31", imagem: {"src": "assets/img/congregacao-espirita-francisco-de-paula.jpg", "alt": "Congregação Espírita Francisco de Paula", "fonte": "partiu__lugaresss.docx"} },
    { id: "sociedade-espirita-ramatis", nome: "Sociedade Espírita Ramatis", bairro: "tijuca", lat: -22.927889, lng: -43.239987, categoria: "Religião", descricao: "Localizada na Rua José Higino, na Tijuca, a Sociedade Espírita Ramatis é uma instituição dedicada ao estudo e à divulgação da Doutrina Espírita. Seu nome faz referência a Ramatís, uma entidade espiritual presente em obras psicografadas que abordam temas relacionados à espiritualidade, à evolução humana e à fraternidade. A instituição desenvolve atividades voltadas ao estudo doutrinário, à reflexão espiritual e à prática da caridade, contribuindo para a presença e a diversidade do movimento espírita na região.", importancia: null, endereco: "Rua José Higino, 176", imagem: {"src": "assets/img/sociedade-espirita-ramatis.jpg", "alt": "Sociedade Espírita Ramatis", "fonte": "partiu__lugaresss.docx"} },
    { id: "tenda-espirita-umbandista-caminheiros-de-oxala", nome: "Tenda Espírita Umbandista Caminheiros de Oxalá", bairro: "tijuca", lat: -22.927468, lng: -43.245844, categoria: "Religião", descricao: "Localizada na Rua Santa Maria Rossello, na Tijuca, a Tenda Espírita Umbandista Caminheiros de Oxalá é um espaço dedicado à prática da Umbanda, religião brasileira que reúne elementos de tradições africanas, indígenas, católicas e espíritas. Seu nome faz referência a Oxalá, considerado uma das principais divindades da religião, associado à criação, à paz e à fé. O terreiro representa a continuidade das tradições religiosas afro-brasileiras e a importância dos espaços de culto para a preservação da ancestralidade, da espiritualidade e da identidade cultural de suas comunidades.", importancia: null, endereco: "Rua Santa Maria Rossello, 140", imagem: {"src": "assets/img/tenda-espirita-umbandista-caminheiros-de-oxala.jpg", "alt": "Tenda Espírita Umbandista Caminheiros de Oxalá", "fonte": "partiu__lugaresss.docx"} },
    { id: "capela-da-irmandade-do-senhor-bom-jesus-de-calvario", nome: "Capela da Irmandade do Senhor Bom Jesus de Calvário", bairro: "tijuca", lat: -22.923116, lng: -43.223189, categoria: "Religião", descricao: "Localizada na Rua Conde de Bonfim, na Tijuca, a Capela da Irmandade do Senhor Bom Jesus do Calvário está ligada à tradição das irmandades religiosas católicas, organizações formadas por leigos que se reuniam para cultivar a fé, promover celebrações e desenvolver ações de auxílio aos seus membros e à comunidade. Dedicada a Jesus Cristo em sua representação durante o Calvário, a capela preserva uma tradição de devoção associada à Paixão de Cristo. Sua existência representa a importância das antigas organizações religiosas na construção da vida comunitária e da história católica do Rio de Janeiro.", importancia: null, endereco: "Rua Conde de Bonfim, 50", imagem: {"src": "assets/img/capela-da-irmandade-do-senhor-bom-jesus-de-calvario.jpg", "alt": "Capela da Irmandade do Senhor Bom Jesus de Calvário", "fonte": "partiu__lugaresss.docx"} },
    { id: "igreja-messianica-mundial-do-brasil-tijuca", nome: "Igreja Messiânica Mundial do Brasil — Tijuca", bairro: "tijuca", lat: -22.932286, lng: -43.236608, categoria: "Religião", descricao: "Localizada na Rua Visconde de Cabo Frio, na Tijuca, a Igreja Messiânica Mundial do Brasil integra uma organização religiosa de origem japonesa fundada por Mokichi Okada, também conhecido como Meishu-Sama, em 1935. A religião tem como princípios a construção de uma sociedade mais harmoniosa e a busca pelo desenvolvimento espiritual, valorizando práticas como o Johrei, uma forma de transmissão de energia espiritual por meio da imposição das mãos. A instituição também incentiva a apreciação da arte, da natureza e a prática da agricultura natural. Sua presença na Tijuca representa a diversidade religiosa e a influência da cultura japonesa na cidade.", importancia: null, endereco: "Rua Visconde de Cabo Frio, 52", imagem: {"src": "assets/img/igreja-messianica-mundial-do-brasil-tijuca.jpg", "alt": "Igreja Messiânica Mundial do Brasil — Tijuca", "fonte": "partiu__lugaresss.docx"} },
    { id: "templo-sidon", nome: "Templo Sidon", bairro: "tijuca", lat: -22.92834, lng: -43.236377, categoria: "Religião", descricao: "Localizado na Rua Conde de Bonfim, na Tijuca, o Templo Sidon é um espaço religioso que integra a diversidade de manifestações espirituais presentes no bairro. Sua presença faz parte do conjunto de instituições que contribuem para a pluralidade religiosa da região, oferecendo um local de encontro e prática de fé para seus frequentadores.", importancia: null, endereco: "Rua Conde de Bonfim, 521", imagem: {"src": "assets/img/templo-sidon.jpg", "alt": "Templo Sidon", "fonte": "partiu__lugaresss.docx"} },
    { id: "igreja-matriz-da-paroquia-do-bom-pastor", nome: "Igreja Matriz da Paróquia do Bom Pastor", bairro: "tijuca", lat: -22.930219, lng: -43.232939, categoria: "Religião", descricao: "Localizada na Rua Bom Pastor, na Tijuca, a Igreja Matriz da Paróquia do Bom Pastor é um espaço de referência para a comunidade católica local. Dedicada a Jesus Cristo sob a representação do Bom Pastor, sua tradição religiosa destaca valores como acolhimento, cuidado e orientação espiritual. Como igreja matriz, desempenha um papel importante na organização da vida paroquial, reunindo fiéis para celebrações litúrgicas, atividades pastorais e ações comunitárias. Sua presença contribui para a continuidade da tradição católica e para a convivência religiosa no bairro.", importancia: null, endereco: "Rua Bom Pastor, 491", imagem: {"src": "assets/img/igreja-matriz-da-paroquia-do-bom-pastor.jpg", "alt": "Igreja Matriz da Paróquia do Bom Pastor", "fonte": "partiu__lugaresss.docx"} },
    { id: "igreja-crista-nova-vida-tijuca", nome: "Igreja Cristã Nova Vida Tijuca", bairro: "tijuca", lat: -22.917841, lng: -43.218791, categoria: "Religião", descricao: "Localizada na Rua Afonso Pena, na Tijuca, a Igreja Cristã Nova Vida integra uma denominação evangélica brasileira fundada pelo bispo Walter McAlister, em 1960. A igreja tem suas raízes na tradição pentecostal e desenvolve atividades voltadas à evangelização, ao ensino bíblico, à oração e à convivência comunitária. Sua presença no bairro representa a diversidade do cristianismo evangélico no Rio de Janeiro e a importância das comunidades religiosas como espaços de encontro, orientação espiritual e participação social.", importancia: null, endereco: "Rua Afonso Pena, 85 — Tijuca", imagem: {"src": "assets/img/igreja-crista-nova-vida-tijuca.jpg", "alt": "Igreja Cristã Nova Vida Tijuca", "fonte": "partiu__lugaresss.docx"} },
    { id: "colegio-militar-do-rio-de-janeiro", nome: "Colégio Militar do Rio de Janeiro", bairro: "tijuca", lat: -22.916256, lng: -43.226994, categoria: "Educação", descricao: "Fundado em 6 de maio de 1889, o Colégio Militar do Rio de Janeiro é uma das instituições de ensino mais tradicionais do país. Sua criação está relacionada à iniciativa de Duque de Caxias, que defendia a educação dos filhos de militares e de jovens sem condições de acesso ao ensino. Ao longo de sua trajetória, tornou-se referência no Sistema Colégio Militar do Brasil, oferecendo formação acadêmica e valorizando princípios como disciplina, responsabilidade e civismo. Instalado na Rua São Francisco Xavier, na Tijuca, seu prédio também se destaca pela arquitetura e pela importância histórica para a educação brasileira.", importancia: null, endereco: "Rua São Francisco Xavier, 267", imagem: {"src": "assets/img/colegio-militar-do-rio-de-janeiro.jpg", "alt": "Colégio Militar do Rio de Janeiro", "fonte": "partiu__lugaresss.docx"} },
    { id: "instituto-superior-de-educacao-do-rio-de-janeiro-iserj", nome: "Instituto Superior de Educação do Rio de Janeiro (ISERJ)", bairro: "tijuca", lat: -22.913184, lng: -43.217046, categoria: "Educação", descricao: "Fundado em 1880, inicialmente como Escola Normal da Corte, o Instituto Superior de Educação do Rio de Janeiro (ISERJ) é uma das instituições mais importantes da história da formação de professores no Brasil. Sua criação esteve ligada ao desenvolvimento do ensino público e à necessidade de preparar profissionais para atuar na educação. Ao longo dos anos, passou por diferentes denominações e mudanças institucionais, acompanhando as transformações do sistema educacional brasileiro. Localizado na Rua Mariz e Barros, na Tijuca, o instituto mantém sua tradição na formação de educadores e representa um importante patrimônio da história da educação carioca.", importancia: null, endereco: "Rua Mariz e Barros, 273", imagem: {"src": "assets/img/instituto-superior-de-educacao-do-rio-de-janeiro-iserj.jpg", "alt": "Instituto Superior de Educação do Rio de Janeiro (ISERJ)", "fonte": "partiu__lugaresss.docx"} },
    { id: "colegio-pedro-ii-campus-tijuca", nome: "Colégio Pedro II — Campus Tijuca", bairro: "tijuca", lat: -22.916145, lng: -43.22592, categoria: "Educação", descricao: "O Colégio Pedro II é uma das instituições de ensino mais tradicionais do Brasil, fundado em 2 de dezembro de 1837, durante o período imperial. Criado por iniciativa do governo de Dom Pedro II, tornou-se referência na educação pública brasileira, contribuindo para a formação de importantes personalidades da história nacional. Sua unidade Tijuca integra uma instituição reconhecida pela qualidade acadêmica e pela tradição no ensino de diferentes áreas do conhecimento. A presença do colégio no bairro reforça a importância da Tijuca como um dos polos educacionais históricos do Rio de Janeiro.", importancia: null, endereco: "Rua Oto de Alencar, 25", imagem: {"src": "assets/img/colegio-pedro-ii-campus-tijuca.jpg", "alt": "Colégio Pedro II — Campus Tijuca", "fonte": "partiu__lugaresss.docx"} },
    { id: "escola-municipal-orsina-da-fonseca", nome: "Escola Municipal Orsina da Fonseca", bairro: "tijuca", lat: -22.919562, lng: -43.224237, categoria: "Educação", descricao: "Localizada na Rua São Francisco Xavier, na Tijuca, a Escola Municipal Orsina da Fonseca é uma instituição pública de ensino que integra a rede municipal de educação do Rio de Janeiro. Seu nome homenageia Orsina da Fonseca, esposa do presidente Hermes da Fonseca, que teve atuação ligada a iniciativas de assistência social e educação. A escola faz parte da história educacional do bairro e contribui para o acesso à educação pública, atendendo gerações de estudantes da região.", importancia: null, endereco: "Rua São Francisco Xavier, 95", imagem: {"src": "assets/img/escola-municipal-orsina-da-fonseca.jpg", "alt": "Escola Municipal Orsina da Fonseca", "fonte": "partiu__lugaresss.docx"} },
    { id: "colegio-santos-anjos", nome: "Colégio Santos Anjos", bairro: "tijuca", lat: -22.93606, lng: -43.241233, categoria: "Educação", descricao: "O Colégio dos Santos Anjos é uma instituição de ensino católica ligada à Congregação das Irmãs dos Santos Anjos, fundada na França em 1831. Sua proposta educacional é inspirada em valores cristãos e busca integrar a formação acadêmica ao desenvolvimento humano e social dos estudantes. A instituição chegou ao Brasil no século XIX e estabeleceu uma trajetória dedicada à educação de crianças e jovens. Sua unidade na Tijuca faz parte da tradição de escolas confessionais que contribuíram para a formação educacional e cultural do Rio de Janeiro.", importancia: null, endereco: "Rua Dezoito de Outubro, 95", imagem: {"src": "assets/img/colegio-santos-anjos.jpg", "alt": "Colégio Santos Anjos", "fonte": "partiu__lugaresss.docx"} },
    { id: "colegio-batista-shepard", nome: "Colégio Batista Shepard", bairro: "tijuca", lat: -22.931094, lng: -43.235355, categoria: "Educação", descricao: "Localizado na Rua José Higino, na Tijuca, o Colégio Batista Shepard é uma instituição de ensino ligada à tradição educacional batista no Brasil. Sua proposta pedagógica combina a formação acadêmica com princípios cristãos, valorizando aspectos como responsabilidade, ética e desenvolvimento humano. Ao longo de sua trajetória, a escola consolidou sua presença na região, contribuindo para a educação de diferentes gerações de estudantes. Sua história também representa a participação das instituições religiosas na expansão do ensino particular e confessional no Rio de Janeiro.", importancia: null, endereco: "Rua José Higino, 416", imagem: {"src": "assets/img/colegio-batista-shepard.jpg", "alt": "Colégio Batista Shepard", "fonte": "partiu__lugaresss.docx"} },
    { id: "colegio-marista-sao-jose", nome: "Colégio Marista São José", bairro: "tijuca", lat: -22.941845, lng: -43.250796, categoria: "Educação", descricao: "Fundado em 1902, o Colégio Marista São José integra a rede de instituições educacionais da Congregação dos Irmãos Maristas, fundada por São Marcelino Champagnat, na França, em 1817. Sua proposta educacional é baseada na formação integral dos estudantes, combinando ensino acadêmico, valores cristãos e desenvolvimento social. Localizado na Rua Conde de Bonfim, na Tijuca, o colégio possui uma longa trajetória na educação carioca e se tornou uma referência entre as instituições tradicionais do bairro. Sua história está ligada à expansão da educação marista no Brasil e à formação de diversas gerações de alunos.", importancia: null, endereco: "Rua Conde de Bonfim, 1067", imagem: {"src": "assets/img/colegio-marista-sao-jose.jpg", "alt": "Colégio Marista São José", "fonte": "partiu__lugaresss.docx"} },
    { id: "colegio-maria-raythe", nome: "Colégio Maria Raythe", bairro: "tijuca", lat: -22.919328, lng: -43.213927, categoria: "Educação", descricao: "O Colégio Maria Raythe é uma instituição de ensino localizada na região da Tijuca, que integra a história da educação particular do bairro. Ao longo de sua trajetória, participou da formação de estudantes da região, contribuindo para a oferta de ensino e para o desenvolvimento educacional da comunidade. Sua presença faz parte do conjunto de escolas que ajudaram a consolidar a Tijuca como uma área tradicionalmente marcada pela diversidade de instituições educacionais.", importancia: null, endereco: "Rua Haddock Lobo", imagem: {"src": "assets/img/colegio-maria-raythe.jpg", "alt": "Colégio Maria Raythe", "fonte": "partiu__lugaresss.docx"} },
    { id: "instituto-la-fayette", nome: "Instituto La-Fayette", bairro: "tijuca", lat: null, lng: null, categoria: "Educação", descricao: "O Instituto La-Fayette foi uma tradicional instituição de ensino do Rio de Janeiro, reconhecida por sua contribuição à história da educação carioca. Seu antigo edifício, localizado na Rua Haddock Lobo, na Tijuca, representa parte da memória arquitetônica e educacional do bairro. A instituição integrou o conjunto de estabelecimentos particulares que tiveram papel importante na formação de estudantes ao longo do século XX. Mesmo após o encerramento de suas atividades originais, sua construção permanece como referência histórica, sendo protegida pelo patrimônio cultural municipal.", importancia: null, endereco: "Rua Haddock Lobo", imagem: {"src": "assets/img/instituto-la-fayette.jpg", "alt": "Instituto La-Fayette", "fonte": "partiu__lugaresss.docx"} },
    { id: "escola-municipal-menezes-vieira", nome: "Escola Municipal Menezes Vieira", bairro: "tijuca", lat: null, lng: null, categoria: "Educação", descricao: "A Escola Municipal Menezes Vieira está relacionada à história da educação pública no Rio de Janeiro e homenageia Joaquim José Menezes Vieira, médico e educador que teve importante participação no desenvolvimento do ensino brasileiro no século XIX. Menezes Vieira destacou-se por suas iniciativas pedagógicas e pela defesa de métodos de ensino inovadores para sua época. A instituição representa a valorização da memória de educadores que contribuíram para a construção do sistema educacional brasileiro e para a ampliação do acesso à educação.", importancia: null, endereco: "Rua São Francisco Xavier", imagem: {"src": "assets/img/escola-municipal-menezes-vieira.jpg", "alt": "Escola Municipal Menezes Vieira", "fonte": "partiu__lugaresss.docx"} },
    { id: "escola-municipal-mario-da-veiga-cabral", nome: "Escola Municipal Mário da Veiga Cabral", bairro: "tijuca", lat: -22.920346, lng: -43.220633, categoria: "Educação", descricao: "Localizada na Rua Melo Matos, na Tijuca, a Escola Municipal Mário da Veiga Cabral integra a rede pública de ensino do Rio de Janeiro. Seu nome homenageia Mário da Veiga Cabral, figura ligada à história brasileira, cuja memória foi incorporada à denominação de instituições públicas. A escola desempenha um papel importante na oferta de educação básica e no atendimento à comunidade local, contribuindo para a formação de crianças e jovens e para o fortalecimento do ensino público no bairro.", importancia: null, endereco: "Rua Melo Matos, 34", imagem: {"src": "assets/img/escola-municipal-mario-da-veiga-cabral.jpg", "alt": "Escola Municipal Mário da Veiga Cabral", "fonte": "partiu__lugaresss.docx"} },
    { id: "escola-municipal-soares-pereira", nome: "Escola Municipal Soares Pereira", bairro: "tijuca", lat: -22.932503, lng: -43.243233, categoria: "Educação", descricao: "A Escola Municipal Soares Pereira integra a rede pública de ensino do Rio de Janeiro e está localizada na região da Tijuca, próxima à Praça Comandante Xavier de Brito. Como instituição de educação básica, desempenha um papel importante na formação de estudantes e no atendimento às famílias da comunidade. Sua presença faz parte da rede de escolas municipais que contribuem para a democratização do acesso à educação e para o desenvolvimento social do bairro.", importancia: null, endereco: "Praça Comandante Xavier de Brito", imagem: {"src": "assets/img/escola-municipal-soares-pereira.jpg", "alt": "Escola Municipal Soares Pereira", "fonte": "partiu__lugaresss.docx"} },
    { id: "colegio-santa-marcelina", nome: "Colégio Santa Marcelina", bairro: "tijuca", lat: null, lng: null, categoria: "Educação", descricao: "O Colégio Santa Marcelina integra a tradição educacional da Congregação das Irmãs Marcelinas, fundada em 1838, na Itália, por Bartolomea Capitanio e Vincenza Gerosa. A congregação desenvolveu um trabalho voltado principalmente à educação e à formação humana, fundamentado em princípios cristãos. No Brasil, as instituições marcelinas construíram uma trajetória importante na área educacional, combinando conhecimento acadêmico, valores éticos e desenvolvimento social. Sua história representa a contribuição das congregações religiosas para a expansão do ensino no país.", importancia: null, endereco: "Rua Doutor Satamini, 195", imagem: {"src": "assets/img/colegio-santa-marcelina.jpg", "alt": "Colégio Santa Marcelina", "fonte": "partiu__lugaresss.docx"} },
    { id: "instituto-padre-leonardo-carrescia-cap-uerj", nome: "Instituto Padre Leonardo Carrescia / CAp-UERJ", bairro: "tijuca", lat: -22.916325, lng: -43.211055, categoria: "Educação", descricao: "O Instituto de Aplicação Fernando Rodrigues da Silveira, conhecido como CAp-UERJ, é uma importante instituição pública de ensino vinculada à Universidade do Estado do Rio de Janeiro. Fundado em 1957, inicialmente como Ginásio de Aplicação da Faculdade de Filosofia, Ciências e Letras da UERJ, foi criado com o objetivo de oferecer educação básica e servir como espaço de formação e experimentação para futuros professores. Ao longo de sua história, consolidou-se como referência na integração entre ensino, pesquisa e extensão universitária. Sua proposta pedagógica valoriza a construção do conhecimento e a formação crítica dos estudantes, desempenhando um papel importante na educação pública fluminense.", importancia: null, endereco: "Rua Jaceguai, 400", imagem: {"src": "assets/img/instituto-padre-leonardo-carrescia-cap-uerj.jpg", "alt": "Instituto Padre Leonardo Carrescia / CAp-UERJ", "fonte": "partiu__lugaresss.docx"} },
    { id: "nave-colegio-estadual-jose-leite-lopes", nome: "NAVE — Colégio Estadual José Leite Lopes", bairro: "tijuca", lat: -22.926887, lng: -43.244827, categoria: "Educação", descricao: "O NAVE (Núcleo Avançado em Educação), instalado no Colégio Estadual José Leite Lopes, na Tijuca, é uma iniciativa de educação pública voltada à integração entre ensino médio, tecnologia e inovação. Criado por meio de uma parceria entre a Secretaria de Estado de Educação do Rio de Janeiro e o Instituto Oi Futuro, o projeto busca aproximar a formação escolar das áreas de tecnologia e economia criativa. Os estudantes têm contato com conhecimentos relacionados a programação, multimídia e desenvolvimento de soluções digitais, além das disciplinas tradicionais do ensino médio. A iniciativa representa uma proposta de modernização da educação pública, estimulando a criatividade, a experimentação e o desenvolvimento de habilidades para o mundo contemporâneo.", importancia: null, endereco: "Rua Uruguai, 204", imagem: {"src": "assets/img/nave-colegio-estadual-jose-leite-lopes.jpg", "alt": "NAVE — Colégio Estadual José Leite Lopes", "fonte": "partiu__lugaresss.docx"} },
    { id: "tijuca-tenis-clube", nome: "Tijuca Tênis Clube", bairro: "tijuca", lat: -22.926601, lng: -43.235025, categoria: "Esportes", descricao: "Fundado em 1915, o Tijuca Tênis Clube é uma das instituições esportivas e sociais mais tradicionais da Zona Norte do Rio de Janeiro. Localizado na Rua Conde de Bonfim, o clube teve papel importante no desenvolvimento do esporte e do lazer na região, oferecendo atividades como natação, tênis, basquete, vôlei e diversas modalidades esportivas. Ao longo de sua trajetória, também se consolidou como espaço de convivência e realização de eventos culturais e sociais. Sua história está diretamente ligada à formação da identidade esportiva e comunitária da Tijuca.", importancia: null, endereco: "Rua Conde de Bonfim, 451", imagem: {"src": "assets/img/tijuca-tenis-clube.jpg", "alt": "Tijuca Tênis Clube", "fonte": "partiu__lugaresss.docx"} },
    { id: "club-municipal", nome: "Club Municipal", bairro: "tijuca", lat: -22.920771, lng: -43.217659, categoria: "Esportes", descricao: "Fundado em 1932, o Club Municipal é uma tradicional associação esportiva, cultural e recreativa localizada na Rua Haddock Lobo, na Tijuca. Ao longo de sua história, tornou-se um importante espaço de convivência para os moradores da região, oferecendo atividades esportivas, eventos sociais e opções de lazer. O clube também se destaca por sua participação na vida comunitária do bairro, mantendo uma tradição de incentivo ao esporte e à integração entre seus associados.", importancia: null, endereco: "Rua Haddock Lobo, 359", imagem: {"src": "assets/img/club-municipal.jpg", "alt": "Club Municipal", "fonte": "partiu__lugaresss.docx"} },
    { id: "associacao-atletica-tijuca", nome: "Associação Atlética Tijuca", bairro: "tijuca", lat: -22.919862, lng: -43.231103, categoria: "Esportes", descricao: "A Associação Atlética Tijuca é uma instituição esportiva e recreativa localizada na Rua Barão de Mesquita, que integra a tradição de clubes de bairro do Rio de Janeiro. Espaços como esse desempenham um papel importante na promoção da prática esportiva, do lazer e da convivência comunitária, oferecendo oportunidades para atividades físicas e encontros entre moradores. Sua presença contribui para a história associativa e esportiva da Tijuca, marcada pela participação de clubes e organizações locais na vida social do bairro.", importancia: null, endereco: "Rua Barão de Mesquita, 149", imagem: {"src": "assets/img/associacao-atletica-tijuca.jpg", "alt": "Associação Atlética Tijuca", "fonte": "partiu__lugaresss.docx"} },
    { id: "country-club-da-tijuca", nome: "Country Club da Tijuca", bairro: "tijuca", lat: -22.936007, lng: -43.238982, categoria: "Esportes", descricao: "Localizado na Rua Uruguai, o Country Club da Tijuca é um espaço esportivo, recreativo e social que integra a tradição dos clubes particulares da região. Com instalações voltadas ao lazer e à prática de atividades físicas, o clube oferece aos seus associados oportunidades de convivência e participação em diferentes modalidades esportivas. Sua presença contribui para a diversidade de espaços de esporte e recreação da Tijuca, reforçando a importância dessas instituições para a vida comunitária do bairro.", importancia: null, endereco: "Rua Uruguai, 574", imagem: {"src": "assets/img/country-club-da-tijuca.jpg", "alt": "Country Club da Tijuca", "fonte": "partiu__lugaresss.docx"} },
    { id: "maracana", nome: "Maracanã", bairro: "tijuca", lat: -22.911876, lng: -43.230297, categoria: "Esportes", descricao: "Inaugurado em 16 de junho de 1950 para receber partidas da Copa do Mundo daquele ano, o Estádio Jornalista Mário Filho, conhecido mundialmente como Maracanã, é um dos principais símbolos do esporte brasileiro. Localizado no bairro de mesmo nome, foi palco de acontecimentos históricos do futebol, incluindo a final da Copa do Mundo de 1950 e a decisão da Copa de 2014. Ao longo das décadas, recebeu grandes clubes, seleções e alguns dos maiores jogadores da história do futebol. Além de sua importância esportiva, o estádio também representa um marco arquitetônico e cultural do Rio de Janeiro, tendo passado por reformas e modernizações para acompanhar as transformações do esporte.", importancia: null, endereco: "Avenida Presidente Castelo Branco, s/n — Maracanã", imagem: {"src": "assets/img/maracana.jpg", "alt": "Maracanã", "fonte": "partiu__lugaresss.docx"} },
    { id: "maracanazinho-ginasio-gilberto-cardoso", nome: "Maracanãzinho — Ginásio Gilberto Cardoso", bairro: "tijuca", lat: -22.91378, lng: -43.229424, categoria: "Esportes", descricao: "Inaugurado em 1954, o Ginásio Gilberto Cardoso, conhecido como Maracanãzinho, é um dos principais espaços esportivos cobertos do Rio de Janeiro. Localizado ao lado do Estádio do Maracanã, foi construído para receber grandes competições e eventos esportivos, especialmente modalidades como vôlei e basquete. Ao longo de sua história, sediou campeonatos nacionais e internacionais, além de importantes partidas da seleção brasileira de voleibol. O ginásio também recebeu eventos culturais e apresentações musicais, consolidando-se como um espaço importante para o esporte e o entretenimento na cidade.", importancia: null, endereco: "Rua Professor Eurico Rabelo, s/n — Maracanã", imagem: {"src": "assets/img/maracanazinho-ginasio-gilberto-cardoso.jpg", "alt": "Maracanãzinho — Ginásio Gilberto Cardoso", "fonte": "partiu__lugaresss.docx"} },
    { id: "clube-monte-sinai", nome: "Clube Monte Sinai", bairro: "tijuca", lat: -22.918987, lng: -43.223473, categoria: "Esportes", descricao: "Localizado na Rua São Francisco Xavier, na Tijuca, o Clube Monte Sinai é uma instituição social, cultural e esportiva ligada à comunidade judaica do Rio de Janeiro. O clube oferece espaços e atividades voltados ao esporte, ao lazer e à convivência, além de promover iniciativas culturais e comunitárias. Sua trajetória representa a participação das associações comunitárias na construção da vida social e esportiva da cidade, funcionando como um importante ponto de encontro para seus associados e frequentadores.", importancia: null, endereco: "Rua São Francisco Xavier, 104 — Tijuca", imagem: {"src": "assets/img/clube-monte-sinai.jpg", "alt": "Clube Monte Sinai", "fonte": "partiu__lugaresss.docx"} },
    { id: "aabb-tijuca", nome: "AABB Tijuca", bairro: "tijuca", lat: -22.919257, lng: -43.213666, categoria: "Esportes", descricao: "A Associação Atlética Banco do Brasil (AABB) é uma rede de clubes recreativos e esportivos criada para promover o esporte, o lazer e a integração social. A unidade indicada na Tijuca integra essa tradição associativa, que se desenvolveu em diferentes regiões do país a partir da comunidade de funcionários do Banco do Brasil. As AABBs são conhecidas pela oferta de atividades esportivas, espaços de convivência e iniciativas recreativas, contribuindo para a valorização da prática de exercícios físicos e do convívio comunitário.", importancia: null, endereco: "Rua Haddock Lobo, 227 — Tijuca", imagem: {"src": "assets/img/aabb-tijuca.jpg", "alt": "AABB Tijuca", "fonte": "partiu__lugaresss.docx"} },
    { id: "casa-granado", nome: "Casa Granado", bairro: "tijuca", lat: -22.922801, lng: -43.231502, categoria: "História/Patrimônio", descricao: "A Casa Granado, localizada na Rua Conde de Bonfim, é um imóvel de importância histórica e arquitetônica para a Tijuca. Seu reconhecimento como patrimônio cultural municipal, por meio do Decreto nº 14.587, de 1996, demonstra a relevância da preservação de construções que ajudam a contar a história da ocupação e do desenvolvimento urbano do bairro. O local integra o conjunto de referências históricas que ajudam a preservar a memória da região.", importancia: null, endereco: "Rua Conde de Bonfim, 300", imagem: {"src": "assets/img/casa-granado.jpg", "alt": "Casa Granado", "fonte": "partiu__lugaresss.docx"} },
    { id: "palacete-da-rua-conde-de-bonfim", nome: "Palacete da Rua Conde de Bonfim", bairro: "tijuca", lat: -22.93519, lng: -43.244253, categoria: "História/Patrimônio", descricao: "O Palacete da Rua Conde de Bonfim, situado no número 824, é um importante exemplar da arquitetura residencial do início do século XX na Tijuca. Sua construção apresenta características do estilo eclético, bastante presente nas residências de famílias abastadas daquele período. O imóvel foi reconhecido como patrimônio cultural municipal em 1995, sendo preservado por representar uma fase importante da expansão e da transformação urbana do bairro.", importancia: null, endereco: "Rua Conde de Bonfim, 824", imagem: {"src": "assets/img/palacete-da-rua-conde-de-bonfim.jpg", "alt": "Palacete da Rua Conde de Bonfim", "fonte": "partiu__lugaresss.docx"} },
    { id: "avenida-mariana-avenida-anna-e-sobrados", nome: "Avenida Mariana, Avenida Anna e Sobrados", bairro: "tijuca", lat: -22.919067, lng: -43.23049, categoria: "História/Patrimônio", descricao: "O conjunto formado pela Avenida Mariana, pela Avenida Anna e pelos sobrados da Rua Barão de Mesquita representa um importante registro da arquitetura residencial e da formação urbana da Tijuca. As construções preservam características de antigas vilas e residências que marcaram o desenvolvimento do bairro, permitindo observar diferentes formas de ocupação e organização dos espaços urbanos. O conjunto foi tombado definitivamente pelo município em 1986, reconhecendo seu valor histórico e arquitetônico.", importancia: null, endereco: "Rua Barão de Mesquita, 117, 125 e 127" },
    { id: "praca-afonso-pena", nome: "Praça Afonso Pena", bairro: "tijuca", lat: -22.91783, lng: -43.2181, categoria: "História/Patrimônio", descricao: "A Praça Afonso Pena é um dos espaços públicos tradicionais da Tijuca e desempenha um papel importante na convivência e na vida cotidiana dos moradores. Cercada por ruas movimentadas e estabelecimentos comerciais, a praça funciona como ponto de encontro, circulação e lazer, além de contribuir para a organização urbana da região. Sua presença acompanha a história de crescimento e transformação da Tijuca, mantendo a função de espaço de convivência em meio à cidade.", importancia: null, endereco: "Praça Afonso Pena", imagem: {"src": "assets/img/praca-afonso-pena.jpg", "alt": "Praça Afonso Pena", "fonte": "partiu__lugaresss.docx"} },
    { id: "praca-comandante-xavier-de-brito", nome: "Praça Comandante Xavier de Brito", bairro: "tijuca", lat: -22.931344, lng: -43.243696, categoria: "História/Patrimônio", descricao: "Conhecida popularmente como Praça dos Cavalinhos, a Praça Comandante Xavier de Brito é um espaço tradicional de lazer e convivência na Tijuca. Ajardinada em 1928, a praça recebeu o nome em homenagem a uma figura ligada à história militar brasileira. Seu apelido está associado aos passeios a cavalo e de charrete oferecidos nas proximidades, tradição que marcou a identidade do local. Com sua arborização, áreas de descanso e atividades de lazer, a praça permanece como uma referência da vida comunitária do bairro.", importancia: null, endereco: "Praça Comandante Xavier de Brito", imagem: {"src": "assets/img/praca-comandante-xavier-de-brito.jpg", "alt": "Praça Comandante Xavier de Brito", "fonte": "partiu__lugaresss.docx"} },
    { id: "conjunto-de-imoveis-da-rua-professor-gabizo", nome: "Conjunto de imóveis da Rua Professor Gabizo", bairro: "tijuca", lat: -22.916666, lng: -43.221782, categoria: "História/Patrimônio", descricao: "O conjunto de imóveis da Rua Professor Gabizo, nos números 225, 227 e 243, reúne construções residenciais que representam diferentes características da arquitetura carioca do início do século XX. Entre elas estão duas residências geminadas de dois pavimentos, com referências ao estilo neocolonial hispânico, e outra residência que conserva elementos típicos das moradias das classes mais abastadas daquele período. Reconhecidos como patrimônio cultural municipal, os imóveis ajudam a preservar a memória da antiga paisagem residencial da Tijuca.", importancia: null, endereco: "Rua Professor Gabizo, 225/227 e 243", imagem: {"src": "assets/img/conjunto-de-imoveis-da-rua-professor-gabizo.jpg", "alt": "Conjunto de imóveis da Rua Professor Gabizo", "fonte": "partiu__lugaresss.docx"} },
    { id: "monumento-ao-almirante-cochrane", nome: "Monumento ao Almirante Cochrane", bairro: "tijuca", lat: -22.922213, lng: -43.231131, categoria: "História/Patrimônio", descricao: "O Monumento ao Almirante Cochrane é uma referência histórica localizada na Rua Almirante Cochrane, na Tijuca. Seu nome homenageia Thomas Cochrane, oficial da Marinha britânica que participou de conflitos ligados aos processos de independência de países da América do Sul, incluindo o Brasil. O monumento integra a memória urbana do bairro e ajuda a lembrar a presença de personagens estrangeiros em episódios importantes da história política e militar brasileira.", importancia: null, endereco: "Rua Almirante Cochrane, 266", imagem: {"src": "assets/img/monumento-ao-almirante-cochrane.jpg", "alt": "Monumento ao Almirante Cochrane", "fonte": "partiu__lugaresss.docx"} },
    { id: "ponte-de-cantaria-sobre-o-rio-sao-joao", nome: "Ponte de Cantaria sobre o Rio São João", bairro: "alto-da-boa-vista", lat: -22.953774, lng: -43.263843, categoria: "História/Patrimônio", descricao: "A Ponte de Cantaria sobre o Rio São João é uma construção histórica localizada na Estrada Velha da Tijuca, no Alto da Boa Vista. Feita em cantaria, técnica que utiliza pedras trabalhadas e encaixadas para formar estruturas, a ponte representa antigas soluções de engenharia utilizadas na construção de caminhos e passagens. Seu valor está relacionado tanto à técnica construtiva quanto à memória dos antigos percursos que conectavam diferentes áreas do maciço da Tijuca. O bem foi tombado definitivamente pelo município em 1986.", importancia: null, endereco: "Estrada Velha da Tijuca, em frente ao nº 1.251 — Alto da Boa Vista", imagem: {"src": "assets/img/ponte-de-cantaria-sobre-o-rio-sao-joao.jpg", "alt": "Ponte de Cantaria sobre o Rio São João", "fonte": "partiu__lugaresss.docx"} },
    { id: "capela-mayrink", nome: "Capela Mayrink", bairro: "alto-da-boa-vista", lat: -22.95674, lng: -43.278023, categoria: "História/Patrimônio", descricao: "A Capela Mayrink é uma pequena construção religiosa localizada em meio à Floresta da Tijuca. Foi erguida em 1855 por iniciativa do Visconde Antônio Alves Souto, inicialmente com o nome de Nossa Senhora de Belém. Em 1896, após a aquisição da propriedade pelo Conselheiro Francisco de Paula Mayrink, passou a ser conhecida pelo nome atual. Um de seus destaques é o conjunto de réplicas de pinturas de Cândido Portinari presentes no altar, cujos originais estão sob a guarda do Museu Nacional de Belas Artes. A capela reúne valor religioso, artístico e histórico em meio à paisagem natural do parque.", importancia: null, endereco: "Estrada da Vista Chinesa, Floresta da Tijuca", imagem: {"src": "assets/img/capela-mayrink.jpg", "alt": "Capela Mayrink", "fonte": "partiu__lugaresss.docx"} },
    { id: "museu-do-acude", nome: "Museu do Açude", bairro: "alto-da-boa-vista", lat: -22.964527, lng: -43.28221, categoria: "História/Patrimônio", descricao: "O Museu do Açude, localizado no Alto da Boa Vista, integra os Museus Castro Maya e ocupa uma antiga residência da família de Raymundo Ottoni de Castro Maya. A propriedade foi adquirida em 1913 e passou por reformas na década de 1920, incorporando características da arquitetura neocolonial. Transformada em museu e aberta ao público em 1964, a antiga residência passou a abrigar importantes coleções de arte, incluindo azulejos, objetos decorativos e peças de diferentes culturas. Cercado pela Floresta da Tijuca, o espaço aproxima patrimônio artístico, arquitetura e natureza.", importancia: null, endereco: "Estrada do Açude, 764 — Alto da Boa Vista", imagem: {"src": "assets/img/museu-do-acude.jpg", "alt": "Museu do Açude", "fonte": "partiu__lugaresss.docx"} },
    { id: "largo-augusto-elisio", nome: "Largo Augusto Elísio", bairro: "tijuca", lat: -22.932554, lng: -43.241022, categoria: "História/Patrimônio", descricao: "O Largo Augusto Elísio é um espaço urbano localizado na região da Rua Uruguai, na Tijuca. Como parte da paisagem cotidiana do bairro, o largo contribui para a organização dos espaços de circulação e convivência, representando também a presença de logradouros tradicionais na formação urbana da região. Sua preservação e identificação ajudam a valorizar a memória dos espaços públicos que compõem a história dos bairros cariocas.", importancia: null, endereco: "Rua Uruguai — Tijuca", imagem: {"src": "assets/img/largo-augusto-elisio.jpg", "alt": "Largo Augusto Elísio", "fonte": "partiu__lugaresss.docx"} },
    { id: "casa-de-arte-e-cultura-luiz-januario", nome: "Casa de Arte e Cultura Luiz Januário", bairro: "tijuca", lat: -22.922535, lng: -43.220235, categoria: "História/Patrimônio", descricao: "A Casa de Arte e Cultura Luiz Januário é um espaço cultural independente localizado na Tijuca, dedicado à formação artística e à realização de atividades culturais. Instalada em um casarão de arquitetura antiga, a instituição foi idealizada pela família Januário e começou a funcionar em 2018. Sua proposta reúne cursos, oficinas, palestras, apresentações e eventos de diferentes linguagens, como música, dança, teatro e artes visuais. O espaço também contribui para ampliar o acesso à cultura na Zona Norte do Rio de Janeiro, valorizando a produção artística e a convivência comunitária.", importancia: null, endereco: "Rua Delgado de Carvalho, 41 — Tijuca", imagem: {"src": "assets/img/casa-de-arte-e-cultura-luiz-januario.jpg", "alt": "Casa de Arte e Cultura Luiz Januário", "fonte": "partiu__lugaresss.docx"} },
    { id: "antiga-fabrica-de-tecidos-cruzeiro", nome: "Antiga Fábrica de Tecidos Cruzeiro", bairro: "tijuca", lat: -22.923465, lng: -43.230767, categoria: "História/Patrimônio", descricao: "A antiga Fábrica de Tecidos Cruzeiro está relacionada ao processo de industrialização que marcou o Andaraí e outras áreas da Grande Tijuca entre o final do século XIX e o início do século XX. Incorporada à Companhia América Fabril no processo de expansão da empresa, a unidade iniciou suas atividades em 1895, após passar por reformas. Sua história representa a importância da indústria têxtil para o crescimento econômico da região e para a formação de uma paisagem urbana marcada por fábricas, trabalhadores e transformações sociais.", importancia: null, endereco: "Andaraí — Grande Tijuca", imagem: {"src": "assets/img/antiga-fabrica-de-tecidos-cruzeiro.jpg", "alt": "Antiga Fábrica de Tecidos Cruzeiro", "fonte": "partiu__lugaresss.docx"} },
    { id: "antiga-fabrica-de-tecidos-confianca", nome: "Antiga Fábrica de Tecidos Confiança", bairro: "tijuca", lat: -22.917214, lng: -43.23806, categoria: "História/Patrimônio", descricao: "A antiga Fábrica de Tecidos Confiança, localizada na região da Aldeia Campista, foi inaugurada em 1885 e teve papel importante no desenvolvimento industrial e urbano da Grande Tijuca. A fábrica impulsionou a formação de uma comunidade operária em seu entorno, contribuindo para o surgimento de moradias, serviços e espaços de convivência ligados à vida dos trabalhadores. Seu funcionamento também ficou marcado pelos apitos que anunciavam os horários de trabalho, lembrados na canção “Três Apitos”, de Noel Rosa. Encerrada em 1964, a antiga fábrica permanece como uma referência da memória industrial e cultural do Rio de Janeiro.", importancia: null, endereco: "Aldeia Campista / Vila Isabel — Grande Tijuca", imagem: {"src": "assets/img/antiga-fabrica-de-tecidos-confianca.jpg", "alt": "Antiga Fábrica de Tecidos Confiança", "fonte": "partiu__lugaresss.docx"} },
    { id: "praca-saens-pena-antiga-fabrica-das-chitas", nome: "Praça Saens Peña — antiga Fábrica das Chitas", bairro: "tijuca", lat: -22.92386, lng: -43.232532, categoria: "Indústria/Urbanização", descricao: "A Praça Saens Peña está localizada em uma área que teve papel importante no início da urbanização da Tijuca. Na década de 1820, funcionava nas proximidades a Fábrica das Chitas, uma das primeiras manufaturas da região, dedicada à estamparia de tecidos de algodão, especialmente os chamados tecidos de chita. A atividade industrial deu nome ao antigo Largo da Fábrica, que posteriormente se transformou na atual praça. Em 1911, o espaço recebeu oficialmente o nome de Praça Sáenz Peña, em homenagem aos presidentes argentinos Luis e Roque Sáenz Peña. Ao longo do século XX, tornou-se um dos principais centros comerciais, culturais e de convivência do bairro.", importancia: null, endereco: "Praça Saens Peña", imagem: {"src": "assets/img/praca-saens-pena-antiga-fabrica-das-chitas.jpg", "alt": "Praça Saens Peña — antiga Fábrica das Chitas", "fonte": "partiu__lugaresss.docx"} },
    { id: "antiga-fabrica-de-fumos-borel", nome: "Antiga Fábrica de Fumos Borel", bairro: "tijuca", lat: -22.937769, lng: -43.254307, categoria: "Indústria/Urbanização", descricao: "A antiga Fábrica de Fumos Borel e Companhia foi um dos estabelecimentos industriais que marcaram a história da Tijuca no século XIX, com atividades relacionadas à produção de produtos derivados do tabaco. Fundada em 1854, a fábrica contribuiu para a movimentação econômica da região e para a formação de uma paisagem urbana ligada ao trabalho industrial. Sua história também está associada à origem do nome Borel, posteriormente utilizado para identificar a comunidade localizada nas proximidades. O estabelecimento representa uma fase em que a Tijuca reunia fábricas, propriedades rurais e áreas residenciais em processo de expansão.", importancia: null, endereco: "Região do Borel / Usina" },
    { id: "antiga-fabrica-de-rape-paulo-cordeiro-souza-cruz", nome: "Antiga Fábrica de Rapé Paulo Cordeiro / Souza Cruz", bairro: "tijuca", lat: -22.923603, lng: -43.232841, categoria: "Indústria/Urbanização", descricao: "A antiga fábrica de rapé Paulo Cordeiro está relacionada à história da indústria do tabaco na Tijuca. No início do século XX, o estabelecimento foi adquirido por Albino Souza Cruz, que o transformou em uma fábrica de cigarros, dando origem a uma importante etapa da expansão industrial da empresa na região. A unidade passou a integrar a trajetória da Souza Cruz no Rio de Janeiro e permaneceu como referência da atividade fabril na área da Usina. Sua história ajuda a compreender as transformações econômicas e urbanas provocadas pela presença de grandes estabelecimentos industriais no bairro.", importancia: null, endereco: "Rua Conde de Bonfim — Tijuca" },
    { id: "antiga-fabrica-de-tecidos-maracana", nome: "Antiga Fábrica de Tecidos Maracanã", bairro: "tijuca", lat: -22.923317, lng: -43.23081, categoria: "Indústria/Urbanização", descricao: "A antiga Fábrica de Tecidos Maracanã integrou o processo de desenvolvimento da indústria têxtil na região da Grande Tijuca, que ganhou força entre o final do século XIX e o início do século XX. Esse setor teve papel importante na economia carioca, gerando empregos e contribuindo para a expansão dos bairros próximos às unidades fabris. A presença de estabelecimentos desse tipo transformou a paisagem local e ajudou a consolidar uma identidade urbana ligada ao trabalho industrial. A memória da fábrica faz parte da história da industrialização da região, embora os detalhes específicos sobre sua trajetória ainda precisem de confirmação documental.", importancia: null, endereco: "Região da Tijuca / Maracanã", imagem: {"src": "assets/img/antiga-fabrica-de-tecidos-maracana.jpg", "alt": "Antiga Fábrica de Tecidos Maracanã", "fonte": "partiu__lugaresss.docx"} },
    { id: "antigos-bondes-eletricos-da-tijuca-eixo-da-rua-conde-de-bonfim", nome: "Antigos bondes elétricos da Tijuca / eixo da Rua Conde de Bonfim", bairro: "tijuca", lat: -22.931382, lng: -43.239535, categoria: "Indústria/Urbanização", descricao: "Os antigos bondes elétricos tiveram papel fundamental na transformação da Tijuca e na integração do bairro ao restante da cidade. A eletrificação do transporte na região começou a ser planejada na década de 1890, e a ligação entre a Tijuca e o Alto da Boa Vista entrou em funcionamento em 1898, após a construção de uma usina termoelétrica nas proximidades da atual região da Usina. Os bondes circulavam por vias como a Rua Conde de Bonfim e facilitaram o deslocamento de moradores, trabalhadores e visitantes, contribuindo para o crescimento urbano e comercial do bairro. O sistema permaneceu em funcionamento até a segunda metade do século XX, deixando marcas importantes na memória e na paisagem da Tijuca.", importancia: null, endereco: "Rua Conde de Bonfim e arredores", imagem: {"src": "assets/img/antigos-bondes-eletricos-da-tijuca-eixo-da-rua-conde-de-bonfim.jpg", "alt": "Antigos bondes elétricos da Tijuca / eixo da Rua Conde de Bonfim", "fonte": "partiu__lugaresss.docx"} },
    { id: "parque-nacional-da-tijuca-floresta-da-tijuca", nome: "Parque Nacional da Tijuca — Floresta da Tijuca", bairro: "alto-da-boa-vista", lat: -22.95581, lng: -43.27986, categoria: "Natureza/Paisagens", descricao: "O Parque Nacional da Tijuca é uma das maiores florestas urbanas replantadas do mundo e um dos principais patrimônios naturais do Rio de Janeiro. Criado em 1961, protege uma extensa área de Mata Atlântica, com grande diversidade de plantas e animais, nascentes, trilhas e construções históricas. Sua história está diretamente ligada ao reflorestamento iniciado no século XIX, após o avanço das plantações de café e do desmatamento comprometerem a vegetação e os recursos hídricos da região. A recuperação foi determinada por Dom Pedro II em 1861 e teve como um de seus principais responsáveis o major Manuel Gomes Archer. Atualmente, o parque é fundamental para a conservação ambiental, o equilíbrio climático e o lazer da população carioca.\n\nA Floresta da Tijuca é uma das principais áreas de preservação ambiental do Rio de Janeiro e integra o Parque Nacional da Tijuca. Sua paisagem atual é resultado de um importante processo de recuperação ambiental iniciado no século XIX, depois que o desmatamento provocado principalmente pelas plantações de café comprometeu a vegetação e os recursos hídricos da região. A partir de 1861, durante o governo de Dom Pedro II, foram organizadas ações de reflorestamento, inicialmente conduzidas pelo major Manuel Gomes Archer, com a participação de pessoas negras escravizadas. Atualmente, a floresta representa um patrimônio natural e histórico, reunindo biodiversidade, trilhas, construções antigas e paisagens que fazem parte da memória carioca.", importancia: null, endereco: "Estrada da Cascatinha, 850 — Alto da Boa Vista", imagem: {"src": "assets/img/parque-nacional-da-tijuca-floresta-da-tijuca.jpg", "alt": "Parque Nacional da Tijuca — Floresta da Tijuca", "fonte": "partiu__lugaresss.docx"} },
    { id: "vista-chinesa", nome: "Vista Chinesa", bairro: "alto-da-boa-vista", lat: -22.97121, lng: -43.249583, categoria: "Natureza/Paisagens", descricao: "A Vista Chinesa é um dos mirantes mais conhecidos do Rio de Janeiro, localizada na Floresta da Tijuca. Construída no início do século XX, durante a administração do prefeito Pereira Passos, a estrutura foi projetada em estilo orientalista, com referências à arquitetura chinesa, como forma de homenagear os trabalhadores chineses que participaram da introdução do cultivo de chá no Brasil. Do mirante, é possível observar importantes paisagens da cidade, incluindo a Lagoa Rodrigo de Freitas, o Cristo Redentor e o Pão de Açúcar. Além de seu valor arquitetônico e histórico, o local se tornou um dos pontos tradicionais de contemplação da paisagem carioca.", importancia: null, endereco: "Estrada da Vista Chinesa — Alto da Boa Vista", imagem: {"src": "assets/img/vista-chinesa.jpg", "alt": "Vista Chinesa", "fonte": "partiu__lugaresss.docx"} },
    { id: "cascatinha-taunay", nome: "Cascatinha Taunay", bairro: "alto-da-boa-vista", lat: -22.95587, lng: -43.279978, categoria: "Natureza/Paisagens", descricao: "A Cascatinha Taunay é uma das quedas d’água mais conhecidas da Floresta da Tijuca e um dos principais cartões-postais do parque. Com aproximadamente 35 metros de altura, recebe esse nome em homenagem ao pintor francês Nicolas-Antoine Taunay, integrante da Missão Artística Francesa, que viveu na região no início do século XIX. A cachoeira está situada em meio à vegetação da Mata Atlântica e possui uma ponte de pedra em sua parte inferior, formando um conjunto paisagístico bastante conhecido pelos visitantes. O local representa a integração entre patrimônio natural, história e paisagem.", importancia: null, endereco: "Floresta da Tijuca — Alto da Boa Vista", imagem: {"src": "assets/img/cascatinha-taunay.jpg", "alt": "Cascatinha Taunay", "fonte": "partiu__lugaresss.docx"} },
    { id: "acude-da-solidao", nome: "Açude da Solidão", bairro: "alto-da-boa-vista", lat: -22.961929, lng: -43.288996, categoria: "Natureza/Paisagens", descricao: "O Açude da Solidão é um pequeno reservatório localizado na Floresta da Tijuca, cercado pela vegetação da Mata Atlântica. Construído no século XIX, integra o conjunto de obras relacionadas ao aproveitamento e à preservação dos recursos hídricos da região. Seu ambiente tranquilo, marcado pela presença da água e pela arborização ao redor, oferece aos visitantes um espaço de contemplação e contato com a natureza. O açude também ajuda a contar a história da ocupação e das intervenções humanas na floresta, que passou por um importante processo de recuperação ambiental.", importancia: null, endereco: "Estrada do Bom Retiro, 1768 — Alto da Boa Vista", imagem: {"src": "assets/img/acude-da-solidao.jpg", "alt": "Açude da Solidão", "fonte": "partiu__lugaresss.docx"} },
    { id: "pico-da-tijuca", nome: "Pico da Tijuca", bairro: "alto-da-boa-vista", lat: -22.943063, lng: -43.286372, categoria: "Natureza/Paisagens", descricao: "Com aproximadamente 1.022 metros de altitude, o Pico da Tijuca é o ponto mais alto do Parque Nacional da Tijuca e um dos principais destinos para caminhadas e montanhismo na cidade. Seu acesso é feito por uma trilha que atravessa trechos preservados de Mata Atlântica e termina em uma escadaria esculpida na rocha, construída durante a década de 1920. Do alto, os visitantes encontram uma vista panorâmica de diferentes regiões do Rio de Janeiro, incluindo a Zona Norte, a Zona Sul e parte da Baixada Fluminense. O pico representa a riqueza natural do maciço da Tijuca e a importância da conservação de suas áreas florestais.", importancia: null, endereco: "Parque Nacional da Tijuca — Alto da Boa Vista", imagem: {"src": "assets/img/pico-da-tijuca.jpg", "alt": "Pico da Tijuca", "fonte": "partiu__lugaresss.docx"} },
    { id: "mesa-do-imperador", nome: "Mesa do Imperador", bairro: "alto-da-boa-vista", lat: -22.968609, lng: -43.258499, categoria: "Natureza/Paisagens", descricao: "A Mesa do Imperador é um mirante histórico situado na Floresta da Tijuca, ao longo da Estrada da Vista Chinesa. O espaço recebeu esse nome por ter sido utilizado como local de refeições e encontros durante passeios realizados por integrantes da família imperial e da sociedade carioca no século XIX. A estrutura de pedra e o ambiente arborizado preservam características de uma época em que a floresta era frequentada como área de descanso e contemplação. Atualmente, o local é conhecido pela vista da paisagem da cidade e por seu valor histórico, integrando o patrimônio cultural e natural do parque.\n\nA Mesa do Imperador é um dos recantos históricos e paisagísticos da Floresta da Tijuca, no caminho da Vista Chinesa. O local era utilizado por integrantes da nobreza e da burguesia para encontros e refeições ao ar livre, tendo recebido também a visita de Dom Pedro II durante seus passeios pela floresta. Com o passar do tempo, tornou-se um ponto tradicional de contemplação, conhecido pela vista da paisagem carioca e pela relação entre a história da cidade e a preservação ambiental.", importancia: null, endereco: "Estrada da Vista Chinesa — Alto da Boa Vista", imagem: {"src": "assets/img/mesa-do-imperador.jpg", "alt": "Mesa do Imperador", "fonte": "partiu__lugaresss.docx"} },
    { id: "pedra-bonita", nome: "Pedra Bonita", bairro: "alto-da-boa-vista", lat: -22.982708, lng: -43.279159, categoria: "Natureza/Paisagens", descricao: "A Pedra Bonita é uma formação rochosa localizada no Parque Nacional da Tijuca, com aproximadamente 696 metros de altitude. O local é conhecido pela trilha que leva ao seu topo, de onde é possível observar paisagens como a Pedra da Gávea, a orla de São Conrado, a Barra da Tijuca e parte da Zona Sul. A montanha também abriga uma das áreas mais conhecidas de voo livre do Rio de Janeiro, utilizada para a prática de asa-delta e parapente. Sua combinação de paisagens naturais, vegetação preservada e atividades ao ar livre faz da Pedra Bonita um dos pontos de visitação mais conhecidos do parque.", importancia: null, endereco: "Parque Nacional da Tijuca — Alto da Boa Vista", imagem: {"src": "assets/img/pedra-bonita.jpg", "alt": "Pedra Bonita", "fonte": "partiu__lugaresss.docx"} },
    { id: "pedra-da-gavea", nome: "Pedra da Gávea", bairro: "tijuca", lat: -22.99679, lng: -43.285023, categoria: "Natureza/Paisagens", descricao: "A Pedra da Gávea é uma das formações rochosas mais impressionantes do Parque Nacional da Tijuca, com aproximadamente 844 metros de altitude. Localizada entre os bairros de São Conrado e Barra da Tijuca, é considerada um dos maiores blocos de granito e gnaisse à beira-mar do mundo. Seu formato característico, que lembra um rosto esculpido na rocha, contribuiu para o surgimento de diversas histórias e lendas populares. O local é muito procurado por praticantes de montanhismo e oferece uma vista ampla do litoral e de diferentes regiões da cidade. Além de seu valor paisagístico, a Pedra da Gávea é um importante símbolo natural do Rio de Janeiro.", importancia: null, endereco: "Parque Nacional da Tijuca — São Conrado", imagem: {"src": "assets/img/pedra-da-gavea.jpg", "alt": "Pedra da Gávea", "fonte": "partiu__lugaresss.docx"} },
    { id: "bico-do-papagaio", nome: "Bico do Papagaio", bairro: "alto-da-boa-vista", lat: -22.949014, lng: -43.301203, categoria: "Natureza/Paisagens", descricao: "O Bico do Papagaio é uma formação rochosa localizada na Floresta da Tijuca, conhecida pelo formato pontudo que lembra o bico de uma ave e que deu origem ao seu nome. Com cerca de 989 metros de altitude, é um dos pontos tradicionais para caminhadas e montanhismo dentro do Parque Nacional da Tijuca. O acesso é feito por trilhas em meio à vegetação da Mata Atlântica, que levam até áreas de contemplação com vistas da floresta e de partes da cidade. O local destaca a diversidade geológica e paisagística do maciço da Tijuca.", importancia: null, endereco: "Floresta da Tijuca — Alto da Boa Vista", imagem: {"src": "assets/img/bico-do-papagaio.jpg", "alt": "Bico do Papagaio", "fonte": "partiu__lugaresss.docx"} },
    { id: "cachoeira-das-almas", nome: "Cachoeira das Almas", bairro: "alto-da-boa-vista", lat: -22.948735, lng: -43.286415, categoria: "Natureza/Paisagens", descricao: "A Cachoeira das Almas é uma das quedas d’água tradicionais da Floresta da Tijuca, localizada em uma área cercada por vegetação nativa. Seu nome está associado a relatos históricos e populares sobre a presença de pessoas escravizadas que teriam utilizado a região durante o período colonial, embora a origem exata da denominação não seja consensual. A cachoeira é procurada por visitantes que desejam aproveitar o ambiente natural e conhecer os cursos d’água que atravessam a floresta. Sua presença também evidencia a importância da proteção das nascentes e dos recursos hídricos do parque.", importancia: null, endereco: "Floresta da Tijuca — Alto da Boa Vista", imagem: {"src": "assets/img/cachoeira-das-almas.jpg", "alt": "Cachoeira das Almas", "fonte": "partiu__lugaresss.docx"} },
    { id: "cachoeira-do-horto", nome: "Cachoeira do Horto", bairro: "alto-da-boa-vista", lat: -22.965217, lng: -43.245946, categoria: "Natureza/Paisagens", descricao: "A Cachoeira do Horto está localizada na região do Horto, aos pés do maciço da Tijuca, e é um dos atrativos naturais procurados por moradores e visitantes que desejam conhecer as áreas verdes da cidade. Cercada pela vegetação da Mata Atlântica, a cachoeira forma pequenas quedas e poços naturais, compondo um ambiente de contato direto com a natureza. Seu entorno integra uma área de grande importância ambiental, marcada pela presença de nascentes e cursos d’água que contribuem para a manutenção do ecossistema local. O espaço também representa a importância da conservação das áreas naturais próximas às regiões urbanizadas do Rio de Janeiro.", importancia: null, endereco: "Estrada da Vista Chinesa — Alto da Boa Vista", imagem: {"src": "assets/img/cachoeira-do-horto.jpg", "alt": "Cachoeira do Horto", "fonte": "partiu__lugaresss.docx"} },
    { id: "paineiras", nome: "Paineiras", bairro: "alto-da-boa-vista", lat: -22.946738, lng: -43.217538, categoria: "Natureza/Paisagens", descricao: "As Paineiras são uma área tradicional de visitação do Parque Nacional da Tijuca, conhecida por suas paisagens, trilhas e vistas panorâmicas do Rio de Janeiro. A região ganhou destaque histórico no século XIX, quando passou a ser frequentada como local de passeio e descanso, especialmente por sua altitude e clima mais ameno. Atualmente, é um dos acessos utilizados por visitantes que seguem em direção ao Corcovado e ao Cristo Redentor, além de oferecer contato com a vegetação da Mata Atlântica e mirantes naturais. O local reúne importância histórica, turística e ambiental, fazendo parte da memória dos passeios pela floresta.", importancia: null, endereco: "Estrada das Paineiras — Alto da Boa Vista", imagem: {"src": "assets/img/paineiras.jpg", "alt": "Paineiras", "fonte": "partiu__lugaresss.docx"} },
    { id: "mirante-do-excelsior", nome: "Mirante do Excelsior", bairro: "alto-da-boa-vista", lat: -22.942189, lng: -43.27271, categoria: "Natureza/Paisagens", descricao: "O Mirante do Excelsior é um dos pontos de contemplação da Floresta da Tijuca, situado em uma área elevada do Parque Nacional da Tijuca. O local oferece uma vista ampla de parte da paisagem carioca e permite observar a relação entre a vegetação preservada do maciço e a ocupação urbana ao redor. Seu acesso é feito por trilhas e caminhos do parque, tornando-o um destino procurado por visitantes interessados em caminhadas e observação da natureza. O mirante também integra o conjunto de espaços históricos de visitação da floresta, que há gerações atrai cariocas em busca de lazer e contato com o ambiente natural.", importancia: null, endereco: "Floresta da Tijuca — Alto da Boa Vista", imagem: {"src": "assets/img/mirante-do-excelsior.jpg", "alt": "Mirante do Excelsior", "fonte": "partiu__lugaresss.docx"} },
    { id: "clarice-lispector", nome: "Clarice Lispector", bairro: "tijuca", lat: -22.912536, lng: -43.21625, categoria: "Personalidades/Memória", descricao: "A Rua Mariz e Barros, na Tijuca, está ligada à adolescência de Clarice Lispector, uma das escritoras mais importantes da literatura brasileira do século XX. Nascida na Ucrânia e criada inicialmente em Recife, Clarice mudou-se com a família para o Rio de Janeiro aos 14 anos e passou parte de sua juventude no bairro. Foi nesse período que começou a construir sua trajetória na cidade, desenvolvendo o interesse pela literatura que marcaria sua obra. A residência da família é uma referência importante para compreender a relação entre a escritora e a Tijuca, bairro que fez parte de sua formação pessoal.", importancia: "A escritora viveu sua adolescência na Tijuca, e o período no bairro faz parte de sua trajetória pessoal e literária", endereco: "Rua Mariz e Barros, 241", imagem: {"src": "assets/img/clarice-lispector.jpg", "alt": "Clarice Lispector", "fonte": "partiu__lugaresss.docx"} },
    { id: "tim-maia", nome: "Tim Maia", bairro: "tijuca", lat: null, lng: null, categoria: "Personalidades/Memória", descricao: "Nascido e criado na Tijuca, Tim Maia é uma das figuras mais marcantes da música brasileira ligadas ao bairro. Conhecido por sua voz inconfundível e por sua contribuição ao soul, ao funk e à música popular brasileira, construiu uma carreira que influenciou gerações de artistas. Em 2015, a Praça Afonso Pena recebeu uma estátua de bronze em sua homenagem, criada pela artista Christina Motta. O monumento celebra a relação do cantor com o bairro onde passou a infância e ajuda a manter viva sua memória na paisagem tijucana.", importancia: "Nascido e eternizado na Tijuca, Tim Maia é uma das figuras mais marcantes da música brasileira ligadas ao bairro. Existe inclusive uma estátua dele na Praça Afonso Pena.", endereco: "Praça Afonso Pena", imagem: {"src": "assets/img/tim-maia.jpg", "alt": "Tim Maia", "fonte": "partiu__lugaresss.docx"} },
    { id: "mario-jorge-lobo-zagallo", nome: "Mário Jorge Lobo Zagallo", bairro: "tijuca", lat: -22.917509, lng: -43.220515, categoria: "Personalidades/Memória", descricao: "A Rua Professor Gabizo, na Tijuca, está relacionada à infância e à juventude de Mário Jorge Lobo Zagallo, um dos maiores nomes da história do futebol brasileiro. Nascido em Maceió, mudou-se ainda bebê para o Rio de Janeiro e cresceu no bairro, onde começou a jogar futebol nas ruas e a frequentar o América Futebol Clube. Ao longo de sua carreira, conquistou quatro Copas do Mundo, sendo duas como jogador, uma como treinador e uma como coordenador técnico. Sua história representa uma ligação importante entre a Tijuca e o desenvolvimento do futebol brasileiro.", importancia: "O tetracampeão mundial de futebol residiu na Tijuca, fazendo parte também da memória esportiva do bairro.", endereco: "Rua Professor Gabizo", imagem: {"src": "assets/img/mario-jorge-lobo-zagallo.jpg", "alt": "Mário Jorge Lobo Zagallo", "fonte": "partiu__lugaresss.docx"} },
    { id: "lucio-rangel", nome: "Lúcio Rangel", bairro: "tijuca", lat: -22.935112, lng: -43.244255, categoria: "Personalidades/Memória", descricao: "Lúcio Rangel foi jornalista, pesquisador, colecionador e crítico musical, reconhecido por sua contribuição ao estudo e à valorização da música popular brasileira. Atuou como diretor e redator da Revista da Música Popular, publicada entre 1954 e 1956, e teve papel importante na preservação da memória musical do país. Seu legado é homenageado na Biblioteca Municipal Lúcio Rangel, instalada no Centro da Música Carioca Artur da Távola, na Rua Conde de Bonfim, 824. Inaugurada em 2024, a biblioteca reúne milhares de livros sobre música brasileira e jazz, incluindo parte do acervo pessoal do pesquisador, doado por sua família.", importancia: "Jornalista, crítico musical e pesquisador, teve seu legado preservado na Biblioteca Municipal Lúcio Rangel, localizada no Centro da Música Carioca Artur da Távola.", endereco: "Rua Conde de Bonfim, 824", imagem: {"src": "assets/img/lucio-rangel.jpg", "alt": "Lúcio Rangel", "fonte": "partiu__lugaresss.docx"} },
    { id: "carlos-seidl", nome: "Carlos Seidl", bairro: "tijuca", lat: -22.921711, lng: -43.21861, categoria: "Personalidades/Memória", descricao: "Carlos Seidl foi médico e sanitarista cuja trajetória está relacionada à história da saúde pública no Rio de Janeiro. Sua ligação com a Tijuca é registrada pela referência à residência localizada na Rua Professor Gabizo, 43, identificada como um lugar de memória associado à sua vida. O registro patrimonial desse endereço contribui para preservar a lembrança de profissionais que participaram da história da medicina e da saúde pública brasileira. Assim, o imóvel representa não apenas uma construção residencial, mas também uma referência à memória de uma personalidade ligada à história da cidade.", importancia: "Médico e sanitarista que viveu nesse endereço; o IRPH registrou o imóvel como lugar de memória ligado a ele.", endereco: "Rua Professor Gabizo, 43", imagem: {"src": "assets/img/carlos-seidl.jpg", "alt": "Carlos Seidl", "fonte": "partiu__lugaresss.docx"} },
    { id: "duque-de-caxias", nome: "Duque de Caxias", bairro: "tijuca", lat: -22.931972, lng: -43.240223, categoria: "Personalidades/Memória", descricao: "Luís Alves de Lima e Silva, conhecido como Duque de Caxias, foi um militar e político brasileiro que teve participação de destaque em conflitos e acontecimentos do período imperial. Sua trajetória também está ligada à Tijuca, onde residiu em um palacete posteriormente ocupado pelo Instituto La-Fayette. A antiga residência representa uma referência da presença de figuras importantes da história nacional na região e contribui para preservar a memória da ocupação residencial da Tijuca durante o século XIX. O local também permite relacionar a história do bairro à formação política e militar do Brasil imperial.", importancia: "Morou em um palacete na Rua Conde de Bonfim, posteriormente ocupado pelo Instituto La-Fayette", endereco: null, imagem: {"src": "assets/img/duque-de-caxias.jpg", "alt": "Duque de Caxias", "fonte": "partiu__lugaresss.docx"} },
    { id: "barao-de-mesquita", nome: "Barão de Mesquita", bairro: "tijuca", lat: -22.920659, lng: -43.219991, categoria: "Personalidades/Memória", descricao: "Jerônimo José de Mesquita, conhecido como Barão de Mesquita, foi um nobre brasileiro ligado à história da aristocracia carioca do século XIX. Sua memória está associada à Tijuca, onde teria residido em um imóvel da Rua Haddock Lobo. A presença de antigas residências de famílias abastadas nessa região ajuda a compreender a formação do bairro, que durante o século XIX reunia chácaras, propriedades rurais e palacetes. A própria denominação de Barão de Mesquita também permanece na geografia da Grande Tijuca, preservando a lembrança dessa figura histórica", importancia: "Morou na Rua Haddock Lobo, nº 416. A própria rua recebeu o nome em homenagem a ele.", endereco: null, imagem: {"src": "assets/img/barao-de-mesquita.jpg", "alt": "Barão de Mesquita", "fonte": "partiu__lugaresss.docx"} },
    { id: "synval-silva", nome: "Synval Silva", bairro: "tijuca", lat: -22.943297, lng: -43.241263, categoria: "Personalidades/Memória", descricao: "Synval Silva foi compositor brasileiro que construiu parte importante de sua trajetória musical no Rio de Janeiro. Nascido em Juiz de Fora, mudou-se para a capital em 1930 e passou a morar no Morro da Formiga, na região da Tijuca. Suas composições ganharam projeção nacional, especialmente por meio de gravações feitas por Carmen Miranda, como “Adeus, Batucada” e “Alvorada”. Também manteve ligação com a escola de samba Império da Tijuca e recebeu o título de Bacharel do Samba, concedido pelo Museu da Imagem e do Som. Sua história representa a importância das comunidades da Grande Tijuca para a formação da cultura musical carioca.", importancia: "Viveu no Morro da Formiga de 1930 a 1994. É uma ligação interessante porque conecta a memória musical diretamente com uma comunidade da Grande Tijuca.", endereco: null, imagem: {"src": "assets/img/synval-silva.jpg", "alt": "Synval Silva", "fonte": "partiu__lugaresss.docx"} },
    { id: "mosteiro-de-sao-bento", nome: "Mosteiro de São Bento", bairro: "centro", lat: -22.896879, lng: -43.177799, categoria: "Religião", descricao: "Fundado em 1590 por monges beneditinos vindos da Bahia, o Mosteiro de São Bento é um dos conjuntos religiosos e arquitetônicos mais importantes do Rio de Janeiro. Construído sobre o Morro de São Bento, reúne a vida monástica, atividades educacionais e um importante patrimônio artístico. Sua igreja abacial, dedicada a Nossa Senhora de Montserrate, é considerada uma das grandes obras do barroco luso-brasileiro, com interior revestido por talha dourada, esculturas e pinturas religiosas. Ao longo de mais de quatro séculos, o mosteiro tornou-se uma referência da história colonial, religiosa e cultural da cidade.", importancia: null, endereco: "Rua Dom Gerardo, 68 — Centro", imagem: {"src": "assets/img/mosteiro-de-sao-bento.jpg", "alt": "Mosteiro de São Bento", "fonte": "partiu__lugaresss.docx"} },
    { id: "igreja-de-nossa-senhora-da-candelaria", nome: "Igreja de Nossa Senhora da Candelária", bairro: "centro", lat: -22.900588, lng: -43.177544, categoria: "Religião", descricao: "A Igreja de Nossa Senhora da Candelária é um dos monumentos religiosos mais conhecidos do Centro do Rio de Janeiro. Sua origem remonta ao início do século XVII, quando foi construída uma pequena capela dedicada à Nossa Senhora da Candelária, posteriormente substituída pelo templo atual. As obras da igreja tiveram início em 1775 e foram concluídas apenas no final do século XIX, resultando em uma construção que combina diferentes referências arquitetônicas. Sua fachada monumental, a cúpula e a decoração interna destacam a importância artística do edifício, que também testemunhou acontecimentos importantes da história política e social brasileira.", importancia: null, endereco: "Praça Pio X — Centro", imagem: {"src": "assets/img/igreja-de-nossa-senhora-da-candelaria.jpg", "alt": "Igreja de Nossa Senhora da Candelária", "fonte": "partiu__lugaresss.docx"} },
    { id: "igreja-da-ordem-terceira-de-sao-francisco-da-penitencia", nome: "Igreja da Ordem Terceira de São Francisco da Penitência", bairro: "centro", lat: -22.906629, lng: -43.179072, categoria: "Religião", descricao: "Localizada no alto do Morro de Santo Antônio, a Igreja da Ordem Terceira de São Francisco da Penitência é considerada uma das maiores expressões da arte barroca no Rio de Janeiro. A irmandade responsável por sua construção foi fundada em 1619, e as obras do templo começaram em 1657, sendo concluídas ao longo do século XVIII. Seu interior impressiona pela abundância de talha dourada, esculturas e pinturas religiosas, especialmente a pintura do teto da nave, atribuída a Caetano da Costa Coelho, considerada um marco da pintura em perspectiva no Brasil. O contraste entre a fachada simples e a riqueza ornamental interna faz da igreja um importante patrimônio artístico e religioso.", importancia: null, endereco: "Largo da Carioca — Centro", imagem: {"src": "assets/img/igreja-da-ordem-terceira-de-sao-francisco-da-penitencia.jpg", "alt": "Igreja da Ordem Terceira de São Francisco da Penitência", "fonte": "partiu__lugaresss.docx"} },
    { id: "convento-e-igreja-de-santo-antonio", nome: "Convento e Igreja de Santo Antônio", bairro: "centro", lat: -22.906872, lng: -43.179105, categoria: "Religião", descricao: "O Convento e a Igreja de Santo Antônio formam um dos conjuntos religiosos mais antigos do Rio de Janeiro. A presença franciscana na cidade começou em 1592, e a construção do convento e da igreja no Morro de Santo Antônio teve início em 1608. A primeira missa foi celebrada em 1615, enquanto as obras da igreja foram concluídas por volta de 1620. O conjunto passou por transformações ao longo dos séculos e conserva importantes elementos da arquitetura colonial e da arte sacra brasileira. Além de sua importância religiosa, o convento teve papel relevante na educação e na vida cultural da cidade, mantendo uma presença histórica no Centro do Rio.", importancia: null, endereco: "Largo da Carioca — Centro", imagem: {"src": "assets/img/convento-e-igreja-de-santo-antonio.jpg", "alt": "Convento e Igreja de Santo Antônio", "fonte": "partiu__lugaresss.docx"} },
    { id: "igreja-de-nossa-senhora-do-carmo-da-antiga-se", nome: "Igreja de Nossa Senhora do Carmo da Antiga Sé", bairro: "centro", lat: -22.903204, lng: -43.175427, categoria: "Religião", descricao: "A Igreja de Nossa Senhora do Carmo da Antiga Sé foi a antiga catedral do Rio de Janeiro e um dos principais templos da cidade durante o período colonial e imperial. Sua história está ligada à presença dos carmelitas, que chegaram ao Rio no século XVI e estabeleceram seu convento próximo ao antigo Paço Real. Em 1808, com a chegada da família real portuguesa, a igreja passou a funcionar como Capela Real e, posteriormente, Capela Imperial, recebendo importantes cerimônias da monarquia brasileira. Foi nela que ocorreram acontecimentos como a coroação de Dom Pedro I e Dom Pedro II. O templo conserva um importante conjunto artístico e arquitetônico e representa uma referência fundamental da história política e religiosa do Brasil.", importancia: null, endereco: "Rua Sete de Setembro, 14 — Centro", imagem: {"src": "assets/img/igreja-de-nossa-senhora-do-carmo-da-antiga-se.jpg", "alt": "Igreja de Nossa Senhora do Carmo da Antiga Sé", "fonte": "partiu__lugaresss.docx"} },
    { id: "igreja-de-nossa-senhora-de-bonsucesso", nome: "Igreja de Nossa Senhora de Bonsucesso", bairro: "centro", lat: -22.906157, lng: -43.170255, categoria: "Religião", descricao: "A Igreja de Nossa Senhora de Bonsucesso tem sua origem ligada à antiga Capela da Misericórdia, construída no século XVI e relacionada à atuação da Santa Casa de Misericórdia do Rio de Janeiro. Localizada no Largo da Misericórdia, próxima ao antigo Morro do Castelo, a igreja preserva elementos importantes da história religiosa e assistencial da cidade. Seu interior abriga peças artísticas provenientes da antiga Igreja de Santo Inácio, dos jesuítas, demolida durante o desmonte do Morro do Castelo em 1922. Entre esses elementos estão retábulos de estilo maneirista, considerados raros exemplares dessa tradição artística no Brasil. O templo representa uma ligação entre a história colonial, a assistência social e a preservação do patrimônio religioso carioca.", importancia: null, endereco: "Largo da Misericórdia — Centro", imagem: {"src": "assets/img/igreja-de-nossa-senhora-de-bonsucesso.jpg", "alt": "Igreja de Nossa Senhora de Bonsucesso", "fonte": "partiu__lugaresss.docx"} },
    { id: "catedral-metropolitana-de-sao-sebastiao", nome: "Catedral Metropolitana de São Sebastião", bairro: "centro", lat: -22.910484, lng: -43.180715, categoria: "Religião", descricao: "A Catedral Metropolitana de São Sebastião é a principal igreja da Arquidiocese do Rio de Janeiro e um dos edifícios religiosos mais marcantes da arquitetura moderna brasileira. Inaugurada em 1979, foi projetada pelo arquiteto Edgar de Oliveira da Fonseca e apresenta formato cônico inspirado nas antigas pirâmides maias, com aproximadamente 75 metros de altura. Seu interior possui quatro grandes vitrais coloridos que se estendem do chão até a cúpula, criando um ambiente de iluminação natural e simbolismo religioso. A construção marcou a criação de uma sede definitiva para a Arquidiocese, que durante séculos utilizou diferentes igrejas da cidade como catedral. O templo é dedicado a São Sebastião, padroeiro do Rio de Janeiro.", importancia: null, endereco: "Avenida República do Chile, 245 — Centro", imagem: {"src": "assets/img/catedral-metropolitana-de-sao-sebastiao.jpg", "alt": "Catedral Metropolitana de São Sebastião", "fonte": "partiu__lugaresss.docx"} },
    { id: "igreja-de-sao-francisco-de-paula", nome: "Igreja de São Francisco de Paula", bairro: "centro", lat: -22.905096, lng: -43.180668, categoria: "Religião", descricao: "A Igreja de São Francisco de Paula está localizada em um dos largos históricos mais importantes do Centro do Rio de Janeiro. Sua construção foi iniciada em 1759 por iniciativa da Ordem Terceira dos Mínimos de São Francisco de Paula, mas o templo só foi concluído e inaugurado no século XIX. Com dimensões monumentais e características da arquitetura religiosa colonial, a igreja possui uma fachada imponente e um interior ricamente decorado, com pinturas, esculturas e elementos de talha. Ao longo de sua história, esteve ligada à vida religiosa e social da cidade, acompanhando as transformações do entorno e preservando a memória de um dos espaços tradicionais do Centro.", importancia: null, endereco: "Largo de São Francisco de Paula — Centro", imagem: {"src": "assets/img/igreja-de-sao-francisco-de-paula.jpg", "alt": "Igreja de São Francisco de Paula", "fonte": "partiu__lugaresss.docx"} },
    { id: "igreja-de-sao-jose", nome: "Igreja de São José", bairro: "centro", lat: -22.904407, lng: -43.174138, categoria: "Religião", descricao: "A Igreja de São José é um dos templos históricos do Centro do Rio de Janeiro e está localizada próxima à antiga região do Paço Imperial. Sua origem remonta ao período colonial, quando uma pequena ermida dedicada ao santo deu lugar a uma igreja maior, construída entre o final do século XVIII e o início do século XIX. O templo atual apresenta características da arquitetura religiosa tradicional, com fachada monumental e decoração interna marcada por elementos ornamentais e artísticos. Sua localização, próxima a importantes edifícios políticos e administrativos, também revela a relação entre a Igreja Católica e a organização da sociedade carioca durante o período colonial e imperial.", importancia: null, endereco: "Avenida Presidente Antônio Carlos — Centro", imagem: {"src": "assets/img/igreja-de-sao-jose.jpg", "alt": "Igreja de São José", "fonte": "partiu__lugaresss.docx"} },
    { id: "igreja-de-nossa-senhora-da-lapa-dos-mercadores", nome: "Igreja de Nossa Senhora da Lapa dos Mercadores", bairro: "centro", lat: -22.901928, lng: -43.175288, categoria: "Religião", descricao: "A Igreja de Nossa Senhora da Lapa dos Mercadores é um dos templos históricos mais conhecidos da Rua do Ouvidor. Sua construção teve início em 1743, por iniciativa de uma irmandade formada por comerciantes da região, e foi inaugurada em 1750. O edifício apresenta características barrocas e rococós, com decoração interna elaborada e elementos artísticos que refletem a importância econômica e religiosa do comércio no Centro do Rio durante o período colonial. A igreja também guarda lembranças de acontecimentos históricos, como a Revolta da Armada, em 1893, quando foi atingida por um disparo de canhão. O episódio está relacionado a objetos preservados em seu interior, que ajudam a contar a história do templo e da cidade.", importancia: null, endereco: "Rua do Ouvidor, 35 — Centro", imagem: {"src": "assets/img/igreja-de-nossa-senhora-da-lapa-dos-mercadores.jpg", "alt": "Igreja de Nossa Senhora da Lapa dos Mercadores", "fonte": "partiu__lugaresss.docx"} },
    { id: "igreja-de-santa-rita", nome: "Igreja de Santa Rita", bairro: "centro", lat: -22.900178, lng: -43.18064, categoria: "Religião", descricao: "A Igreja de Santa Rita é um dos templos mais antigos do Centro do Rio de Janeiro, com origem ligada a uma capela cuja construção começou em 1720 e cuja parte principal ficou pronta em 1721. O espaço foi dedicado a Santa Rita de Cássia e passou a ser administrado por uma irmandade criada naquele mesmo período. Sua história também revela aspectos importantes da sociedade escravista: o entorno da igreja e seu antigo adro foram utilizados como local de sepultamento de africanos escravizados recém-chegados ao Brasil, conhecidos como “pretos novos”. Atualmente, o templo representa um importante patrimônio religioso e histórico, permitindo compreender tanto a devoção católica quanto aspectos difíceis da história da escravidão no Rio de Janeiro.", importancia: null, endereco: "Largo de Santa Rita — Centro", imagem: {"src": "assets/img/igreja-de-santa-rita.jpg", "alt": "Igreja de Santa Rita", "fonte": "partiu__lugaresss.docx"} },
    { id: "igreja-de-nossa-senhora-da-conceicao-e-boa-morte", nome: "Igreja de Nossa Senhora da Conceição e Boa Morte", bairro: "centro", lat: -22.902985, lng: -43.178594, categoria: "Religião", descricao: "A Igreja de Nossa Senhora da Conceição e Boa Morte é um importante templo colonial localizado na Rua do Rosário, no Centro do Rio de Janeiro. Sua história está relacionada à união de irmandades religiosas dedicadas a Nossa Senhora da Conceição e à Boa Morte, que organizaram suas atividades na região a partir do início do século XVIII. O edifício atual foi construído no século XVIII e apresenta elementos arquitetônicos e artísticos do período, incluindo um portal atribuído ao escultor e entalhador Mestre Valentim. Mesmo diante das grandes transformações urbanas provocadas pela abertura da Avenida Central, atual Avenida Rio Branco, a igreja foi preservada e permanece como parte importante do patrimônio religioso e arquitetônico carioca.", importancia: null, endereco: "Rua do Rosário — Centro", imagem: {"src": "assets/img/igreja-de-nossa-senhora-da-conceicao-e-boa-morte.jpg", "alt": "Igreja de Nossa Senhora da Conceição e Boa Morte", "fonte": "partiu__lugaresss.docx"} },
    { id: "igreja-de-nossa-senhora-do-rosario-e-sao-benedito-dos-homens-pretos", nome: "Igreja de Nossa Senhora do Rosário e São Benedito dos Homens Pretos", bairro: "centro", lat: -22.903678, lng: -43.180358, categoria: "Religião", descricao: "A Igreja de Nossa Senhora do Rosário e São Benedito dos Homens Pretos é um dos espaços mais importantes para a preservação da memória da população negra no Rio de Janeiro. Sua história está ligada à irmandade fundada por homens negros no século XVII, que buscavam um espaço próprio para manifestar sua fé e organizar atividades de assistência e solidariedade. A construção do templo na atual Rua Uruguaiana começou em 1700 e foi concluída ao longo das décadas seguintes. Entre 1737 e 1808, a igreja chegou a funcionar como sede da Catedral do Rio de Janeiro. O local também está relacionado à atuação de pessoas negras na vida religiosa, cultural e política da cidade, sendo um símbolo de resistência, organização comunitária e preservação da memória afro-brasileira.\n\nA Igreja de Nossa Senhora do Rosário e São Benedito é um dos espaços mais importantes para a preservação da memória da população negra no Rio de Janeiro. Sua história está ligada à Irmandade de Nossa Senhora do Rosário e São Benedito dos Homens Pretos, formada por pessoas negras que encontraram na organização religiosa uma maneira de exercer sua fé, construir redes de solidariedade e conquistar espaço na sociedade colonial. Construída no início do século XVIII, a igreja chegou a funcionar como Catedral do Rio de Janeiro entre 1737 e 1808. O local também teve importância política: em 1821, recebeu reuniões relacionadas ao movimento que defendia a permanência de Dom Pedro no Brasil. Atualmente, representa um importante patrimônio histórico e cultural, ligado à resistência, à religiosidade e à participação da população negra na formação da cidade.", importancia: null, endereco: "Rua Uruguaiana, 77 — Centro", imagem: {"src": "assets/img/igreja-de-nossa-senhora-do-rosario-e-sao-benedito-dos-homens-pretos.jpg", "alt": "Igreja de Nossa Senhora do Rosário e São Benedito dos Homens Pretos", "fonte": "partiu__lugaresss.docx"} },
    { id: "igreja-de-nossa-senhora-do-carmo-da-lapa-do-desterro", nome: "Igreja de Nossa Senhora do Carmo da Lapa do Desterro", bairro: "centro", lat: -22.914473, lng: -43.177957, categoria: "Religião", descricao: "A Igreja de Nossa Senhora do Carmo da Lapa do Desterro está ligada à história religiosa e urbana da região da Lapa. Sua construção começou em 1751, em um terreno doado para a instalação de um seminário e de um templo dedicado a Nossa Senhora do Desterro, e foi concluída em 1780. O projeto é atribuído ao engenheiro militar José Fernandes Pinto Alpoim, figura importante da arquitetura colonial no Rio de Janeiro. No início do século XIX, com a chegada da família real portuguesa e as mudanças na organização das instituições religiosas da cidade, o edifício passou a ser utilizado pelos carmelitas. A igreja foi tombada pelo IPHAN em 1938 e permanece como um importante exemplar da arquitetura religiosa colonial.", importancia: null, endereco: "Rua Riachuelo — Centro", imagem: {"src": "assets/img/igreja-de-nossa-senhora-do-carmo-da-lapa-do-desterro.jpg", "alt": "Igreja de Nossa Senhora do Carmo da Lapa do Desterro", "fonte": "partiu__lugaresss.docx"} },
    { id: "grande-templo-israelita-do-rio-de-janeiro", nome: "Grande Templo Israelita do Rio de Janeiro", bairro: "centro", lat: -22.91211, lng: -43.190296, categoria: "Religião", descricao: "O Grande Templo Israelita do Rio de Janeiro, também conhecido como Sinagoga da Rua Tenente Possolo, é um importante marco da história da comunidade judaica na cidade. Sua construção está relacionada ao crescimento da população judaica no Rio de Janeiro entre o final do século XIX e as primeiras décadas do século XX, quando muitos imigrantes se estabeleceram na região da Praça Onze e em bairros próximos. O templo foi idealizado como um espaço de culto, estudo e convivência capaz de reunir diferentes grupos da comunidade judaica. Além de sua função religiosa, representa a contribuição dos imigrantes judeus para a formação cultural e social da cidade, preservando a memória de uma importante etapa da história da imigração no Rio.", importancia: null, endereco: "Rua Tenente Possolo, 8 — Centro", imagem: {"src": "assets/img/grande-templo-israelita-do-rio-de-janeiro.jpg", "alt": "Grande Templo Israelita do Rio de Janeiro", "fonte": "partiu__lugaresss.docx"} },
    { id: "catedral-presbiteriana-do-rio-de-janeiro", nome: "Catedral Presbiteriana do Rio de Janeiro", bairro: "centro", lat: -22.907571, lng: -43.181504, categoria: "Religião", descricao: "A Catedral Presbiteriana do Rio de Janeiro é um dos principais marcos da história do protestantismo no Brasil. Sua origem está ligada à fundação da Primeira Igreja Presbiteriana do Brasil, organizada em 12 de janeiro de 1862 pelo missionário norte-americano Ashbel Green Simonton. Após funcionar em diferentes endereços, a comunidade estabeleceu sua sede definitiva na atual Rua Silva Jardim, 23, em 1870. O edifício apresenta características da arquitetura religiosa neogótica, com elementos que se destacam na paisagem do Centro. Sua trajetória representa a expansão das igrejas protestantes no país e a consolidação da presença presbiteriana na sociedade brasileira.\n\nA Igreja Presbiteriana do Rio de Janeiro, também conhecida como Catedral Presbiteriana, é um marco da história do protestantismo brasileiro. Organizada em 12 de janeiro de 1862 pelo missionário Ashbel Green Simonton, é considerada a primeira igreja presbiteriana do Brasil. Seu templo atual, localizado no Centro, apresenta arquitetura neogótica e elementos decorativos como vitrais e iluminação artística. Ao longo de sua trajetória, teve papel importante na expansão do presbiterianismo e na formação de comunidades religiosas no país.", importancia: null, endereco: "Rua Silva Jardim, 23 — Centro", imagem: {"src": "assets/img/catedral-presbiteriana-do-rio-de-janeiro.jpg", "alt": "Catedral Presbiteriana do Rio de Janeiro", "fonte": "partiu__lugaresss.docx"} },
    { id: "colegio-de-sao-bento", nome: "Colégio de São Bento", bairro: "centro", lat: -22.897227, lng: -43.179818, categoria: "Educação", descricao: "Fundado em 1858 por Dom Frei Luís da Conceição Saraiva, o Colégio de São Bento é uma das instituições de ensino mais tradicionais do Rio de Janeiro. Inicialmente chamado de Externato de São Bento, foi criado pelos monges beneditinos com o objetivo de oferecer formação educacional baseada nos valores cristãos e na tradição humanista. Ao longo de sua história, recebeu estudantes que se destacaram em diferentes áreas da sociedade brasileira, como o escritor Coelho Neto e o jurista Clóvis Beviláqua. Localizado no mesmo conjunto arquitetônico do Mosteiro de São Bento, mantém uma ligação histórica entre educação, cultura e tradição religiosa.", importancia: null, endereco: "Rua Dom Gerardo, 68 — Centro", imagem: {"src": "assets/img/colegio-de-sao-bento.jpg", "alt": "Colégio de São Bento", "fonte": "partiu__lugaresss.docx"} },
    { id: "colegio-cruzeiro-centro", nome: "Colégio Cruzeiro — Centro", bairro: "centro", lat: -22.911244, lng: -43.189601, categoria: "Educação", descricao: "O Colégio Cruzeiro tem suas origens na comunidade alemã estabelecida no Rio de Janeiro durante o século XIX. Foi fundado em 1862 pela Sociedade Beneficente Alemã, inicialmente com o nome de Deutsche Schule, para atender às necessidades educacionais dos filhos dos imigrantes. Ao longo de sua trajetória, a instituição ampliou sua atuação e passou a receber estudantes de diferentes origens, preservando elementos de sua tradição cultural alemã. Com mais de um século e meio de história, tornou-se uma referência na educação carioca e representa a contribuição das comunidades imigrantes para a formação cultural da cidade.", importancia: null, endereco: "Rua Carlos de Carvalho, 76 — Centro", imagem: {"src": "assets/img/colegio-cruzeiro-centro.jpg", "alt": "Colégio Cruzeiro — Centro", "fonte": "partiu__lugaresss.docx"} },
    { id: "faculdade-nacional-de-direito-ufrj", nome: "Faculdade Nacional de Direito — UFRJ", bairro: "centro", lat: -22.907114, lng: -43.190623, categoria: "Educação", descricao: "A Faculdade Nacional de Direito da Universidade Federal do Rio de Janeiro é uma das instituições mais tradicionais do ensino jurídico brasileiro. Sua formação ocorreu em 1920, a partir da união de duas faculdades livres de Direito que já funcionavam na cidade. O edifício histórico que abriga a instituição também possui grande importância política: foi residência do Conde dos Arcos, sede do Senado Imperial e, posteriormente, do Senado Republicano. Em 1938, passou a receber a Faculdade Nacional de Direito, tornando-se um espaço associado à formação de juristas e ao desenvolvimento das instituições políticas e jurídicas do Brasil.", importancia: null, endereco: "Rua Moncorvo Filho, 8 — Centro", imagem: {"src": "assets/img/faculdade-nacional-de-direito-ufrj.jpg", "alt": "Faculdade Nacional de Direito — UFRJ", "fonte": "partiu__lugaresss.docx"} },
    { id: "escola-de-musica-da-ufrj", nome: "Escola de Música da UFRJ", bairro: "lapa", lat: -22.913151, lng: -43.178296, categoria: "Educação", descricao: "A Escola de Música da Universidade Federal do Rio de Janeiro é a mais antiga instituição de ensino musical em atividade no Brasil. Sua origem está no Conservatório de Música, inaugurado em 1848, com o objetivo de formar músicos para orquestras, corais e outras atividades artísticas. A instituição teve como primeiro diretor Francisco Manuel da Silva, compositor do Hino Nacional Brasileiro, e participou da formação de importantes músicos, professores, pesquisadores e intérpretes do país. Atualmente, desenvolve atividades de ensino, pesquisa e extensão, contribuindo para a preservação e a renovação da música brasileira.", importancia: null, endereco: "Rua do Passeio, 98 — Lapa", imagem: {"src": "assets/img/escola-de-musica-da-ufrj.jpg", "alt": "Escola de Música da UFRJ", "fonte": "partiu__lugaresss.docx"} },
    { id: "instituto-de-filosofia-e-ciencias-sociais-ufrj", nome: "Instituto de Filosofia e Ciências Sociais — UFRJ", bairro: "centro", lat: -22.90508, lng: -43.181242, categoria: "Educação", descricao: "O Instituto de Filosofia e Ciências Sociais da UFRJ está instalado em um edifício histórico no Largo de São Francisco de Paula, cuja trajetória remonta ao século XVIII. Construído inicialmente para funcionar como Sé do Rio de Janeiro, o prédio abrigou posteriormente instituições importantes para a formação científica do país, como a Academia Militar e a Escola Politécnica. O IFCS reúne cursos e pesquisas nas áreas de Filosofia, Ciências Sociais e outras disciplinas das humanidades, sendo um importante espaço de produção intelectual e debate sobre a sociedade brasileira. Sua presença no Centro aproxima a história do ensino superior da vida acadêmica contemporânea.", importancia: null, endereco: "Largo de São Francisco de Paula, 1 — Centro", imagem: {"src": "assets/img/instituto-de-filosofia-e-ciencias-sociais-ufrj.jpg", "alt": "Instituto de Filosofia e Ciências Sociais — UFRJ", "fonte": "partiu__lugaresss.docx"} },
    { id: "instituto-de-historia-ufrj", nome: "Instituto de História — UFRJ", bairro: "centro", lat: -22.905347, lng: -43.181644, categoria: "Educação", descricao: "O Instituto de História da Universidade Federal do Rio de Janeiro é uma unidade acadêmica dedicada ao ensino, à pesquisa e à divulgação do conhecimento histórico. Criado em dezembro de 2010, surgiu a partir da transformação do antigo Departamento de História do Instituto de Filosofia e Ciências Sociais em uma unidade universitária independente. Instalado no histórico edifício do Largo de São Francisco de Paula, participa da formação de historiadores e do desenvolvimento de pesquisas sobre diferentes períodos e sociedades. Sua localização também estabelece uma ligação entre a produção acadêmica atual e a longa trajetória do prédio como espaço de ensino superior no Brasil.", importancia: null, endereco: "Largo de São Francisco de Paula, 1 — Centro", imagem: {"src": "assets/img/instituto-de-historia-ufrj.jpg", "alt": "Instituto de História — UFRJ", "fonte": "partiu__lugaresss.docx"} },
    { id: "paco-imperial", nome: "Paço Imperial", bairro: "centro", lat: -22.903349, lng: -43.174264, categoria: "História/Patrimônio", descricao: "Construído entre 1738 e 1743, o Paço Imperial é um dos edifícios mais importantes da história política brasileira. Inicialmente utilizado como residência e sede administrativa dos governadores e vice-reis, tornou-se Paço Real com a chegada da família portuguesa ao Rio de Janeiro, em 1808, e posteriormente Paço Imperial, durante os reinados de Dom Pedro I e Dom Pedro II. O local foi cenário de acontecimentos fundamentais, como o Dia do Fico, em 1822, e decisões relacionadas à Independência e à Abolição da Escravidão. Tombado pelo IPHAN em 1938, atualmente funciona como centro cultural, recebendo exposições e atividades artísticas.", importancia: null, endereco: "Praça XV de Novembro, 48 — Centro", imagem: {"src": "assets/img/paco-imperial.jpg", "alt": "Paço Imperial", "fonte": "partiu__lugaresss.docx"} },
    { id: "arco-do-teles", nome: "Arco do Teles", bairro: "centro", lat: -22.90262, lng: -43.174729, categoria: "História/Patrimônio", descricao: "O Arco do Teles é um dos conjuntos arquitetônicos mais característicos da Praça XV e preserva parte da paisagem urbana do Rio de Janeiro colonial. Sua origem está relacionada à construção de um conjunto de casas encomendado pelo juiz Antônio Telles Barreto de Menezes, no século XVIII. Projetado pelo engenheiro militar José Fernandes Pinto Alpoim, o conjunto foi construído sobre um arco que permitia a passagem entre a Praça XV e o antigo Beco do Comércio. Com suas construções históricas, ruas estreitas e estabelecimentos comerciais, o local representa um importante registro da ocupação e da vida cotidiana do antigo Centro da cidade.", importancia: null, endereco: "Praça XV de Novembro, 34 — Centro", imagem: {"src": "assets/img/arco-do-teles.jpg", "alt": "Arco do Teles", "fonte": "partiu__lugaresss.docx"} },
    { id: "campo-de-santana", nome: "Campo de Santana", bairro: "centro", lat: -22.906494, lng: -43.18852, categoria: "História/Patrimônio", descricao: "O Campo de Santana, também conhecido como Praça da República, é um dos espaços públicos mais importantes da história do Rio de Janeiro. Durante o período colonial, a área era um grande terreno alagadiço que passou por sucessivos aterros e transformações urbanas. O local foi palco de acontecimentos fundamentais da história brasileira, incluindo a aclamação de Dom Pedro I como imperador, em 1822, e a Proclamação da República, em 1889. Em 1873, recebeu um projeto paisagístico do francês Auguste Glaziou, que introduziu lagos, pontes, grutas e jardins inspirados nos parques europeus. Atualmente, é uma importante área verde no coração do Centro.", importancia: null, endereco: "Praça da República — Centro", imagem: {"src": "assets/img/campo-de-santana.jpg", "alt": "Campo de Santana", "fonte": "partiu__lugaresss.docx"} },
    { id: "arcos-da-lapa", nome: "Arcos da Lapa", bairro: "lapa", lat: -22.912333, lng: -43.179855, categoria: "História/Patrimônio", descricao: "Os Arcos da Lapa, oficialmente conhecidos como Aqueduto da Carioca, são um dos monumentos mais emblemáticos do Rio de Janeiro. Construídos para transportar as águas do Rio Carioca até o Centro da cidade, representam uma das principais obras de engenharia do período colonial. A estrutura atual, feita de pedra e cal, teve suas obras concluídas em 1750 e substituiu um sistema anterior de abastecimento. No século XIX, com a expansão dos transportes urbanos, os antigos aquedutos passaram a servir de viaduto para os bondes que seguiam em direção a Santa Teresa. Atualmente, os arcos são um símbolo da Lapa e da paisagem histórica carioca.", importancia: null, endereco: "Praça Cardeal Câmara — Lapa", imagem: {"src": "assets/img/arcos-da-lapa.jpg", "alt": "Arcos da Lapa", "fonte": "partiu__lugaresss.docx"} },
    { id: "passeio-publico", nome: "Passeio Público", bairro: "centro", lat: -22.913168, lng: -43.176397, categoria: "História/Patrimônio", descricao: "Inaugurado em 1783, o Passeio Público é considerado o primeiro parque ajardinado do Brasil e um dos espaços de lazer mais antigos do Rio de Janeiro. Seu projeto original foi desenvolvido por Mestre Valentim, durante o governo do vice-rei Luís de Vasconcelos, em uma área aterrada próxima à antiga Lagoa do Boqueirão. O jardim foi concebido para oferecer à população um espaço de passeio e contemplação, reunindo caminhos, fontes, esculturas e elementos ornamentais. Em 1864, passou por uma grande reforma conduzida pelo paisagista francês Auguste Glaziou, que modificou seu traçado e incorporou características dos jardins ingleses. O parque preserva importantes elementos da história urbana e paisagística da cidade.", importancia: null, endereco: "Rua do Passeio, s/n — Centro", imagem: {"src": "assets/img/passeio-publico.jpg", "alt": "Passeio Público", "fonte": "partiu__lugaresss.docx"} },
    { id: "chafariz-do-mestre-valentim", nome: "Chafariz do Mestre Valentim", bairro: "centro", lat: -22.902532, lng: -43.173947, categoria: "História/Patrimônio", descricao: "O Chafariz do Mestre Valentim, localizado na Praça XV, foi inaugurado em 1789 e projetado pelo escultor e urbanista Valentim da Fonseca e Silva, conhecido como Mestre Valentim. Construído originalmente próximo ao antigo cais, tinha a função de abastecer a população e fornecer água às embarcações que chegavam ao porto do Rio de Janeiro. Sua estrutura de pedra apresenta elementos ornamentais característicos da arquitetura colonial, com uma composição que combina cantaria, pilastras e uma cobertura em formato de pirâmide. Com as transformações da orla e o avanço dos aterros, o chafariz perdeu sua função original, mas permaneceu como um importante monumento da história do abastecimento de água e da arte colonial brasileira.", importancia: null, endereco: "Praça XV de Novembro — Centro", imagem: {"src": "assets/img/chafariz-do-mestre-valentim.jpg", "alt": "Chafariz do Mestre Valentim", "fonte": "partiu__lugaresss.docx"} },
    { id: "real-gabinete-portugues-de-leitura", nome: "Real Gabinete Português de Leitura", bairro: "centro", lat: -22.905123, lng: -43.182176, categoria: "História/Patrimônio", descricao: "Fundado em 1837 por imigrantes portugueses, o Real Gabinete Português de Leitura foi criado com o objetivo de promover a instrução e preservar a literatura e a cultura de Portugal no Brasil. Sua atual sede, inaugurada em 1887, é um dos mais importantes exemplos da arquitetura neomanuelina fora de Portugal, com uma fachada ricamente ornamentada e referências ao período das grandes navegações portuguesas. O interior abriga um salão monumental, com estantes que se estendem até o teto e um amplo acervo bibliográfico, incluindo obras raras e edições históricas. Reconhecido internacionalmente por sua arquitetura e coleção, o espaço representa os vínculos culturais entre Brasil e Portugal.", importancia: null, endereco: "Rua Luís de Camões, 30 — Centro", imagem: {"src": "assets/img/real-gabinete-portugues-de-leitura.jpg", "alt": "Real Gabinete Português de Leitura", "fonte": "partiu__lugaresss.docx"} },
    { id: "theatro-municipal-do-rio-de-janeiro", nome: "Theatro Municipal do Rio de Janeiro", bairro: "centro", lat: -22.908771, lng: -43.176515, categoria: "História/Patrimônio", descricao: "Inaugurado em 14 de julho de 1909, o Theatro Municipal do Rio de Janeiro é uma das principais instituições culturais do país e um dos edifícios mais conhecidos da Cinelândia. Sua construção fez parte das reformas urbanas realizadas durante a administração do prefeito Pereira Passos, que buscavam modernizar o Centro e aproximar a cidade das grandes capitais europeias. Inspirado em importantes teatros europeus, o edifício apresenta uma arquitetura monumental, com esculturas, colunas, vitrais e uma decoração interna elaborada. Ao longo de sua história, recebeu grandes nomes da música, da dança e da ópera, além de manter seus próprios corpos artísticos, contribuindo para a vida cultural brasileira.", importancia: null, endereco: "Praça Floriano, s/n — Centro", imagem: {"src": "assets/img/theatro-municipal-do-rio-de-janeiro.jpg", "alt": "Theatro Municipal do Rio de Janeiro", "fonte": "partiu__lugaresss.docx"} },
    { id: "biblioteca-nacional", nome: "Biblioteca Nacional", bairro: "centro", lat: -22.9094, lng: -43.175453, categoria: "História/Patrimônio", descricao: "A Biblioteca Nacional é uma das instituições culturais mais importantes do Brasil e possui suas origens na transferência da Real Biblioteca portuguesa para o Rio de Janeiro, após a chegada da família real em 1808. Oficialmente estabelecida em 1810, a instituição reúne um dos maiores acervos bibliográficos da América Latina, com livros, manuscritos, mapas, fotografias, periódicos e documentos fundamentais para a história do país. Sua sede atual, localizada na Avenida Rio Branco, foi inaugurada em 1910, durante as reformas urbanas do início do século XX. O edifício apresenta arquitetura monumental e foi projetado para abrigar e preservar um patrimônio documental de valor nacional e internacional.", importancia: null, endereco: "Avenida Rio Branco, 219 — Centro", imagem: {"src": "assets/img/biblioteca-nacional.jpg", "alt": "Biblioteca Nacional", "fonte": "partiu__lugaresss.docx"} },
    { id: "museu-historico-nacional", nome: "Museu Histórico Nacional", bairro: "centro", lat: -22.905407, lng: -43.169552, categoria: "História/Patrimônio", descricao: "Criado em 1922, durante as comemorações do centenário da Independência do Brasil, o Museu Histórico Nacional é uma das principais instituições dedicadas à preservação da memória brasileira. Instalado em um conjunto arquitetônico de origem colonial, próximo à Praça XV, ocupa construções que abrigaram antigas estruturas militares, como a Casa do Trem e o Arsenal de Guerra. Seu acervo reúne objetos, documentos, pinturas, mobiliário, moedas e outros registros que ajudam a compreender diferentes períodos da história do país. Ao longo de sua trajetória, o museu tornou-se um importante espaço de pesquisa, educação e valorização do patrimônio histórico nacional.", importancia: null, endereco: "Praça Marechal Âncora, s/n — Centro", imagem: {"src": "assets/img/museu-historico-nacional.jpg", "alt": "Museu Histórico Nacional", "fonte": "partiu__lugaresss.docx"} },
    { id: "antigo-dops-edificio-da-reparticao-central-de-policia", nome: "Antigo DOPS — Edifício da Repartição Central de Polícia", bairro: "centro", lat: -22.910422, lng: -43.18509, categoria: "História/Patrimônio", descricao: "O edifício da antiga Repartição Central de Polícia, localizado na Rua da Relação, foi inaugurado em 1910 e projetado pelo arquiteto Heitor de Mello. Construído para abrigar instituições policiais, tornou-se posteriormente sede do Departamento de Ordem Política e Social, o DOPS, órgão associado à vigilância, à perseguição e à repressão política durante diferentes períodos da história brasileira, especialmente durante a ditadura militar. O prédio foi cenário de prisões e violações de direitos humanos, tornando-se um importante lugar de memória das vítimas da violência de Estado. Sua preservação possui significado histórico e social, contribuindo para a reflexão sobre autoritarismo, democracia e direitos humanos.", importancia: null, endereco: "Centro", imagem: {"src": "assets/img/antigo-dops-edificio-da-reparticao-central-de-policia.jpg", "alt": "Antigo DOPS — Edifício da Repartição Central de Polícia", "fonte": "partiu__lugaresss.docx"} },
    { id: "estacao-central-do-brasil", nome: "Estação Central do Brasil", bairro: "centro", lat: -22.903203, lng: -43.191598, categoria: "História/Patrimônio", descricao: "A Estação Central do Brasil é um dos principais marcos da história ferroviária e urbana do Rio de Janeiro. Sua origem está ligada à inauguração da Estrada de Ferro Dom Pedro II, em 1858, que conectava a então Corte a outras regiões da província e contribuiu para a expansão dos transportes no país. Ao longo do tempo, a estação passou por ampliações e mudanças de nome, tornando-se conhecida como Central do Brasil. O edifício atual, marcado por sua torre com relógio e características da arquitetura art déco, foi inaugurado em 1943. Até hoje, é um dos principais pontos de circulação de passageiros da cidade e um símbolo da relação entre o transporte ferroviário e o crescimento urbano carioca.", importancia: null, endereco: "Praça Cristiano Ottoni — Centro", imagem: {"src": "assets/img/estacao-central-do-brasil.jpg", "alt": "Estação Central do Brasil", "fonte": "partiu__lugaresss.docx"} },
    { id: "monumento-a-nelson-rodrigues", nome: "Monumento a Nelson Rodrigues", bairro: "centro", lat: null, lng: null, categoria: "Personalidades/Memória", descricao: "Nelson Rodrigues foi dramaturgo, jornalista e escritor, reconhecido como um dos nomes mais importantes da história do teatro brasileiro. Nascido no Recife, mudou-se ainda criança para o Rio de Janeiro, onde construiu grande parte de sua trajetória profissional e cultural. Suas peças revolucionaram a dramaturgia nacional ao abordar conflitos familiares, comportamentos sociais e aspectos controversos da vida urbana, com obras como “Vestido de Noiva” e “Álbum de Família”. Sua contribuição para a cultura brasileira é lembrada por meio de homenagens e monumentos espalhados pela cidade, que reconhecem sua importância para o teatro, o jornalismo e a literatura.", importancia: null, endereco: "Avenida Rio Branco — Centro", imagem: {"src": "assets/img/monumento-a-nelson-rodrigues.jpg", "alt": "Monumento a Nelson Rodrigues", "fonte": "partiu__lugaresss.docx"} },
    { id: "igreja-de-nossa-senhora-da-gloria-do-outeiro", nome: "Igreja de Nossa Senhora da Glória do Outeiro", bairro: "gloria", lat: -22.921074, lng: -43.175243, categoria: "Religião", descricao: "A Igreja de Nossa Senhora da Glória do Outeiro é um dos mais importantes patrimônios religiosos e arquitetônicos do Rio de Janeiro. Sua origem remonta a uma pequena capela construída em 1671, e o templo atual foi concluído em 1739. Erguida no alto do Outeiro da Glória, destaca-se pela arquitetura barroca, pela planta de formato incomum e pelos painéis de azulejos portugueses que decoram seu interior. Também possui uma ligação histórica com a Família Real portuguesa e a Família Imperial brasileira, sendo tombada pelo IPHAN em 1938.", importancia: null, endereco: "Praça Nossa Senhora da Glória, 135 — Glória", imagem: {"src": "assets/img/igreja-de-nossa-senhora-da-gloria-do-outeiro.jpg", "alt": "Igreja de Nossa Senhora da Glória do Outeiro", "fonte": "partiu__lugaresss.docx"} },
    { id: "basilica-imaculada-conceicao", nome: "Basílica Imaculada Conceição", bairro: "botafogo", lat: -22.943152, lng: -43.18241, categoria: "Religião", descricao: "A Basílica Menor de Nossa Senhora da Imaculada Conceição é um dos destaques arquitetônicos de Botafogo. Inaugurada em 1892, foi projetada pelo padre francês Júlio Clavelin em estilo neogótico, inspirado nas igrejas medievais europeias. Sua fachada apresenta arcos ogivais, pináculos e uma composição que chama a atenção na paisagem da Praia de Botafogo. Além de sua importância religiosa para a comunidade católica, o edifício é reconhecido como patrimônio cultural da cidade.", importancia: null, endereco: "Praia de Botafogo, 266 — Botafogo", imagem: {"src": "assets/img/basilica-imaculada-conceicao.jpg", "alt": "Basílica Imaculada Conceição", "fonte": "partiu__lugaresss.docx"} },
    { id: "igreja-de-nossa-senhora-da-conceicao-da-gavea", nome: "Igreja de Nossa Senhora da Conceição da Gávea", bairro: "gavea", lat: -22.975319, lng: -43.227319, categoria: "Religião", descricao: "A Igreja de Nossa Senhora da Conceição da Gávea tem uma história ligada ao desenvolvimento e à ocupação do bairro. Sua construção começou em meados do século XIX, a partir de uma iniciativa organizada em 1852, e a capela foi concluída e consagrada em 1855. Em 1874, com a criação da freguesia de Nossa Senhora da Conceição da Gávea, tornou-se igreja matriz da região. O edifício original foi destruído por um incêndio em 1934 e reconstruído com a participação da comunidade local, mantendo sua importância como referência religiosa e histórica do bairro.", importancia: null, endereco: "Praça Santos Dumont — Gávea", imagem: {"src": "assets/img/igreja-de-nossa-senhora-da-conceicao-da-gavea.jpg", "alt": "Igreja de Nossa Senhora da Conceição da Gávea", "fonte": "partiu__lugaresss.docx"} },
    { id: "igreja-de-sao-judas-tadeu", nome: "Igreja de São Judas Tadeu", bairro: "cosme-velho", lat: -22.937614, lng: -43.198727, categoria: "Religião", descricao: "O Santuário de São Judas Tadeu, localizado no Cosme Velho, é um importante centro de devoção católica da Zona Sul do Rio de Janeiro. Dedicado ao apóstolo conhecido popularmente como padroeiro das causas difíceis e impossíveis, recebe fiéis especialmente no dia 28 de outubro, data dedicada ao santo. A igreja foi construída com a participação da comunidade e se tornou uma referência religiosa para moradores e devotos de diferentes regiões da cidade.", importancia: null, endereco: "Rua Cosme Velho, 470 — Cosme Velho", imagem: {"src": "assets/img/igreja-de-sao-judas-tadeu.jpg", "alt": "Igreja de São Judas Tadeu", "fonte": "partiu__lugaresss.docx"} },
    { id: "ktc-karma-theksum-chokhorling", nome: "KTC – Karma Theksum Chokhorling", bairro: "vargem-grande", lat: -22.977214, lng: -43.498606, categoria: "Religião", descricao: "A KTC – Karma Theksum Chokhorling é um centro dedicado ao estudo e à prática do budismo tibetano da linhagem Karma Kagyu. Fundada no Brasil em 1988, tornou-se a sede sul-americana de Sua Santidade o Karmapa, uma das principais lideranças dessa tradição budista. Localizada em Vargem Grande, a instituição promove ensinamentos, práticas de meditação e atividades voltadas ao conhecimento do Dharma, recebendo pessoas interessadas em conhecer e praticar o budismo tibetano.", importancia: null, endereco: "Vargem Grande", imagem: {"src": "assets/img/ktc-karma-theksum-chokhorling.jpg", "alt": "KTC – Karma Theksum Chokhorling", "fonte": "partiu__lugaresss.docx"} },
    { id: "colegio-santo-inacio", nome: "Colégio Santo Inácio", bairro: "botafogo", lat: -22.948698, lng: -43.190376, categoria: "Educação", descricao: "O Colégio Santo Inácio foi fundado em 1903 pelos padres jesuítas e faz parte da tradição educacional da Companhia de Jesus no Rio de Janeiro. Localizado em Botafogo, o colégio começou suas atividades como Externato Santo Inácio e, ao longo do século XX, ampliou suas instalações e modalidades de ensino. Sua trajetória é marcada pela proposta de formação integral, que combina ensino acadêmico com valores como solidariedade, responsabilidade social e compromisso com a comunidade.", importancia: null, endereco: "Rua São Clemente, 226 — Botafogo", imagem: {"src": "assets/img/colegio-santo-inacio.jpg", "alt": "Colégio Santo Inácio", "fonte": "partiu__lugaresss.docx"} },
    { id: "colegio-sion", nome: "Colégio Sion", bairro: "cosme-velho", lat: -22.938192, lng: -43.195975, categoria: "Educação", descricao: "O Colégio Sion chegou ao Rio de Janeiro no final do século XIX, por iniciativa das religiosas da Congregação de Nossa Senhora de Sion. Após funcionar em diferentes endereços da cidade, transferiu sua sede para o bairro do Cosme Velho em novembro de 1925, onde permanece até hoje. Inicialmente voltado à educação feminina, tornou-se uma instituição mista em 1972. Sua história está ligada à atuação educacional da congregação e à formação de gerações de estudantes na cidade.", importancia: null, endereco: "Rua Cosme Velho, 98 — Cosme Velho", imagem: {"src": "assets/img/colegio-sion.jpg", "alt": "Colégio Sion", "fonte": "partiu__lugaresss.docx"} },
    { id: "colegio-bennett", nome: "Colégio Bennett", bairro: "flamengo", lat: -22.935011, lng: -43.176594, categoria: "Educação", descricao: "O Instituto Metodista Bennett é uma instituição tradicional de ensino localizada no bairro do Flamengo. Ligado à tradição educacional metodista, integra a história das instituições confessionais que contribuíram para a educação no Rio de Janeiro. Ao longo de sua trajetória, ofereceu diferentes etapas de formação escolar, mantendo a proposta de unir conhecimento acadêmico, desenvolvimento humano e valores éticos.", importancia: null, endereco: "Rua Marquês de Abrantes, 55 — Flamengo", imagem: {"src": "assets/img/colegio-bennett.jpg", "alt": "Colégio Bennett", "fonte": "partiu__lugaresss.docx"} },
    { id: "instituto-benjamin-constant", nome: "Instituto Benjamin Constant", bairro: "urca", lat: -22.953013, lng: -43.171976, categoria: "Educação", descricao: "O Instituto Benjamin Constant é uma instituição pública federal de referência na educação de pessoas com deficiência visual. Criado em 1854 com o nome de Imperial Instituto dos Meninos Cegos, foi pioneiro na educação especializada no Brasil. Em 1891, recebeu o nome atual, em homenagem a Benjamin Constant, que dirigiu a instituição por muitos anos. Instalado em seu edifício histórico na Urca, desenvolve atividades educacionais, produção de materiais acessíveis, formação de profissionais e pesquisas relacionadas à deficiência visual.", importancia: null, endereco: "Avenida Pasteur, 350/368 — Urca", imagem: {"src": "assets/img/instituto-benjamin-constant.jpg", "alt": "Instituto Benjamin Constant", "fonte": "partiu__lugaresss.docx"} },
    { id: "escola-naval", nome: "Escola Naval", bairro: "ilha-de-villegagnon", lat: -22.913635, lng: -43.159937, categoria: "Educação", descricao: "A Escola Naval é a instituição de ensino superior responsável pela formação dos futuros oficiais da Marinha do Brasil. Sua origem remonta a 1782, quando foi criada em Lisboa como Academia Real de Guardas-Marinhas. Com a chegada da Família Real portuguesa ao Brasil, em 1808, foi transferida para o Rio de Janeiro e passou por diferentes instalações até se estabelecer na Ilha de Villegagnon, em 1938. Além de sua importância para a formação militar, está situada em um local marcado por episódios importantes da história da cidade, como a tentativa francesa de estabelecer uma colônia na Baía de Guanabara no século XVI.", importancia: null, endereco: "Avenida Rafael de Aboim, s/n — Ilha de Villegagnon", imagem: {"src": "assets/img/escola-naval.jpg", "alt": "Escola Naval", "fonte": "partiu__lugaresss.docx"} },
    { id: "universidade-federal-do-rio-de-janeiro-campus-praia-vermelha", nome: "Universidade Federal do Rio de Janeiro — Campus Praia Vermelha", bairro: "urca", lat: -22.952195, lng: -43.174441, categoria: "Educação", descricao: "O campus da Praia Vermelha da Universidade Federal do Rio de Janeiro reúne unidades acadêmicas e espaços históricos importantes para a universidade. Um de seus principais edifícios é o Palácio Universitário, construído originalmente para abrigar o Hospício Pedro II, inaugurado em 1852. Após o encerramento das atividades hospitalares, o prédio foi incorporado à universidade em 1948 e passou a integrar o campus. Atualmente, o local abriga diferentes unidades e espaços culturais da UFRJ, sendo também um importante patrimônio arquitetônico da cidade.", importancia: null, endereco: "Avenida Pasteur, 250 — Urca", imagem: {"src": "assets/img/universidade-federal-do-rio-de-janeiro-campus-praia-vermelha.jpg", "alt": "Universidade Federal do Rio de Janeiro — Campus Praia Vermelha", "fonte": "partiu__lugaresss.docx"} },
    { id: "colegio-de-aplicacao-da-ufrj-cap-ufrj", nome: "Colégio de Aplicação da UFRJ — CAp-UFRJ", bairro: "lagoa", lat: -22.96452, lng: -43.215672, categoria: "Educação", descricao: "O Colégio de Aplicação da Universidade Federal do Rio de Janeiro (CAp-UFRJ) foi criado em 1948 e tem como uma de suas principais características a integração entre educação básica, formação de professores, pesquisa e extensão universitária. Ao longo de sua história, funcionou em diferentes espaços da cidade até se estabelecer, em 1962, na Rua J.J. Seabra, na Lagoa. A instituição também é um espaço de experimentação pedagógica e de formação de estudantes e futuros profissionais da educação.", importancia: null, endereco: "Rua J.J. Seabra, s/n — Lagoa", imagem: {"src": "assets/img/colegio-de-aplicacao-da-ufrj-cap-ufrj.jpg", "alt": "Colégio de Aplicação da UFRJ — CAp-UFRJ", "fonte": "partiu__lugaresss.docx"} },
    { id: "pontificia-universidade-catolica-do-rio-de-janeiro-puc-rio", nome: "Pontifícia Universidade Católica do Rio de Janeiro — PUC-Rio", bairro: "gavea", lat: null, lng: null, categoria: "Educação", descricao: "A Pontifícia Universidade Católica do Rio de Janeiro (PUC-Rio) é uma universidade privada comunitária, fundada em 1941 e reconhecida por sua atuação no ensino, na pesquisa e na extensão. Seu campus principal está localizado na Gávea e reúne edifícios acadêmicos, bibliotecas, áreas verdes e espaços de convivência. A universidade oferece cursos em diversas áreas do conhecimento e mantém uma trajetória ligada à formação intelectual, científica e cultural do Rio de Janeiro.", importancia: null, endereco: "Rua Marquês de São Vicente, 225 — Gávea", imagem: {"src": "assets/img/pontificia-universidade-catolica-do-rio-de-janeiro-puc-rio.jpg", "alt": "Pontifícia Universidade Católica do Rio de Janeiro — PUC-Rio", "fonte": "partiu__lugaresss.docx"} },
    { id: "colegio-de-aplicacao-da-puc-rio", nome: "Colégio de Aplicação da PUC-Rio", bairro: "gavea", lat: -22.980578, lng: -43.235423, categoria: "Educação", descricao: "O Colégio Teresiano foi criado em 1956 como Colégio de Aplicação da PUC-Rio. Desenvolvido pela Instituição Teresiana, construiu sua trajetória com uma proposta pedagógica voltada à formação integral dos estudantes, à renovação das práticas de ensino e ao compromisso social. Atualmente, é uma instituição independente da universidade, mas mantém em sua história essa ligação com a experiência de aplicação pedagógica da PUC-Rio.", importancia: null, endereco: "Rua Marquês de São Vicente, 331 — Gávea", imagem: {"src": "assets/img/colegio-de-aplicacao-da-puc-rio.jpg", "alt": "Colégio de Aplicação da PUC-Rio", "fonte": "partiu__lugaresss.docx"} },
    { id: "escola-ort-brasil", nome: "Escola ORT Brasil", bairro: "botafogo", lat: -22.955434, lng: -43.187229, categoria: "Educação", descricao: "A Escola ORT Brasil iniciou suas atividades no país em 1943, oferecendo cursos profissionalizantes e programas de formação para empresas e para a comunidade. Localizada em Botafogo, atualmente oferece Ensino Fundamental II e Ensino Médio, com itinerários formativos em áreas como Biotecnologia, Eletrônica, Informática, Marketing e Multimídia. Sua proposta combina formação acadêmica e conhecimentos técnicos, aproximando os estudantes de diferentes campos da ciência, da tecnologia e do empreendedorismo.", importancia: null, endereco: "Rua Dona Mariana, 213 — Botafogo", imagem: {"src": "assets/img/escola-ort-brasil.jpg", "alt": "Escola ORT Brasil", "fonte": "partiu__lugaresss.docx"} },
    { id: "maternidade-escola-da-ufrj", nome: "Maternidade-Escola da UFRJ", bairro: "laranjeiras", lat: -22.932703, lng: -43.185253, categoria: "Educação", descricao: "A Maternidade-Escola da Universidade Federal do Rio de Janeiro, conhecida também como Maternidade de Laranjeiras, foi fundada em 18 de janeiro de 1904. Criada inicialmente para oferecer assistência a gestantes e recém-nascidos de famílias em situação de vulnerabilidade, tornou-se uma instituição importante para o desenvolvimento do ensino e da pesquisa em Obstetrícia no Brasil. Atualmente, integra a rede de saúde da UFRJ, oferecendo assistência especializada e contribuindo para a formação de profissionais da área médica.", importancia: null, endereco: "Rua das Laranjeiras, 180 — Laranjeiras", imagem: {"src": "assets/img/maternidade-escola-da-ufrj.jpg", "alt": "Maternidade-Escola da UFRJ", "fonte": "partiu__lugaresss.docx"} },
    { id: "observatorio-do-valongo-ufrj", nome: "Observatório do Valongo — UFRJ", bairro: "saude", lat: -22.898255, lng: -43.186507, categoria: "Educação", descricao: "O Observatório do Valongo, vinculado à Universidade Federal do Rio de Janeiro, é uma das instituições mais importantes para a história do ensino da Astronomia no Brasil. Foi fundado em 5 de julho de 1881, inicialmente no Morro de Santo Antônio, com o objetivo de apoiar as aulas práticas de Astronomia e Geodésia da Escola Politécnica. Na década de 1920, foi transferido para o Morro da Conceição, na região do Valongo, onde permanece até hoje. Atualmente, desenvolve atividades de ensino, pesquisa e divulgação científica, além de preservar instrumentos e documentos ligados à história da Astronomia.", importancia: null, endereco: "Ladeira Pedro Antônio, 43 — Saúde", imagem: {"src": "assets/img/observatorio-do-valongo-ufrj.jpg", "alt": "Observatório do Valongo — UFRJ", "fonte": "partiu__lugaresss.docx"} },
    { id: "estadio-das-laranjeiras", nome: "Estádio das Laranjeiras", bairro: "laranjeiras", lat: -22.936601, lng: -43.184429, categoria: "Esportes", descricao: "O Estádio das Laranjeiras, oficialmente chamado Estádio Presidente Manoel Schwartz, é um dos espaços mais importantes da história do futebol brasileiro. Inaugurado em 1919, foi construído pelo Fluminense Football Club para receber o Campeonato Sul-Americano de Seleções, atual Copa América, daquele ano. O local também entrou para a história por ter sediado a primeira partida da Seleção Brasileira, em 1914, ainda antes da construção do estádio. Por sua importância esportiva, é considerado um dos berços do futebol nacional.", importancia: null, endereco: "Rua Pinheiro Machado, 86 — Laranjeiras", imagem: {"src": "assets/img/estadio-das-laranjeiras.jpg", "alt": "Estádio das Laranjeiras", "fonte": "partiu__lugaresss.docx"} },
    { id: "estadio-da-gavea-jose-bastos-padilha", nome: "Estádio da Gávea — José Bastos Padilha", bairro: "lagoa", lat: -22.978097, lng: -43.221131, categoria: "Esportes", descricao: "O Estádio José Bastos Padilha, conhecido como Estádio da Gávea, pertence ao Clube de Regatas do Flamengo e foi inaugurado em 4 de setembro de 1938. Seu nome homenageia José Bastos Padilha, presidente do clube durante o período em que o projeto foi desenvolvido. Embora o Flamengo passe a disputar a maior parte de seus jogos em outros estádios, a Gávea continua sendo uma importante referência esportiva e faz parte da história do clube, abrigando sua sede e diversas instalações destinadas à prática esportiva.", importancia: null, endereco: "Avenida Borges de Medeiros, 997 — Lagoa", imagem: {"src": "assets/img/estadio-da-gavea-jose-bastos-padilha.jpg", "alt": "Estádio da Gávea — José Bastos Padilha", "fonte": "partiu__lugaresss.docx"} },
    { id: "castelinho-do-flamengo", nome: "Castelinho do Flamengo", bairro: "flamengo", lat: -22.930085, lng: -43.174547, categoria: "História/Patrimônio", descricao: "O Castelinho do Flamengo é uma construção histórica inaugurada em 1918, projetada pelo arquiteto italiano Gino Coppedè e executada pelo arquiteto Francisco dos Santos. Com uma aparência que mistura diferentes referências arquitetônicas, o edifício se destaca na paisagem da Praia do Flamengo. Após correr o risco de ser demolido na década de 1980, foi preservado graças à mobilização de moradores e defensores do patrimônio, sendo tombado em 1983. Atualmente, abriga o Centro Cultural Municipal Oduvaldo Vianna Filho e recebe atividades culturais e artísticas.", importancia: null, endereco: "Praia do Flamengo, 158 — Flamengo", imagem: {"src": "assets/img/castelinho-do-flamengo.jpg", "alt": "Castelinho do Flamengo", "fonte": "partiu__lugaresss.docx"} },
    { id: "fortaleza-de-sao-joao", nome: "Fortaleza de São João", bairro: "urca", lat: -22.943669, lng: -43.158634, categoria: "História/Patrimônio", descricao: "A Fortaleza de São João é um dos principais marcos da história militar e da fundação da cidade do Rio de Janeiro. Sua origem remonta a 1565, quando Estácio de Sá e suas tropas desembarcaram na região entre o Morro Cara de Cão e o Pão de Açúcar e construíram um primeiro fortim durante a luta contra os franceses. Ao longo dos séculos, a estrutura foi ampliada e reforçada, formando um conjunto de fortificações destinado à defesa da entrada da Baía de Guanabara. Atualmente, permanece sob responsabilidade do Exército Brasileiro e preserva importantes registros da história da cidade.", importancia: null, endereco: "Avenida João Luís Alves, s/n — Urca", imagem: {"src": "assets/img/fortaleza-de-sao-joao.jpg", "alt": "Fortaleza de São João", "fonte": "partiu__lugaresss.docx"} },
    { id: "monumento-nacional-aos-mortos-da-segunda-guerra-mundial", nome: "Monumento Nacional aos Mortos da Segunda Guerra Mundial", bairro: "gloria", lat: -22.916456, lng: -43.173539, categoria: "História/Patrimônio", descricao: "O Monumento Nacional aos Mortos da Segunda Guerra Mundial, conhecido como Monumento aos Pracinhas, foi inaugurado em 1960 no Aterro do Flamengo. O espaço foi criado para homenagear os militares brasileiros que morreram durante a Segunda Guerra Mundial, especialmente aqueles que participaram da campanha da Força Expedicionária Brasileira na Itália. Projetado pelos arquitetos Marcos Konder Netto e Hélio Ribas Marinho, o conjunto reúne um mausoléu, um museu e elementos simbólicos, como a chama do Túmulo do Soldado Desconhecido. É um importante espaço de memória e homenagem à participação brasileira no conflito.", importancia: null, endereco: "Avenida Infante Dom Henrique, 75 — Glória", imagem: {"src": "assets/img/monumento-nacional-aos-mortos-da-segunda-guerra-mundial.jpg", "alt": "Monumento Nacional aos Mortos da Segunda Guerra Mundial", "fonte": "partiu__lugaresss.docx"} },
    { id: "palacio-do-catete-museu-da-republica", nome: "Palácio do Catete — Museu da República", bairro: "catete", lat: -22.925694, lng: -43.17627, categoria: "História/Patrimônio", descricao: "O Palácio do Catete, atual sede do Museu da República, foi construído em meados do século XIX para servir de residência ao Barão de Nova Friburgo. Em 1897, o edifício foi adquirido pelo governo federal e transformado em sede da Presidência da República, função que exerceu até 1960, quando a capital do país foi transferida para Brasília. Ao longo desse período, foi palco de importantes acontecimentos políticos da história brasileira. Desde novembro de 1960, abriga o Museu da República, que preserva documentos, objetos, obras de arte e ambientes históricos relacionados à trajetória republicana do país.", importancia: null, endereco: "Rua do Catete, 153 — Catete", imagem: {"src": "assets/img/palacio-do-catete-museu-da-republica.jpg", "alt": "Palácio do Catete — Museu da República", "fonte": "partiu__lugaresss.docx"} },
    { id: "solar-grandjean-de-montigny", nome: "Solar Grandjean de Montigny", bairro: "gavea", lat: -22.978832, lng: -43.233812, categoria: "História/Patrimônio", descricao: "O Solar Grandjean de Montigny é uma das construções mais representativas da arquitetura neoclássica no Rio de Janeiro. Construído na década de 1820, foi residência do arquiteto francês Auguste Henri Victor Grandjean de Montigny, integrante da Missão Artística Francesa que chegou ao Brasil em 1816. O edifício é considerado um importante exemplo da adaptação do estilo neoclássico ao clima brasileiro e foi tombado pelo IPHAN em 1938. Atualmente, integra a PUC-Rio e funciona como museu universitário e centro cultural, recebendo exposições e atividades artísticas.", importancia: null, endereco: "Rua Marquês de São Vicente, 225 — Gávea", imagem: {"src": "assets/img/solar-grandjean-de-montigny.jpg", "alt": "Solar Grandjean de Montigny", "fonte": "partiu__lugaresss.docx"} },
    { id: "museu-historico-da-cidade-do-rio-de-janeiro", nome: "Museu Histórico da Cidade do Rio de Janeiro", bairro: "gavea", lat: -22.978542, lng: -43.244885, categoria: "História/Patrimônio", descricao: "O Museu Histórico da Cidade do Rio de Janeiro foi inaugurado em 1934 e está instalado em um palacete do século XIX, localizado no Parque da Cidade, na Gávea. Seu acervo reúne milhares de peças relacionadas à trajetória carioca, incluindo fotografias, pinturas, documentos, mapas, mobiliário e objetos históricos. Por meio de exposições e atividades educativas, o museu apresenta as transformações sociais, culturais, políticas e urbanas da cidade ao longo do tempo. O próprio edifício também faz parte desse patrimônio, por sua arquitetura e ligação com a antiga ocupação da região.", importancia: null, endereco: "Estrada de Santa Marinha, s/n — Gávea", imagem: {"src": "assets/img/museu-historico-da-cidade-do-rio-de-janeiro.jpg", "alt": "Museu Histórico da Cidade do Rio de Janeiro", "fonte": "partiu__lugaresss.docx"} },
    { id: "vila-operaria-da-fabrica-alianca", nome: "Vila Operária da Fábrica Aliança", bairro: "laranjeiras", lat: -22.937808, lng: -43.188454, categoria: "Indústria/Urbanização", descricao: "A Vila Operária da Fábrica Aliança está relacionada à história da Companhia de Fiações e Tecidos Aliança, instalada em Laranjeiras por volta de 1880. A fábrica chegou a empregar mais de mil trabalhadores e funcionou até 1938, contribuindo para transformar o perfil do bairro, que passou a reunir residências operárias, comércio e espaços de convivência. As vilas construídas para abrigar os funcionários representam um importante registro da relação entre industrialização, moradia e crescimento urbano no Rio de Janeiro.", importancia: null, endereco: "Rua Cardoso Júnior — Laranjeiras", imagem: {"src": "assets/img/vila-operaria-da-fabrica-alianca.jpg", "alt": "Vila Operária da Fábrica Aliança", "fonte": "partiu__lugaresss.docx"} },
    { id: "parque-natural-municipal-paisagem-carioca", nome: "Parque Natural Municipal Paisagem Carioca", bairro: "leme", lat: null, lng: null, categoria: "Natureza/Paisagens", descricao: "O Parque Natural Municipal Paisagem Carioca foi criado em 2013 e protege áreas naturais distribuídas entre Leme, Copacabana, Botafogo e Urca. A unidade de conservação reúne trechos de Mata Atlântica, encostas verdes e trilhas que permitem conhecer paisagens marcantes da Zona Sul. Além de preservar a biodiversidade local, o parque contribui para proteger áreas naturais que fazem parte da identidade visual do Rio de Janeiro.", importancia: null, endereco: "Leme / Copacabana / Botafogo / Urca", imagem: {"src": "assets/img/parque-natural-municipal-paisagem-carioca.jpg", "alt": "Parque Natural Municipal Paisagem Carioca", "fonte": "partiu__lugaresss.docx"} },
    { id: "parque-natural-municipal-do-penhasco-dois-irmaos", nome: "Parque Natural Municipal do Penhasco Dois Irmãos", bairro: "leblon", lat: -22.989014, lng: -43.22882, categoria: "Natureza/Paisagens", descricao: "O Parque Natural Municipal do Penhasco Dois Irmãos, também associado ao nome Parque Natural Municipal Dois Cariocas – Dois Irmãos, está localizado no Leblon e protege uma área de Mata Atlântica nas encostas do Morro Dois Irmãos. O parque possui trilhas, áreas de convivência e mirantes que oferecem vistas da orla, da Lagoa Rodrigo de Freitas e de diferentes bairros da Zona Sul. Sua vegetação abriga espécies nativas e animais característicos da Mata Atlântica, contribuindo para a preservação ambiental em meio à área urbana.", importancia: null, endereco: "Rua Aperana — Leblon", imagem: {"src": "assets/img/parque-natural-municipal-do-penhasco-dois-irmaos.jpg", "alt": "Parque Natural Municipal do Penhasco Dois Irmãos", "fonte": "partiu__lugaresss.docx"} },
    { id: "parque-natural-municipal-da-catacumba", nome: "Parque Natural Municipal da Catacumba", bairro: "lagoa", lat: -22.972321, lng: -43.202716, categoria: "Natureza/Paisagens", descricao: "O Parque Natural Municipal da Catacumba está localizado às margens da Lagoa Rodrigo de Freitas e combina preservação ambiental, lazer e arte. Criado após o processo de remoção da antiga comunidade da Catacumba, no início da década de 1970, o espaço passou por um trabalho de reflorestamento e foi transformado em parque. Atualmente, possui trilhas, mirantes e esculturas expostas ao ar livre, formando uma espécie de museu a céu aberto em meio à vegetação.", importancia: null, endereco: "Avenida Epitácio Pessoa, 3000 — Lagoa", imagem: {"src": "assets/img/parque-natural-municipal-da-catacumba.jpg", "alt": "Parque Natural Municipal da Catacumba", "fonte": "partiu__lugaresss.docx"} },
    { id: "parque-natural-municipal-da-cidade", nome: "Parque Natural Municipal da Cidade", bairro: "gavea", lat: -22.979571, lng: -43.242337, categoria: "Natureza/Paisagens", descricao: "O Parque Natural Municipal da Cidade ocupa uma área de aproximadamente 46 hectares entre a Gávea e o Alto da Boa Vista. Sua origem está ligada à antiga propriedade do Marquês de São Vicente, doada ao governo em 1939. Criado em 1941 e transformado em unidade de conservação de proteção integral em 2008, o parque reúne jardins, trilhas, áreas de lazer e espaços para atividades culturais. Também abriga o Museu Histórico da Cidade do Rio de Janeiro, conectando a preservação ambiental à memória carioca.", importancia: null, endereco: "Estrada Santa Marinha, 505 — Gávea", imagem: {"src": "assets/img/parque-natural-municipal-da-cidade.jpg", "alt": "Parque Natural Municipal da Cidade", "fonte": "partiu__lugaresss.docx"} },
    { id: "parque-natural-municipal-de-marapendi", nome: "Parque Natural Municipal de Marapendi", bairro: "barra-da-tijuca", lat: null, lng: null, categoria: "Natureza/Paisagens", descricao: "O Parque Natural Municipal de Marapendi protege importantes ecossistemas costeiros da Zona Oeste do Rio de Janeiro, especialmente áreas de restinga e manguezal próximas à Lagoa de Marapendi. Criado em 1978, o parque abriga espécies da fauna e da flora características desses ambientes, incluindo o jacaré-de-papo-amarelo e a borboleta-da-praia. Além de contribuir para a conservação da biodiversidade, oferece trilhas e atividades de educação ambiental para aproximar os visitantes da natureza.", importancia: null, endereco: "Barra da Tijuca", imagem: {"src": "assets/img/parque-natural-municipal-de-marapendi.jpg", "alt": "Parque Natural Municipal de Marapendi", "fonte": "partiu__lugaresss.docx"} },
    { id: "parque-natural-municipal-chico-mendes", nome: "Parque Natural Municipal Chico Mendes", bairro: "recreio-dos-bandeirantes", lat: -23.022372, lng: -43.47188, categoria: "Natureza/Paisagens", descricao: "O Parque Natural Municipal Chico Mendes foi criado em 1989 para proteger a Lagoinha das Tachas e os ambientes naturais ao seu redor, na região do Recreio dos Bandeirantes. Situado em uma área de restinga, o parque preserva espécies importantes da fauna e da flora locais, com destaque para o jacaré-de-papo-amarelo, além de diversas aves e outros animais. Com trilhas sinalizadas e espaços voltados à educação ambiental, é um importante refúgio de biodiversidade em uma região marcada pela expansão urbana.", importancia: null, endereco: "Avenida Jarbas de Carvalho, 679 — Recreio dos Bandeirantes", imagem: {"src": "assets/img/parque-natural-municipal-chico-mendes.jpg", "alt": "Parque Natural Municipal Chico Mendes", "fonte": "partiu__lugaresss.docx"} },
    { id: "parque-natural-municipal-de-grumari", nome: "Parque Natural Municipal de Grumari", bairro: "grumari", lat: -23.048998, lng: -43.534022, categoria: "Natureza/Paisagens", descricao: "O Parque Natural Municipal de Grumari protege uma extensa área de Mata Atlântica e ecossistemas costeiros na Zona Oeste do Rio de Janeiro. Inserido em uma região de grande beleza natural, reúne morros, encostas florestadas, vegetação de restinga e áreas próximas ao litoral. Sua preservação é importante para proteger a biodiversidade e manter as características naturais de uma das regiões menos urbanizadas da orla carioca.", importancia: null, endereco: "Grumari", imagem: {"src": "assets/img/parque-natural-municipal-de-grumari.jpg", "alt": "Parque Natural Municipal de Grumari", "fonte": "partiu__lugaresss.docx"} },
    { id: "parque-natural-municipal-da-prainha", nome: "Parque Natural Municipal da Prainha", bairro: "recreio-dos-bandeirantes", lat: -23.033089, lng: -43.505471, categoria: "Natureza/Paisagens", descricao: "O Parque Natural Municipal da Prainha foi criado para proteger uma importante área de Mata Atlântica no Recreio dos Bandeirantes. Cercado por morros e localizado junto à praia que lhe dá nome, o parque conserva ecossistemas costeiros e vegetação nativa, contribuindo para a proteção da paisagem e da biodiversidade da região. É também um espaço de contato com a natureza, procurado por visitantes que desejam conhecer uma parte mais preservada do litoral carioca.", importancia: null, endereco: "Prainha", imagem: {"src": "assets/img/parque-natural-municipal-da-prainha.jpg", "alt": "Parque Natural Municipal da Prainha", "fonte": "partiu__lugaresss.docx"} },
    { id: "parque-natural-municipal-bosque-da-barra", nome: "Parque Natural Municipal Bosque da Barra", bairro: "barra-da-tijuca", lat: -22.998014, lng: -43.371908, categoria: "Natureza/Paisagens", descricao: "O Parque Natural Municipal Bosque da Barra, também conhecido como Parque Arruda Câmara, foi criado em 1983 para proteger os ambientes naturais da Barra da Tijuca em meio ao processo de urbanização da região. Localizado em uma planície costeira, abriga vegetação de restinga, lagoas e áreas verdes que servem de habitat para diferentes espécies de animais. Além de sua importância ambiental, oferece espaços de lazer e contemplação, funcionando como um refúgio natural dentro de uma área bastante urbanizada da cidade.", importancia: null, endereco: "Avenida das Américas, 6000 — Barra da Tijuca", imagem: {"src": "assets/img/parque-natural-municipal-bosque-da-barra.jpg", "alt": "Parque Natural Municipal Bosque da Barra", "fonte": "partiu__lugaresss.docx"} },
    { id: "monumento-natural-dos-morros-do-pao-de-acucar-e-da-urca", nome: "Monumento Natural dos Morros do Pão de Açúcar e da Urca", bairro: "urca", lat: -22.953619, lng: -43.163351, categoria: "Natureza/Paisagens", descricao: "O Monumento Natural dos Morros do Pão de Açúcar e da Urca protege um dos conjuntos paisagísticos mais conhecidos do Rio de Janeiro. Criado em 2006, preserva áreas de Mata Atlântica, formações rochosas e a biodiversidade presente nos morros. O local reúne atrações como o Bondinho, a Trilha do Morro da Urca e a Pista Cláudio Coutinho, permitindo diferentes formas de contato com a natureza. Sua paisagem também integra o conjunto reconhecido pela UNESCO como Patrimônio Mundial em 2012.", importancia: null, endereco: "Urca", imagem: {"src": "assets/img/monumento-natural-dos-morros-do-pao-de-acucar-e-da-urca.jpg", "alt": "Monumento Natural dos Morros do Pão de Açúcar e da Urca", "fonte": "partiu__lugaresss.docx"} },
    { id: "monumento-natural-das-ilhas-cagarras", nome: "Monumento Natural das Ilhas Cagarras", bairro: "ilhas-cagarras", lat: -23.037984, lng: -43.20432, categoria: "Natureza/Paisagens", descricao: "O Monumento Natural do Arquipélago das Ilhas Cagarras é uma unidade de conservação federal criada em 2010, localizada no Oceano Atlântico, a aproximadamente cinco quilômetros da Praia de Ipanema. Formado por ilhas e ilhotas rochosas, protege ecossistemas insulares da Mata Atlântica e áreas utilizadas por aves marinhas para abrigo e reprodução. Além de sua importância para a biodiversidade, o arquipélago se destaca pela beleza natural e pela presença marcante na paisagem da orla da Zona Sul.", importancia: null, endereco: "Oceano Atlântico — em frente à Zona Sul", imagem: {"src": "assets/img/monumento-natural-das-ilhas-cagarras.jpg", "alt": "Monumento Natural das Ilhas Cagarras", "fonte": "partiu__lugaresss.docx"} },
    { id: "praia-de-grumari", nome: "Praia de Grumari", bairro: "grumari", lat: -23.045997, lng: -43.526303, categoria: "Natureza/Paisagens", descricao: "A Praia de Grumari está localizada na Zona Oeste do Rio de Janeiro e se destaca por sua paisagem cercada por morros cobertos de vegetação e áreas naturais preservadas. Por estar situada em uma região protegida, mantém características ambientais diferentes das praias mais urbanizadas da cidade. Sua extensa faixa de areia e o cenário natural fazem dela um importante espaço de lazer e também de conservação dos ecossistemas costeiros.", importancia: null, endereco: "Grumari", imagem: {"src": "assets/img/praia-de-grumari.jpg", "alt": "Praia de Grumari", "fonte": "partiu__lugaresss.docx"} },
    { id: "praia-da-prainha", nome: "Praia da Prainha", bairro: "recreio-dos-bandeirantes", lat: -23.037334, lng: -43.507265, categoria: "Natureza/Paisagens", descricao: "A Praia da Prainha é uma pequena praia oceânica localizada no Recreio dos Bandeirantes, cercada por morros cobertos de Mata Atlântica. Com aproximadamente 700 metros de extensão, é conhecida pelas ondas fortes e pelas condições favoráveis à prática do surfe. A paisagem preservada e a presença de áreas naturais protegidas tornam o local um dos principais exemplos de integração entre litoral e vegetação nativa na cidade.", importancia: null, endereco: "Recreio dos Bandeirantes", imagem: {"src": "assets/img/praia-da-prainha.jpg", "alt": "Praia da Prainha", "fonte": "partiu__lugaresss.docx"} },
    { id: "praia-da-reserva", nome: "Praia da Reserva", bairro: "barra-da-tijuca", lat: -23.012229, lng: -43.394537, categoria: "Natureza/Paisagens", descricao: "A Praia da Reserva está localizada entre a Barra da Tijuca e o Recreio dos Bandeirantes, em um trecho da orla marcado pela presença de áreas naturais protegidas. Seu nome está relacionado à proximidade com a região de Marapendi, que conserva ecossistemas como restingas e manguezais. Com uma extensa faixa de areia e menor concentração de construções junto à praia, destaca-se pela paisagem mais aberta e pela importância ambiental de seu entorno.", importancia: null, endereco: "Barra da Tijuca", imagem: {"src": "assets/img/praia-da-reserva.jpg", "alt": "Praia da Reserva", "fonte": "partiu__lugaresss.docx"} },
    { id: "praia-do-leme", nome: "Praia do Leme", bairro: "leme", lat: -22.962555, lng: -43.166845, categoria: "Natureza/Paisagens", descricao: "A Praia do Leme ocupa o trecho inicial da orla de Copacabana, junto ao Morro do Leme. Conhecida pela faixa de areia que acompanha a Avenida Atlântica e pela vista do litoral da Zona Sul, é um dos espaços tradicionais de lazer da cidade. A praia também está integrada à Área de Proteção Ambiental da Orla Marítima, criada para contribuir com a preservação do conjunto paisagístico e ambiental do litoral carioca.", importancia: null, endereco: "Leme", imagem: {"src": "assets/img/praia-do-leme.jpg", "alt": "Praia do Leme", "fonte": "partiu__lugaresss.docx"} },
    { id: "praia-de-ipanema", nome: "Praia de Ipanema", bairro: "ipanema", lat: -22.986895, lng: -43.204774, categoria: "Natureza/Paisagens", descricao: "A Praia de Ipanema é um dos cartões-postais mais conhecidos do Rio de Janeiro e possui grande importância para a cultura e a identidade carioca. Sua orla ganhou projeção internacional, especialmente a partir da década de 1960, quando a música e o movimento cultural da Bossa Nova ajudaram a divulgar o bairro e sua paisagem. Além de ser um espaço de lazer e prática de esportes, integra um conjunto paisagístico protegido da cidade.", importancia: null, endereco: "Ipanema", imagem: {"src": "assets/img/praia-de-ipanema.jpg", "alt": "Praia de Ipanema", "fonte": "partiu__lugaresss.docx"} },
    { id: "lagoa-rodrigo-de-freitas", nome: "Lagoa Rodrigo de Freitas", bairro: "lagoa", lat: -22.970764, lng: -43.21197, categoria: "Natureza/Paisagens", descricao: "A Lagoa Rodrigo de Freitas é um dos principais elementos naturais da Zona Sul do Rio de Janeiro. Seu nome tem origem em Rodrigo de Freitas Castro e Mello, que adquiriu terras na região em meados do século XVI. Ao longo do tempo, a área passou por transformações relacionadas à expansão urbana, incluindo aterros que reduziram significativamente sua extensão original. Atualmente, a lagoa é um importante espaço de lazer, prática esportiva e contemplação, além de fazer parte do patrimônio paisagístico da cidade.", importancia: null, endereco: "Lagoa", imagem: {"src": "assets/img/lagoa-rodrigo-de-freitas.jpg", "alt": "Lagoa Rodrigo de Freitas", "fonte": "partiu__lugaresss.docx"} },
    { id: "restinga-de-marapendi", nome: "Restinga de Marapendi", bairro: "barra-da-tijuca", lat: -23.011602, lng: -43.449653, categoria: "Natureza/Paisagens", descricao: "A Restinga de Marapendi é um ecossistema costeiro formado por vegetação adaptada às condições de solo arenoso, salinidade e exposição ao vento. Localizada na região da Barra da Tijuca e do Recreio, integra um conjunto ambiental que inclui lagoas, manguezais e áreas de Mata Atlântica. Sua preservação é fundamental para a proteção de espécies nativas, para a manutenção da biodiversidade e para o equilíbrio ambiental da faixa litorânea da cidade.", importancia: null, endereco: "Barra da Tijuca / Recreio", imagem: {"src": "assets/img/restinga-de-marapendi.jpg", "alt": "Restinga de Marapendi", "fonte": "partiu__lugaresss.docx"} },
    { id: "parque-lage", nome: "Parque Lage", bairro: "jardim-botanico", lat: -22.960925, lng: -43.212717, categoria: "Natureza/Paisagens", descricao: "O Parque Lage é um parque público localizado aos pés do Morro do Corcovado, no Jardim Botânico. Sua história começou no período colonial, quando a área abrigava um engenho de açúcar, e passou por diferentes proprietários e transformações ao longo dos séculos. Na década de 1920, Henrique Lage promoveu a construção do palacete que se tornou um dos símbolos do espaço. Atualmente, o parque reúne jardins, trilhas em meio à Mata Atlântica e áreas de convivência, além de abrigar a Escola de Artes Visuais do Parque Lage.", importancia: null, endereco: "Rua Jardim Botânico, 414 — Jardim Botânico", imagem: {"src": "assets/img/parque-lage.jpg", "alt": "Parque Lage", "fonte": "partiu__lugaresss.docx"} },
    { id: "mirante-dona-marta", nome: "Mirante Dona Marta", bairro: "cosme-velho", lat: -22.944791, lng: -43.196342, categoria: "Natureza/Paisagens", descricao: "O Mirante Dona Marta está localizado a aproximadamente 360 metros de altitude, dentro do Parque Nacional da Tijuca. De sua plataforma de observação é possível contemplar uma vista panorâmica de importantes paisagens cariocas, como o Cristo Redentor, o Pão de Açúcar, a Baía de Guanabara e o Maracanã. Por sua localização privilegiada, tornou-se um dos pontos mais conhecidos da cidade para observar e fotografar a paisagem do Rio de Janeiro.", importancia: null, endereco: "Estrada do Mirante Dona Marta — Cosme Velho", imagem: {"src": "assets/img/mirante-dona-marta.jpg", "alt": "Mirante Dona Marta", "fonte": "partiu__lugaresss.docx"} },
    { id: "mirante-do-leblon", nome: "Mirante do Leblon", bairro: "leblon", lat: -22.989823, lng: -43.227443, categoria: "Natureza/Paisagens", descricao: "O Mirante do Leblon está localizado no final da Avenida Niemeyer e oferece uma vista privilegiada da orla da Zona Sul do Rio de Janeiro. Do local, é possível observar as praias do Leblon e de Ipanema, além do Morro Dois Irmãos e do litoral em direção a São Conrado. Sua posição junto à avenida faz dele um ponto tradicional de contemplação da paisagem, especialmente para quem deseja apreciar o encontro entre o mar, as montanhas e a cidade.", importancia: null, endereco: "Avenida Niemeyer — Leblon", imagem: {"src": "assets/img/mirante-do-leblon.jpg", "alt": "Mirante do Leblon", "fonte": "partiu__lugaresss.docx"} },
    { id: "monumento-a-estacio-de-sa", nome: "Monumento a Estácio de Sá", bairro: "flamengo", lat: -22.939731, lng: -43.169608, categoria: "Personalidades/Memória", descricao: "O Monumento a Estácio de Sá foi inaugurado em 1973 e homenageia o militar português considerado fundador da cidade do Rio de Janeiro, em 1565. Projetado pelo arquiteto Lúcio Costa, o conjunto possui formato de pirâmide e obelisco, com uma de suas extremidades direcionada simbolicamente ao local de fundação da cidade. Na parte subterrânea, há um espaço que abriga a lápide de Estácio de Sá, tornando o monumento também um local de memória sobre os primeiros anos da ocupação portuguesa no território carioca.", importancia: null, endereco: "Aterro do Flamengo — Flamengo", imagem: {"src": "assets/img/monumento-a-estacio-de-sa.jpg", "alt": "Monumento a Estácio de Sá", "fonte": "partiu__lugaresss.docx"} },
    { id: "estatua-de-carlos-drummond-de-andrade", nome: "Estátua de Carlos Drummond de Andrade", bairro: "copacabana", lat: -22.98429, lng: -43.189156, categoria: "Personalidades/Memória", descricao: "A estátua de Carlos Drummond de Andrade foi instalada em Copacabana em 2002, em comemoração ao centenário de nascimento do poeta. Criada pelo escultor Leo Santana e inspirada em uma fotografia de Rogério Reis, a obra retrata Drummond sentado em um banco, contemplando a paisagem da praia. O monumento tornou-se um dos pontos mais conhecidos do bairro e uma homenagem permanente a um dos maiores nomes da literatura brasileira, que viveu grande parte de sua vida no Rio de Janeiro.", importancia: null, endereco: "Avenida Atlântica — Copacabana", imagem: {"src": "assets/img/estatua-de-carlos-drummond-de-andrade.jpg", "alt": "Estátua de Carlos Drummond de Andrade", "fonte": "partiu__lugaresss.docx"} },
    { id: "estatua-de-tom-jobim", nome: "Estátua de Tom Jobim", bairro: "ipanema", lat: -22.987893, lng: -43.194577, categoria: "Personalidades/Memória", descricao: "A estátua de Tom Jobim foi inaugurada em 2014, na orla de Ipanema, em homenagem aos 20 anos da morte do compositor. Criada pela escultora Christina Motta, a obra retrata o músico caminhando com um violão no ombro, em referência à sua ligação com a música e com a paisagem carioca. A escolha da região próxima ao Arpoador também remete à relação de Tom com o mar e com Ipanema, bairro eternizado em uma de suas composições mais conhecidas, Garota de Ipanema.", importancia: null, endereco: "Arpoador — Ipanema", imagem: {"src": "assets/img/estatua-de-tom-jobim.jpg", "alt": "Estátua de Tom Jobim", "fonte": "partiu__lugaresss.docx"} },
    { id: "monumento-a-chacrinha", nome: "Monumento a Chacrinha", bairro: "jardim-botanico", lat: -22.966852, lng: -43.218338, categoria: "Personalidades/Memória", descricao: "O monumento a Abelardo Barbosa, conhecido como Chacrinha ou Velho Guerreiro, foi inaugurado em 2010 no Jardim Botânico. Criada pelo escultor Ique Woitschach, a estátua de bronze retrata o apresentador com elementos que marcaram sua personalidade na televisão, como a gravata-borboleta, a buzina e o bacalhau. Chacrinha foi um dos comunicadores mais populares do Brasil entre as décadas de 1950 e 1980, conhecido por seus programas de auditório, bordões e pela maneira irreverente de interagir com o público. O monumento foi instalado próximo ao antigo Teatro Fênix, onde ele gravava seus programas.", importancia: null, endereco: "Rua Jardim Botânico — Jardim Botânico", imagem: {"src": "assets/img/monumento-a-chacrinha.jpg", "alt": "Monumento a Chacrinha", "fonte": "partiu__lugaresss.docx"} },
    { id: "museu-villa-lobos", nome: "Museu Villa-Lobos", bairro: "botafogo", lat: -22.951684, lng: -43.190508, categoria: "Personalidades/Memória", descricao: "O Museu Villa-Lobos foi criado em 1960, um ano após a morte do compositor Heitor Villa-Lobos, com a finalidade de preservar e divulgar sua vida e obra. Instalado em um casarão tombado do século XIX, em Botafogo, reúne um acervo com mais de 53 mil itens, incluindo partituras, fotografias, correspondências, instrumentos musicais, gravações e objetos pessoais. A instituição permite conhecer a trajetória de um dos compositores mais importantes da música brasileira e sua contribuição para a valorização de elementos da cultura nacional. O casarão que abriga o museu não foi residência de Villa-Lobos.", importancia: null, endereco: "Rua Sorocaba, 200 — Botafogo", imagem: {"src": "assets/img/museu-villa-lobos.jpg", "alt": "Museu Villa-Lobos", "fonte": "partiu__lugaresss.docx"} },
    { id: "fundacao-casa-de-rui-barbosa", nome: "Fundação Casa de Rui Barbosa", bairro: "botafogo", lat: -22.948524, lng: -43.187015, categoria: "Personalidades/Memória", descricao: "A Fundação Casa de Rui Barbosa preserva a antiga residência do jurista, escritor e político Rui Barbosa, localizada em Botafogo. Construída em 1850, a casa foi adquirida por Rui Barbosa e sua esposa, Maria Augusta, em 1893, e serviu de residência para a família até 1923. Em 1924, o imóvel foi vendido ao governo federal e, posteriormente, transformado em museu. Atualmente, o conjunto reúne a casa histórica, um jardim preservado, biblioteca e espaços dedicados à pesquisa e à memória de Rui Barbosa, uma das figuras importantes da história política e intelectual brasileira.", importancia: null, endereco: "Rua São Clemente, 134 — Botafogo", imagem: {"src": "assets/img/fundacao-casa-de-rui-barbosa.jpg", "alt": "Fundação Casa de Rui Barbosa", "fonte": "partiu__lugaresss.docx"} },
    { id: "instituto-casa-roberto-marinho", nome: "Instituto Casa Roberto Marinho", bairro: "cosme-velho", lat: -22.939791, lng: -43.204282, categoria: "Personalidades/Memória", descricao: "O Instituto Casa Roberto Marinho está instalado na antiga residência do jornalista e empresário Roberto Marinho, no Cosme Velho. A construção começou em 1939 e foi inaugurada em 1943, com arquitetura inspirada no estilo neocolonial. Durante décadas, a casa recebeu encontros culturais e sociais, reunindo artistas, escritores e personalidades. Em 2018, o espaço foi transformado em instituto cultural aberto ao público, dedicado à preservação e à exposição da Coleção Roberto Marinho, formada principalmente por obras de arte moderna brasileira. O conjunto também se destaca pelo jardim projetado por Burle Marx.", importancia: null, endereco: "Rua Cosme Velho, 1105 — Cosme Velho", imagem: {"src": "assets/img/instituto-casa-roberto-marinho.jpg", "alt": "Instituto Casa Roberto Marinho", "fonte": "partiu__lugaresss.docx"} },
    { id: "instituto-moreira-salles-ims-rio", nome: "Instituto Moreira Salles — IMS Rio", bairro: "gavea", lat: -22.981508, lng: -43.239419, categoria: "Personalidades/Memória", descricao: "O Instituto Moreira Salles do Rio de Janeiro está instalado na antiga residência do empresário e diplomata Walther Moreira Salles, na Gávea. Projetada pelo arquiteto Olavo Redig de Campos em 1948 e inaugurada em 1951, a construção é um importante exemplo da arquitetura moderna brasileira. O conjunto também se destaca pelos jardins projetados por Roberto Burle Marx e pela integração com a vegetação da região. Desde 1999, funciona como centro cultural, recebendo exposições, atividades educativas e eventos, além de preservar e divulgar importantes acervos de fotografia, música e literatura.", importancia: null, endereco: "Rua Marquês de São Vicente, 476 — Gávea", imagem: {"src": "assets/img/instituto-moreira-salles-ims-rio.jpg", "alt": "Instituto Moreira Salles — IMS Rio", "fonte": "partiu__lugaresss.docx"} },
    { id: "museu-da-imagem-e-do-som-mis", nome: "Museu da Imagem e do Som — MIS", bairro: "copacabana", lat: -22.978886, lng: -43.189703, categoria: "Personalidades/Memória", descricao: "O Museu da Imagem e do Som do Rio de Janeiro foi criado em 1965 com a missão de preservar e divulgar a memória audiovisual e musical do estado. Sua nova sede em Copacabana foi projetada pelo escritório Diller Scofidio + Renfro e chama atenção pela arquitetura que transforma a circulação vertical do edifício em uma espécie de passeio pela paisagem cultural carioca. Após um longo período de obras, o prédio começou a receber visitantes em 2026, com abertura gradual e exposições sobre sua própria construção. O acervo do museu reúne registros sonoros, fotografias, filmes e outros documentos importantes para a história cultural brasileira.", importancia: null, endereco: "Avenida Atlântica, 3432 — Copacabana", imagem: {"src": "assets/img/museu-da-imagem-e-do-som-mis.jpg", "alt": "Museu da Imagem e do Som — MIS", "fonte": "partiu__lugaresss.docx"} },
    { id: "monumento-a-getulio-vargas", nome: "Monumento a Getúlio Vargas", bairro: "gloria", lat: -22.921382, lng: -43.173507, categoria: "Personalidades/Memória", descricao: "O Memorial Municipal Getúlio Vargas foi inaugurado em 2004, na Glória, cinquenta anos após a morte do ex-presidente. O espaço subterrâneo foi criado para preservar e apresentar a trajetória política de Getúlio Vargas, uma das figuras mais marcantes da história brasileira do século XX. Por meio de exposições, fotografias, documentos e atividades culturais, o memorial aborda os períodos em que Vargas esteve à frente do governo e as transformações políticas e sociais de sua época. O local também promove reflexões sobre a história do Brasil e do Rio de Janeiro enquanto capital federal.", importancia: null, endereco: "Praça Luís de Camões — Glória" },
    { id: "monumento-a-santos-dumont", nome: "Monumento a Santos Dumont", bairro: "gavea", lat: null, lng: null, categoria: "Personalidades/Memória", descricao: "O busto de Santos Dumont, localizado na Praça Santos Dumont, na Gávea, homenageia o inventor e pioneiro da aviação brasileira. A obra foi inaugurada em 1942, dez anos após a praça receber oficialmente o nome do aviador. A homenagem recorda a contribuição de Santos Dumont para a história da aviação e sua importância como uma das personalidades brasileiras de maior reconhecimento internacional. A praça também é um tradicional ponto de encontro do bairro, conhecida pela feira de antiguidades e pela proximidade com o Jockey Club Brasileiro.", importancia: null, endereco: "Praça Santos Dumont — Gávea", imagem: {"src": "assets/img/monumento-a-santos-dumont.jpg", "alt": "Monumento a Santos Dumont", "fonte": "partiu__lugaresss.docx"} },
    { id: "monumento-a-zuzu-angel", nome: "Monumento a Zuzu Angel", bairro: "gavea", lat: -22.998256, lng: -43.269012, categoria: "Personalidades/Memória", descricao: "O monumento a Zuzu Angel homenageia a estilista brasileira que ficou conhecida internacionalmente por seu trabalho na moda e por sua luta para descobrir o que aconteceu com seu filho, Stuart Angel Jones, desaparecido durante a ditadura militar. A escultura foi instalada em 1998, nas proximidades de um dos acessos ao atual Túnel Zuzu Angel, perto do local onde a estilista morreu em 1976. Sua memória representa a resistência de familiares que buscaram respostas sobre as vítimas da repressão política e a importância da luta pelo direito à verdade e à memória.", importancia: null, endereco: "Túnel Zuzu Angel — Gávea", imagem: {"src": "assets/img/monumento-a-zuzu-angel.jpg", "alt": "Monumento a Zuzu Angel", "fonte": "partiu__lugaresss.docx"} },
    { id: "monumento-a-carmen-miranda", nome: "Monumento a Carmen Miranda", bairro: "flamengo", lat: -22.941427, lng: -43.172178, categoria: "Personalidades/Memória", descricao: "O Museu Carmen Miranda, localizado no Parque do Flamengo, preserva a memória de uma das artistas brasileiras de maior projeção internacional. Criado em 1956 e inaugurado em 1976, o museu reúne milhares de peças relacionadas à trajetória da cantora e atriz, incluindo figurinos, turbantes, fotografias, discos, filmes e objetos pessoais. Carmen Miranda tornou-se conhecida por sua presença marcante no cinema e na música, levando elementos da cultura brasileira para os palcos e produções de Hollywood. O acervo permite conhecer diferentes momentos de sua carreira e sua contribuição para a divulgação da música brasileira no exterior.", importancia: null, endereco: "Avenida Rui Barbosa — Flamengo", imagem: {"src": "assets/img/monumento-a-carmen-miranda.jpg", "alt": "Monumento a Carmen Miranda", "fonte": "partiu__lugaresss.docx"} },
    { id: "basilica-santuario-de-nossa-senhora-da-penha", nome: "Basílica Santuário de Nossa Senhora da Penha", bairro: "penha", lat: -22.844054, lng: -43.275083, categoria: "Religião", descricao: "Localizada no alto de um rochedo na Zona Norte do Rio, a Basílica Santuário de Nossa Senhora da Penha é um dos mais tradicionais centros de peregrinação religiosa da cidade. Sua origem remonta a 1635, quando foi construída uma pequena capela dedicada a Nossa Senhora da Penha. Ao longo dos séculos, o santuário tornou-se conhecido por sua escadaria de 382 degraus esculpidos na pedra e pela tradicional Festa da Penha, realizada anualmente em outubro.", importancia: null, endereco: "Largo da Penha, 19 — Penha", imagem: {"src": "assets/img/basilica-santuario-de-nossa-senhora-da-penha.jpg", "alt": "Basílica Santuário de Nossa Senhora da Penha", "fonte": "partiu__lugaresss.docx"} },
    { id: "templo-espirita-ogum-mege", nome: "Templo Espírita Ogum Megê", bairro: "vaz-lobo", lat: -22.857228, lng: -43.330535, categoria: "Religião", descricao: "Esse é particularmente interessante para o projeto porque existe uma proposta legislativa municipal específica para reconhecê-lo como patrimônio histórico, cultural e material, destacando seu valor para a cultura religiosa de matriz afro-brasileira.\n\nFundado em 1984, o Templo Espírita Ogum Megê é um importante espaço de prática e preservação da Umbanda em Vaz Lobo. Além de sua atuação religiosa e comunitária, o templo possui reconhecimento legal como patrimônio histórico, cultural e material do município do Rio de Janeiro, por meio da Lei Municipal nº 8.855, de 3 de abril de 2025. Esse reconhecimento destaca a importância da valorização das tradições e dos saberes das religiões de matriz africana.", importancia: null, endereco: "Rua Manuel Machado, 105 — Vaz Lobo", imagem: {"src": "assets/img/templo-espirita-ogum-mege.jpg", "alt": "Templo Espírita Ogum Megê", "fonte": "partiu__lugaresss.docx"} },
    { id: "escola-de-enfermagem-anna-nery-ufrj", nome: "Escola de Enfermagem Anna Nery — UFRJ", bairro: "cidade-nova", lat: -22.909515, lng: -43.201521, categoria: "Educação", descricao: "Criada em 1923, a Escola de Enfermagem Anna Nery foi a primeira escola de enfermagem de nível superior do Brasil e teve papel fundamental na formação profissional e no desenvolvimento da enfermagem brasileira. Incorporada à Universidade Federal do Rio de Janeiro, tornou-se uma referência nacional no ensino, na pesquisa e na extensão na área da saúde. Seu edifício histórico, localizado na Cidade Nova, foi tombado pelo Instituto do Patrimônio Histórico e Artístico Nacional em 1986.", importancia: null, endereco: "Rua Afonso Cavalcanti, 275 — Cidade Nova", imagem: {"src": "assets/img/escola-de-enfermagem-anna-nery-ufrj.jpg", "alt": "Escola de Enfermagem Anna Nery — UFRJ", "fonte": "partiu__lugaresss.docx"} },
    { id: "museu-nacional-ufrj", nome: "Museu Nacional — UFRJ", bairro: "sao-cristovao", lat: -22.905552, lng: -43.226454, categoria: "Educação", descricao: "Fundado em 1818, o Museu Nacional é uma das instituições científicas mais antigas do Brasil. Instalado no antigo Paço de São Cristóvão, na Quinta da Boa Vista, reúne uma trajetória importante para a pesquisa e a divulgação do conhecimento nas áreas de antropologia, arqueologia, paleontologia, zoologia e ciências naturais. Em 2018, um incêndio atingiu o edifício e destruiu grande parte de seu acervo, dando início a um amplo processo de reconstrução e recuperação de sua memória científica.\n\nConstruído no início do século XIX, o Paço de São Cristóvão foi residência da família real portuguesa e, posteriormente, da família imperial brasileira. Em 1892, o edifício passou a abrigar o Museu Nacional, instituição fundada em 1818 por Dom João VI e considerada uma das mais antigas instituições científicas do país. Seu acervo reunia importantes coleções de história natural, arqueologia e antropologia, mas grande parte foi destruída no incêndio de 2018. Atualmente, o edifício passa por um processo de restauração e reconstrução, preservando sua importância histórica, científica e cultural.", importancia: null, endereco: "Quinta da Boa Vista, s/n — São Cristóvão", imagem: {"src": "assets/img/museu-nacional-ufrj.jpg", "alt": "Museu Nacional — UFRJ", "fonte": "partiu__lugaresss.docx"} },
    { id: "instituto-de-educacao-carmela-dutra", nome: "Instituto de Educação Carmela Dutra", bairro: "madureira", lat: -22.865723, lng: -43.334701, categoria: "Educação", descricao: "Criado em 1946, o Instituto de Educação Carmela Dutra surgiu com o objetivo de formar professores para atuar na educação básica, sendo a primeira escola de formação de normalistas localizada nos subúrbios cariocas. Instalado em Madureira, tornou-se uma instituição importante para a história da educação na Zona Norte. Em 2004, passou a ter a denominação atual, mantendo sua tradição na formação de professores.", importancia: null, endereco: "Avenida Ministro Edgar Romero — Madureira", imagem: {"src": "assets/img/instituto-de-educacao-carmela-dutra.jpg", "alt": "Instituto de Educação Carmela Dutra", "fonte": "partiu__lugaresss.docx"} },
    { id: "escola-tecnica-estadual-republica-faetec", nome: "Escola Técnica Estadual República — FAETEC", bairro: "quintino-bocaiuva", lat: -22.893109, lng: -43.3294, categoria: "Educação", descricao: "Localizada em Quintino Bocaiúva, a Escola Técnica Estadual República integra a rede FAETEC e oferece formação técnica em diferentes áreas, como Informática, Eletrônica, Telecomunicações, Mecânica Industrial e Enfermagem. A instituição tem papel importante na oferta de educação profissional pública e gratuita, preparando estudantes para o mundo do trabalho e para a continuidade dos estudos.", importancia: null, endereco: "Rua Clarimundo de Melo, 847 — Quintino Bocaiúva", imagem: {"src": "assets/img/escola-tecnica-estadual-republica-faetec.jpg", "alt": "Escola Técnica Estadual República — FAETEC", "fonte": "partiu__lugaresss.docx"} },
    { id: "universidade-do-estado-do-rio-de-janeiro-uerj", nome: "Universidade do Estado do Rio de Janeiro — UERJ", bairro: "maracana", lat: -22.911075, lng: -43.236164, categoria: "Educação", descricao: "Fundada em 1950, a Universidade do Estado do Rio de Janeiro é uma das principais instituições públicas de ensino superior do país. Seu campus Maracanã, inaugurado em 1976, concentra grande parte de suas atividades acadêmicas e reúne cursos de graduação e pós-graduação, além de atividades de pesquisa e extensão. A universidade também se destaca por sua contribuição para a produção científica e para a democratização do acesso ao ensino superior.", importancia: null, endereco: "Rua São Francisco Xavier, 524 — Maracanã", imagem: {"src": "assets/img/universidade-do-estado-do-rio-de-janeiro-uerj.jpg", "alt": "Universidade do Estado do Rio de Janeiro — UERJ", "fonte": "partiu__lugaresss.docx"} },
    { id: "cefet-rj-campus-maracana", nome: "CEFET/RJ — Campus Maracanã", bairro: "maracana", lat: -22.911417, lng: -43.224782, categoria: "Educação", descricao: "Com uma trajetória iniciada em 1917, o CEFET/RJ tem suas origens na antiga Escola Normal de Artes e Ofícios Wenceslau Brás e se consolidou como uma importante instituição de educação tecnológica. O campus Maracanã reúne essa história centenária e oferece formação em diferentes níveis, incluindo ensino técnico, graduação e pós-graduação. Sua atuação integra ensino, pesquisa e extensão, com destaque para as áreas científica e tecnológica.", importancia: null, endereco: "Avenida Maracanã, 229 — Maracanã", imagem: {"src": "assets/img/cefet-rj-campus-maracana.jpg", "alt": "CEFET/RJ — Campus Maracanã", "fonte": "partiu__lugaresss.docx"} },
    { id: "estadio-olimpico-nilton-santos", nome: "Estádio Olímpico Nilton Santos", bairro: "engenho-de-dentro", lat: -22.893087, lng: -43.292345, categoria: "Esportes", descricao: "Construído para os Jogos Pan-Americanos de 2007, o Estádio Olímpico Nilton Santos foi inaugurado em 30 de junho daquele ano e se tornou a casa do Botafogo de Futebol e Regatas. Conhecido popularmente como Engenhão, o estádio recebeu competições de atletismo e futebol durante os Jogos Olímpicos e Paralímpicos de 2016. Seu nome homenageia Nilton Santos, um dos maiores jogadores da história do Botafogo e do futebol brasileiro.", importancia: null, endereco: "Rua José dos Reis, 425 — Engenho de Dentro", imagem: {"src": "assets/img/estadio-olimpico-nilton-santos.jpg", "alt": "Estádio Olímpico Nilton Santos", "fonte": "partiu__lugaresss.docx"} },
    { id: "estadio-sao-januario", nome: "Estádio São Januário", bairro: "vasco-da-gama", lat: -22.890747, lng: -43.228058, categoria: "Esportes", descricao: "Inaugurado em 21 de abril de 1927, o Estádio Vasco da Gama, conhecido como São Januário, foi construído com recursos arrecadados pelo próprio Club de Regatas Vasco da Gama. Na época, era o maior estádio da América do Sul e representou um marco na luta do clube por um futebol mais democrático, em oposição às práticas de exclusão social e racial presentes no esporte. Além de sua importância esportiva, destaca-se pela arquitetura neocolonial e pelo valor histórico e cultural.", importancia: null, endereco: "Avenida Roberto Dinamite, 10 — Vasco da Gama", imagem: {"src": "assets/img/estadio-sao-januario.jpg", "alt": "Estádio São Januário", "fonte": "partiu__lugaresss.docx"} },
    { id: "estadio-de-moca-bonita", nome: "Estádio de Moça Bonita", bairro: "bangu", lat: -22.872263, lng: -43.456557, categoria: "Esportes", descricao: "Inaugurado em 1947, o Estádio Proletário Guilherme da Silveira Filho, conhecido como Moça Bonita, é a casa do Bangu Atlético Clube. Sua construção foi uma etapa importante da história do clube, que precisou deixar seu antigo campo na Rua Ferrer. Desde então, o estádio se tornou um símbolo da identidade esportiva de Bangu e da tradição do futebol na Zona Oeste do Rio de Janeiro.", importancia: null, endereco: "Rua Sul América, 950 — Bangu", imagem: {"src": "assets/img/estadio-de-moca-bonita.jpg", "alt": "Estádio de Moça Bonita", "fonte": "partiu__lugaresss.docx"} },
    { id: "estadio-da-rua-bariri", nome: "Estádio da Rua Bariri", bairro: "olaria", lat: -22.84118, lng: -43.266675, categoria: "Esportes", descricao: "Inaugurado em 6 de abril de 1947, o Estádio Antônio Mourão Vieira Filho, conhecido como Estádio da Rua Bariri, pertence ao Olaria Atlético Clube. O espaço é um dos símbolos do futebol suburbano carioca e recebeu importantes partidas do clube, que chegou a conquistar o vice-campeonato estadual em 1933 e o terceiro lugar em 1971. O estádio também está ligado à trajetória de jogadores importantes, como Romário e Garrincha, que passaram pelo Olaria.", importancia: null, endereco: "Rua Bariri, 251 — Olaria", imagem: {"src": "assets/img/estadio-da-rua-bariri.jpg", "alt": "Estádio da Rua Bariri", "fonte": "partiu__lugaresss.docx"} },
    { id: "estadio-italo-del-cima", nome: "Estádio Ítalo del Cima", bairro: "campo-grande", lat: -22.901451, lng: -43.545765, categoria: "Esportes", descricao: "Inaugurado em 29 de abril de 1960, o Estádio Ítalo del Cima pertence ao Campo Grande Atlético Clube e é um dos espaços tradicionais do futebol da Zona Oeste. Seu nome homenageia Ítalo Del Cima, comerciante italiano que contribuiu para a construção do estádio ao ceder o terreno. Ao longo de sua história, recebeu partidas importantes do futebol carioca e se tornou parte da memória esportiva de Campo Grande.", importancia: null, endereco: "Rua Campo Grande, 8 — Campo Grande", imagem: {"src": "assets/img/estadio-italo-del-cima.jpg", "alt": "Estádio Ítalo del Cima", "fonte": "partiu__lugaresss.docx"} },
    { id: "estadio-conselheiro-galvao", nome: "Estádio Conselheiro Galvão", bairro: "madureira", lat: -22.869461, lng: -43.337239, categoria: "Esportes", descricao: "Oficialmente chamado Estádio Aniceto Moscoso, o espaço foi inaugurado em 15 de junho de 1941 e pertence ao Madureira Esporte Clube. Seu nome homenageia Aniceto Moscoso, responsável por ceder o terreno para a construção do estádio. Localizado na Rua Conselheiro Galvão, tornou-se um importante símbolo do futebol de Madureira e da tradição dos clubes suburbanos do Rio de Janeiro.", importancia: null, endereco: "Rua Conselheiro Galvão, 130 — Madureira", imagem: {"src": "assets/img/estadio-conselheiro-galvao.jpg", "alt": "Estádio Conselheiro Galvão", "fonte": "partiu__lugaresss.docx"} },
    { id: "estadio-leonidas-da-silva", nome: "Estádio Leônidas da Silva", bairro: "bonsucesso", lat: -22.861608, lng: -43.253096, categoria: "Esportes", descricao: "Localizado em Bonsucesso, o Estádio Leônidas da Silva pertence ao Bonsucesso Futebol Clube e homenageia um dos maiores nomes da história do futebol brasileiro. Conhecido como Diamante Negro, Leônidas da Silva teve uma passagem marcante pelo clube na década de 1930, período em que se destacou como atacante antes de conquistar reconhecimento nacional e internacional. O estádio preserva essa ligação entre a história do Bonsucesso e a trajetória do jogador.", importancia: null, endereco: "Rua Teixeira de Castro, 54 — Bonsucesso", imagem: {"src": "assets/img/estadio-leonidas-da-silva.jpg", "alt": "Estádio Leônidas da Silva", "fonte": "partiu__lugaresss.docx"} },
    { id: "estadio-ronaldo-nazario-figueira-de-melo", nome: "Estádio Ronaldo Nazário / Figueira de Melo", bairro: "sao-cristovao", lat: -22.904861, lng: -43.213519, categoria: "Esportes", descricao: "Inaugurado em 23 de abril de 1916, o estádio do São Cristóvão de Futebol e Regatas é considerado o mais antigo do Rio de Janeiro. Originalmente conhecido como Estádio Figueira de Melo, recebeu o nome de Ronaldo Luís Nazário de Lima em homenagem ao atacante Ronaldo Fenômeno, revelado nas categorias de base do clube. O local guarda uma parte importante da história do futebol carioca e da formação de grandes jogadores.", importancia: null, endereco: "Rua Figueira de Melo, 200 — São Cristóvão", imagem: {"src": "assets/img/estadio-ronaldo-nazario-figueira-de-melo.jpg", "alt": "Estádio Ronaldo Nazário / Figueira de Melo", "fonte": "partiu__lugaresss.docx"} },
    { id: "estadio-do-ceres-futebol-clube", nome: "Estádio do Ceres Futebol Clube", bairro: "bangu", lat: -22.8691, lng: -43.463699, categoria: "Esportes", descricao: "Localizado em Bangu, o estádio pertence ao Ceres Futebol Clube, fundado em 10 de julho de 1933. Oficialmente chamado Estádio João Francisco dos Santos, foi inaugurado em 1949 e faz parte da história do futebol da Zona Oeste. O clube construiu sua trajetória principalmente nas competições do futebol carioca, representando a tradição das equipes suburbanas da cidade.", importancia: null, endereco: "Rua da Chita, 638 — Bangu", imagem: {"src": "assets/img/estadio-do-ceres-futebol-clube.jpg", "alt": "Estádio do Ceres Futebol Clube", "fonte": "partiu__lugaresss.docx"} },
    { id: "parque-madureira-mestre-monarco", nome: "Parque Madureira Mestre Monarco", bairro: "madureira", lat: -22.869943, lng: -43.340328, categoria: "Esportes", descricao: "Inaugurado em 2012, o Parque Madureira Mestre Monarco é um importante espaço público de lazer, convivência e prática esportiva da Zona Norte. Com áreas destinadas a atividades físicas, ciclovias, quadras, pistas de skate e espaços culturais, o parque atende moradores de diferentes bairros da região. Em 2021, recebeu o nome de Mestre Monarco, em homenagem ao cantor e compositor ligado à história da Portela e do samba carioca.", importancia: null, endereco: "Rua Soares Caldeira — Madureira", imagem: {"src": "assets/img/parque-madureira-mestre-monarco.jpg", "alt": "Parque Madureira Mestre Monarco", "fonte": "partiu__lugaresss.docx"} },
    { id: "vila-olimpica-da-mangueira", nome: "Vila Olímpica da Mangueira", bairro: "mangueira", lat: -22.90315, lng: -43.241953, categoria: "Esportes", descricao: "A Vila Olímpica da Mangueira é um espaço público voltado à promoção do esporte, do lazer e da inclusão social. Localizada na comunidade da Mangueira, oferece estrutura para atividades físicas e esportivas, contribuindo para ampliar o acesso da população a essas práticas. O projeto integra a política municipal de incentivo ao esporte e busca fortalecer a convivência comunitária por meio de atividades orientadas.", importancia: null, endereco: "Rua Visconde de Niterói, s/n — Mangueira", imagem: {"src": "assets/img/vila-olimpica-da-mangueira.jpg", "alt": "Vila Olímpica da Mangueira", "fonte": "partiu__lugaresss.docx"} },
    { id: "quinta-da-boa-vista", nome: "Quinta da Boa Vista", bairro: "sao-cristovao", lat: -22.905026, lng: -43.221839, categoria: "História/Patrimônio", descricao: "A Quinta da Boa Vista é um dos parques históricos mais importantes do Rio de Janeiro. A área pertenceu à família real portuguesa e foi residência da família imperial brasileira durante o século XIX. Após a Proclamação da República, o espaço passou por transformações e foi aberto ao público como parque. Com jardins projetados pelo paisagista francês Auguste François Marie Glaziou, a Quinta reúne importantes elementos da história brasileira e se tornou um dos principais espaços de lazer e convivência de São Cristóvão.", importancia: null, endereco: "Avenida Pedro II, s/n — São Cristóvão", imagem: {"src": "assets/img/quinta-da-boa-vista.jpg", "alt": "Quinta da Boa Vista", "fonte": "partiu__lugaresss.docx"} },
    { id: "companhia-progresso-industrial-fabrica-bangu", nome: "Companhia Progresso Industrial — Fábrica Bangu", bairro: "bangu", lat: null, lng: null, categoria: "Indústria/Urbanização", descricao: "Fundada em 1889, a Companhia Progresso Industrial do Brasil, conhecida como Fábrica Bangu, foi uma das principais indústrias têxteis do Rio de Janeiro. Sua instalação impulsionou o crescimento da região, atraindo trabalhadores e contribuindo para a formação do bairro de Bangu. O conjunto de edifícios da antiga fábrica, localizado na Rua Fonseca, é reconhecido como patrimônio histórico municipal e preserva elementos da arquitetura industrial do século XIX.", importancia: null, endereco: "Rua Fonseca, região da antiga fábrica — Bangu", imagem: {"src": "assets/img/companhia-progresso-industrial-fabrica-bangu.jpg", "alt": "Companhia Progresso Industrial — Fábrica Bangu", "fonte": "partiu__lugaresss.docx"} },
    { id: "vila-operaria-de-bangu", nome: "Vila Operária de Bangu", bairro: "bangu", lat: -22.878443, lng: -43.466532, categoria: "Indústria/Urbanização", descricao: "Construída a partir de 1893 pela Companhia Progresso Industrial do Brasil, a Vila Operária de Bangu foi criada para abrigar trabalhadores da fábrica de tecidos. O conjunto de moradias ficava próximo ao local de trabalho e fazia parte de um projeto mais amplo de organização da vida dos funcionários, que também envolvia espaços de convivência e serviços. Sua construção foi fundamental para a ocupação e a urbanização de Bangu, que passou de uma região predominantemente rural a um importante núcleo industrial da Zona Oeste.", importancia: null, endereco: "Região da antiga Fábrica Bangu — Bangu", imagem: {"src": "assets/img/vila-operaria-de-bangu.jpg", "alt": "Vila Operária de Bangu", "fonte": "partiu__lugaresss.docx"} },
    { id: "vila-operaria-da-companhia-confianca", nome: "Vila Operária da Companhia Confiança", bairro: "vila-isabel", lat: -22.922946, lng: -43.248735, categoria: "Indústria/Urbanização", descricao: "A antiga Companhia de Fiação e Tecidos Confiança Industrial, inaugurada em 1885 na Rua Maxwell, contribuiu para o desenvolvimento industrial de Vila Isabel. Em seu entorno foram construídas diversas vilas operárias destinadas aos funcionários da fábrica, formando conjuntos residenciais que ajudaram a transformar a paisagem do bairro. Parte desse patrimônio arquitetônico ainda pode ser identificada nas ruas próximas à antiga fábrica, cuja história está ligada ao crescimento da indústria têxtil e à urbanização da região.", importancia: null, endereco: "Região da Rua Maxwell — Vila Isabel", imagem: {"src": "assets/img/vila-operaria-da-companhia-confianca.jpg", "alt": "Vila Operária da Companhia Confiança", "fonte": "partiu__lugaresss.docx"} },
    { id: "antiga-fabrica-de-gas-gasometro-de-sao-cristovao", nome: "Antiga Fábrica de Gás — Gasômetro de São Cristóvão", bairro: "sao-cristovao", lat: -22.907382, lng: -43.200109, categoria: "Indústria/Urbanização", descricao: "Inaugurado em 1911, o Gasômetro de São Cristóvão fazia parte do complexo industrial responsável pela produção e pelo armazenamento de gás utilizado na iluminação pública e no abastecimento da cidade. Instalado próximo ao Canal do Mangue, na região da atual Avenida Francisco Bicalho, foi durante décadas uma estrutura marcante da paisagem carioca. Com a modernização do sistema de abastecimento e a substituição do gás manufaturado pelo gás natural, o complexo foi desativado em 2005 e desmontado no ano seguinte.", importancia: null, endereco: "Região da Avenida Francisco Bicalho — São Cristóvão", imagem: {"src": "assets/img/antiga-fabrica-de-gas-gasometro-de-sao-cristovao.jpg", "alt": "Antiga Fábrica de Gás — Gasômetro de São Cristóvão", "fonte": "partiu__lugaresss.docx"} },
    { id: "refinaria-de-manguinhos", nome: "Refinaria de Manguinhos", bairro: "manguinhos", lat: -22.885535, lng: -43.235196, categoria: "Indústria/Urbanização", descricao: "Inaugurada em 1954, a Refinaria de Manguinhos foi uma das primeiras refinarias privadas de petróleo do Brasil. Sua implantação representou um marco para a industrialização da Zona Norte e para o setor energético nacional. Ao longo de sua trajetória, passou por diferentes administrações e transformações, mantendo uma presença importante na paisagem industrial de Manguinhos.", importancia: null, endereco: "Avenida Brasil, 3.141 — Manguinhos", imagem: {"src": "assets/img/refinaria-de-manguinhos.jpg", "alt": "Refinaria de Manguinhos", "fonte": "partiu__lugaresss.docx"} },
    { id: "estacao-da-leopoldina", nome: "Estação da Leopoldina", bairro: "sao-cristovao", lat: -22.90743, lng: -43.21046, categoria: "Indústria/Urbanização", descricao: null, importancia: null, endereco: "Avenida Francisco Bicalho — São Cristóvão", imagem: {"src": "assets/img/estacao-da-leopoldina.jpg", "alt": "Estação da Leopoldina", "fonte": "partiu__lugaresss.docx"} },
    { id: "estacao-de-bonsucesso", nome: "Estação de Bonsucesso", bairro: "bonsucesso", lat: -22.867321, lng: -43.25523, categoria: "Indústria/Urbanização", descricao: "A Estação de Bonsucesso integra o ramal ferroviário de Saracuruna e teve papel importante no desenvolvimento e na mobilidade da Zona Norte do Rio de Janeiro. Localizada na Praça das Nações, tornou-se um ponto de conexão para moradores e trabalhadores da região, contribuindo para a expansão urbana e para a integração de Bonsucesso com outras áreas da cidade.", importancia: null, endereco: "Bonsucesso", imagem: {"src": "assets/img/estacao-de-bonsucesso.jpg", "alt": "Estação de Bonsucesso", "fonte": "partiu__lugaresss.docx"} },
    { id: "estacao-de-olaria", nome: "Estação de Olaria", bairro: "olaria", lat: -22.84739, lng: -43.265793, categoria: "Indústria/Urbanização", descricao: "Inaugurada em 23 de outubro de 1886, a Estação de Olaria integra o ramal ferroviário de Saracuruna. Sua chegada contribuiu diretamente para a urbanização do bairro, facilitando o transporte de pessoas e de materiais produzidos na região, especialmente tijolos e outros artigos de cerâmica. A estação também já foi chamada de Pedro Ernesto, em homenagem ao médico e político que governou o antigo Distrito Federal.", importancia: null, endereco: "Olaria", imagem: {"src": "assets/img/estacao-de-olaria.jpg", "alt": "Estação de Olaria", "fonte": "partiu__lugaresss.docx"} },
    { id: "estacao-da-penha", nome: "Estação da Penha", bairro: "penha", lat: -22.840036, lng: -43.278634, categoria: "Indústria/Urbanização", descricao: "A Estação da Penha integra o ramal ferroviário de Saracuruna e contribuiu para a expansão dos transportes e da ocupação urbana da Zona Norte. Sua presença facilitou o deslocamento dos moradores e a conexão do bairro com outras regiões do Rio de Janeiro, especialmente o Centro e os municípios atendidos pelo ramal.", importancia: null, endereco: "Penha", imagem: {"src": "assets/img/estacao-da-penha.jpg", "alt": "Estação da Penha", "fonte": "partiu__lugaresss.docx"} },
    { id: "vila-operaria-salvador-de-sa", nome: "Vila Operária Salvador de Sá", bairro: "cidade-nova", lat: -22.912172, lng: -43.199405, categoria: "Indústria/Urbanização", descricao: "Construída durante a gestão do prefeito Pereira Passos e inaugurada em 1908, a Vila Operária Salvador de Sá foi o primeiro conjunto habitacional criado pelo poder público municipal no Rio de Janeiro. Formada originalmente por 120 moradias distribuídas em quadras ao longo da avenida, a vila surgiu como parte das iniciativas de reorganização urbana do início do século XX. Seu conjunto arquitetônico é reconhecido como patrimônio histórico da cidade.", importancia: null, endereco: "Avenida Salvador de Sá — Cidade Nova", imagem: {"src": "assets/img/vila-operaria-salvador-de-sa.jpg", "alt": "Vila Operária Salvador de Sá", "fonte": "partiu__lugaresss.docx"} },
    { id: "monumento-a-pixinguinha", nome: "Monumento a Pixinguinha", bairro: "ramos", lat: null, lng: null, categoria: "Personalidades/Memória", descricao: "Inaugurado em 2016, o monumento homenageia Pixinguinha, um dos maiores nomes da música popular brasileira. A escultura de bronze retrata o compositor sentado em uma cadeira, usando pijama e chinelos, como costumava ficar enquanto frequentava o tradicional Bar da Portuguesa, em Ramos. A obra foi criada pelo artista Ique e instalada na esquina das ruas João Silva e Custódio Nunes.", importancia: null, endereco: "Esquina das ruas João Silva e Custódio Nunes — Ramos", imagem: {"src": "assets/img/monumento-a-pixinguinha.jpg", "alt": "Monumento a Pixinguinha", "fonte": "partiu__lugaresss.docx"} },
    { id: "monumento-a-bellini-os-campeoes-do-mundo", nome: "Monumento a Bellini — “Os Campeões do Mundo”", bairro: "maracana", lat: -22.913221, lng: -43.227859, categoria: "Personalidades/Memória", descricao: "Conhecido popularmente como Estátua de Bellini, o monumento homenageia a seleção brasileira que conquistou sua primeira Copa do Mundo, em 1958. A escultura representa o capitão Hilderaldo Bellini erguendo a taça Jules Rimet, gesto que se tornou uma das imagens mais marcantes da história do futebol brasileiro. Inaugurada em 1960, a obra fica nas proximidades do Estádio do Maracanã e é um tradicional ponto de encontro dos torcedores.", importancia: null, endereco: "Praça Querubim — Maracanã", imagem: {"src": "assets/img/monumento-a-bellini-os-campeoes-do-mundo.jpg", "alt": "Monumento a Bellini — “Os Campeões do Mundo”", "fonte": "partiu__lugaresss.docx"} },
    { id: "museu-do-samba", nome: "Museu do Samba", bairro: "mangueira", lat: -22.901469, lng: -43.240876, categoria: "Personalidades/Memória", descricao: "Localizado na Mangueira, o Museu do Samba é dedicado à preservação e à valorização da história do samba e das escolas de samba do Rio de Janeiro. Seu acervo reúne documentos, fotografias, objetos e registros relacionados a grandes compositores, intérpretes e personalidades do gênero. O espaço também desenvolve atividades culturais e educativas, contribuindo para manter viva essa importante expressão da cultura brasileira.", importancia: null, endereco: "Rua Visconde de Niterói, 1296 — Mangueira", imagem: {"src": "assets/img/museu-do-samba.jpg", "alt": "Museu do Samba", "fonte": "partiu__lugaresss.docx"} },
    { id: "monumento-a-cartola", nome: "Monumento a Cartola", bairro: "mangueira", lat: -22.901378, lng: -43.240904, categoria: "Personalidades/Memória", descricao: "Inaugurado em 2006, o monumento homenageia Angenor de Oliveira, o Cartola, um dos maiores compositores da história do samba e figura fundamental da Estação Primeira de Mangueira. A escultura fica em frente ao centro cultural que leva seu nome, na comunidade da Mangueira, e representa o reconhecimento de sua contribuição para a música e para a cultura carioca.", importancia: null, endereco: "Mangueira", imagem: {"src": "assets/img/monumento-a-cartola.jpg", "alt": "Monumento a Cartola", "fonte": "partiu__lugaresss.docx"} },
    { id: "casa-de-cartola-e-dona-zica-memoria-do-casal", nome: "Casa de Cartola e Dona Zica — memória do casal", bairro: "mangueira", lat: -22.901439, lng: -43.240823, categoria: "Personalidades/Memória", descricao: "Cartola e Dona Zica formaram um dos casais mais conhecidos da história do samba carioca. Além da trajetória musical de Cartola, Dona Zica teve papel importante na cultura da Mangueira e na gastronomia popular. Juntos, comandaram o Zicartola, restaurante musical que funcionou no Centro do Rio entre 1963 e 1965 e se tornou um importante ponto de encontro de sambistas, artistas e intelectuais.", importancia: null, endereco: "Mangueira", imagem: {"src": "assets/img/casa-de-cartola-e-dona-zica-memoria-do-casal.jpg", "alt": "Casa de Cartola e Dona Zica — memória do casal", "fonte": "partiu__lugaresss.docx"} },
    { id: "bar-da-portuguesa-memoria-de-pixinguinha", nome: "Bar da Portuguesa — memória de Pixinguinha", bairro: "ramos", lat: -22.848478, lng: -43.261299, categoria: "Personalidades/Memória", descricao: "Tradicional botequim de Ramos, o Bar da Portuguesa tem uma ligação especial com a memória de Pixinguinha, que morava nas proximidades e costumava frequentar o estabelecimento. O local também foi cenário de um encontro entre o compositor e o violonista Baden Powell, registrado no documentário Saravah. Reconhecido como Patrimônio Cultural Carioca, o bar representa um importante espaço de convivência e memória da Zona Norte.", importancia: null, endereco: "Rua João Silva — Ramos", imagem: {"src": "assets/img/bar-da-portuguesa-memoria-de-pixinguinha.jpg", "alt": "Bar da Portuguesa — memória de Pixinguinha", "fonte": "partiu__lugaresss.docx"} },
    { id: "busto-de-tia-ciata", nome: "Busto de Tia Ciata", bairro: "cidade-nova", lat: null, lng: null, categoria: "Personalidades/Memória", descricao: "A Casa da Tia Ciata é um espaço cultural dedicado à memória de Hilária Batista de Almeida, conhecida como Tia Ciata, uma das figuras mais importantes para o desenvolvimento do samba carioca. A matriarca do samba promovia encontros musicais em sua residência, reunindo compositores e instrumentistas que contribuíram para a formação do gênero. Atualmente, o espaço preserva sua história e valoriza a cultura afro-brasileira.", importancia: null, endereco: "Praça Onze — Cidade Nova", imagem: {"src": "assets/img/busto-de-tia-ciata.jpg", "alt": "Busto de Tia Ciata", "fonte": "partiu__lugaresss.docx"} },
    { id: "ufrj-cidade-universitaria", nome: "UFRJ — Cidade Universitária", bairro: "cidade-universitaria", lat: -22.864452, lng: -43.214904, categoria: "Educação", descricao: "A Cidade Universitária da Universidade Federal do Rio de Janeiro (UFRJ), localizada na Ilha do Fundão, é o principal campus da instituição e reúne centros de ensino, pesquisa, hospitais, bibliotecas e instalações esportivas. A área foi escolhida para receber a Cidade Universitária em 1948, e sua construção começou na década seguinte, integrando diferentes ilhas por meio de aterros e obras de infraestrutura. Atualmente, o campus é um importante polo científico e acadêmico do país, com atividades em diversas áreas do conhecimento", importancia: null, endereco: "Avenida Pedro Calmon, 550 — Cidade Universitária", imagem: {"src": "assets/img/ufrj-cidade-universitaria.jpg", "alt": "UFRJ — Cidade Universitária", "fonte": "partiu__lugaresss.docx"} },
    { id: "estadio-luso-brasileiro", nome: "Estádio Luso-Brasileiro", bairro: "portuguesa", lat: -22.801438, lng: -43.207783, categoria: "Esportes", descricao: "O Estádio Luso-Brasileiro pertence à Associação Atlética Portuguesa e está localizado na Ilha do Governador. Inaugurado em 1965, foi construído no terreno onde funcionava o antigo Jockey Club Guanabara. Ao longo de sua história, recebeu partidas de futebol e passou por diferentes reformas e parcerias, chegando a ser utilizado por clubes como Botafogo e Flamengo. Também ficou conhecido como Arena Petrobras, Arena Botafogo e Ilha do Urubu, acompanhando as diferentes fases de sua utilização.", importancia: null, endereco: "Rua Haroldo Lôbo, 400 — Portuguesa", imagem: {"src": "assets/img/estadio-luso-brasileiro.jpg", "alt": "Estádio Luso-Brasileiro", "fonte": "partiu__lugaresss.docx"} },
    { id: "arena-carioca-1", nome: "Arena Carioca 1", bairro: "barra-da-tijuca", lat: -22.978594, lng: -43.392304, categoria: "Esportes", descricao: "A Arena Carioca 1 foi construída para os Jogos Olímpicos e Paralímpicos Rio 2016 e recebeu competições de basquete durante o evento. Localizada no Parque Olímpico da Barra, possui estrutura multiuso, com quadra e arquibancadas que podem ser adaptadas para diferentes atividades. Após os Jogos, passou a integrar o conjunto de instalações do legado olímpico, destinado à realização de eventos e ao incentivo à prática esportiva. A gestão da arena está sob responsabilidade da União.", importancia: null, endereco: "Parque Olímpico — Barra da Tijuca", imagem: {"src": "assets/img/arena-carioca-1.jpg", "alt": "Arena Carioca 1", "fonte": "partiu__lugaresss.docx"} },
    { id: "arena-carioca-2", nome: "Arena Carioca 2", bairro: "barra-da-tijuca", lat: -22.977394, lng: -43.392346, categoria: "Esportes", descricao: "A Arena Carioca 2 integrou o Parque Olímpico da Barra e recebeu competições de judô e luta olímpica durante os Jogos Rio 2016, além de provas de bocha nos Jogos Paralímpicos. Após o evento, foi utilizada para atividades esportivas e projetos voltados à população. Atualmente, sua estrutura está destinada à implantação de um campus do Instituto Federal do Rio de Janeiro (IFRJ), transformando parte do legado olímpico em espaço de educação e formação profissional.", importancia: null, endereco: "Parque Olímpico — Barra da Tijuca", imagem: {"src": "assets/img/arena-carioca-2.jpg", "alt": "Arena Carioca 2", "fonte": "partiu__lugaresss.docx"} },
    { id: "arena-carioca-3-ginasio-educacional-olimpico", nome: "Arena Carioca 3 / Ginásio Educacional Olímpico", bairro: "barra-da-tijuca", lat: -22.97632, lng: -43.3924, categoria: "Esportes", descricao: "A Arena Carioca 3 foi uma das instalações construídas para os Jogos Olímpicos Rio 2016, recebendo competições de taekwondo e esgrima, além de provas de judô nos Jogos Paralímpicos. Em 2024, foi transformada no Ginásio Educacional Olímpico Isabel Salgado, uma escola pública municipal de tempo integral que integra educação e prática esportiva. A mudança representa um exemplo de reaproveitamento de uma estrutura olímpica para atender às necessidades da população.", importancia: null, endereco: "Parque Olímpico — Barra da Tijuca", imagem: {"src": "assets/img/arena-carioca-3-ginasio-educacional-olimpico.jpg", "alt": "Arena Carioca 3 / Ginásio Educacional Olímpico", "fonte": "partiu__lugaresss.docx"} },
    { id: "centro-aquatico-maria-lenk", nome: "Centro Aquático Maria Lenk", bairro: "barra-da-tijuca", lat: -22.974061, lng: -43.38811, categoria: "Esportes", descricao: "O Parque Aquático Maria Lenk foi construído para os Jogos Pan-Americanos de 2007 e recebeu competições de saltos ornamentais e polo aquático durante os Jogos Olímpicos Rio 2016. Seu nome homenageia Maria Lenk, nadadora brasileira pioneira e primeira mulher sul-americana a participar de uma edição dos Jogos Olímpicos, em 1932. O complexo possui piscinas destinadas a diferentes modalidades aquáticas e continua sendo uma referência para treinamentos e competições esportivas.", importancia: null, endereco: "Avenida Embaixador Abelardo Bueno, 3.401 — Barra da Tijuca", imagem: {"src": "assets/img/centro-aquatico-maria-lenk.jpg", "alt": "Centro Aquático Maria Lenk", "fonte": "partiu__lugaresss.docx"} },
    { id: "velodromo-olimpico-do-rio", nome: "Velódromo Olímpico do Rio", bairro: "barra-da-tijuca", lat: -22.975008, lng: -43.39239, categoria: "Esportes", descricao: "O Velódromo Olímpico do Rio foi construído para os Jogos Olímpicos de 2016 e recebeu as competições de ciclismo de pista. Sua estrutura possui uma pista de madeira com 250 metros de extensão, projetada para permitir provas de alta velocidade e precisão. Após os Jogos, passou a integrar a Rede Nacional de Treinamento e a receber atividades e competições da modalidade. O espaço também abriga o Museu Rio Olímpico, dedicado à memória dos Jogos e ao legado esportivo deixado na cidade.", importancia: null, endereco: "Parque Olímpico — Barra da Tijuca", imagem: {"src": "assets/img/velodromo-olimpico-do-rio.jpg", "alt": "Velódromo Olímpico do Rio", "fonte": "partiu__lugaresss.docx"} },
    { id: "centro-olimpico-de-tenis", nome: "Centro Olímpico de Tênis", bairro: "barra-da-tijuca", lat: -22.9748, lng: -43.394523, categoria: "Esportes", descricao: "O Centro Olímpico de Tênis foi construído para receber as competições de tênis dos Jogos Olímpicos e Paralímpicos Rio 2016. Localizado no Parque Olímpico da Barra, o complexo reúne quadras de diferentes dimensões e uma quadra central com arquibancadas para grandes eventos. Após os Jogos, passou a integrar o legado esportivo da cidade, com potencial para receber competições, treinamentos e atividades relacionadas ao tênis.", importancia: null, endereco: "Parque Olímpico — Barra da Tijuca", imagem: {"src": "assets/img/centro-olimpico-de-tenis.jpg", "alt": "Centro Olímpico de Tênis", "fonte": "partiu__lugaresss.docx"} },
    { id: "arena-olimpica-do-rio", nome: "Arena Olímpica do Rio", bairro: "barra-da-tijuca", lat: -22.974231, lng: -43.393489, categoria: "Esportes", descricao: "A Arena Olímpica do Rio, também conhecida como Rio Olympic Arena e atualmente chamada de Farmasi Arena, foi inaugurada em 2007 para os Jogos Pan-Americanos. Durante os Jogos Olímpicos de 2016, recebeu competições de ginástica artística e de trampolim. Com capacidade para grandes públicos e estrutura adaptável, tornou-se um dos principais espaços multiuso da cidade, recebendo shows, eventos culturais, competições esportivas e apresentações de diferentes modalidades.", importancia: null, endereco: "Avenida Embaixador Abelardo Bueno, 3.401 — Barra da Tijuca", imagem: {"src": "assets/img/arena-olimpica-do-rio.jpg", "alt": "Arena Olímpica do Rio", "fonte": "partiu__lugaresss.docx"} },
    { id: "arena-da-juventude", nome: "Arena da Juventude", bairro: "deodoro", lat: -22.859038, lng: -43.403828, categoria: "Esportes", descricao: "A Arena da Juventude foi construída no Complexo Esportivo de Deodoro para os Jogos Olímpicos Rio 2016, recebendo competições de basquete e esgrima do pentatlo moderno. Sua estrutura foi planejada para continuar sendo utilizada após o evento, contribuindo para ampliar o acesso ao esporte na Zona Oeste. O espaço integra o legado esportivo de Deodoro e é conhecido também como Arena Poliesportiva Wenceslau Malta.", importancia: null, endereco: "Estrada São Pedro de Alcântara, 2.020 — Deodoro", imagem: {"src": "assets/img/arena-da-juventude.jpg", "alt": "Arena da Juventude", "fonte": "partiu__lugaresss.docx"} },
    { id: "parque-radical-de-deodoro", nome: "Parque Radical de Deodoro", bairro: "deodoro", lat: -22.848368, lng: -43.402711, categoria: "Esportes", descricao: "O Parque Radical de Deodoro foi construído para os Jogos Olímpicos Rio 2016 e se tornou um importante espaço de esporte e lazer para a população da Zona Oeste. Com aproximadamente 500 mil metros quadrados, recebeu competições de mountain bike, BMX e canoagem slalom. Após os Jogos, foi adaptado para oferecer atividades esportivas e recreativas, incluindo áreas de treinamento, piscina e espaços de convivência. O parque representa uma das principais estruturas do legado olímpico na região.", importancia: null, endereco: "Estrada Marechal Alencastro — Deodoro", imagem: {"src": "assets/img/parque-radical-de-deodoro.jpg", "alt": "Parque Radical de Deodoro", "fonte": "partiu__lugaresss.docx"} },
    { id: "centro-olimpico-de-bmx", nome: "Centro Olímpico de BMX", bairro: "deodoro", lat: -22.846312, lng: -43.401321, categoria: "Esportes", descricao: "O Centro Olímpico de BMX integra o Parque Radical de Deodoro e recebeu as competições de ciclismo BMX dos Jogos Olímpicos Rio 2016. A pista foi projetada para provas de alta velocidade, com curvas inclinadas, obstáculos e saltos que exigem habilidade e precisão dos atletas. Após os Jogos, o espaço passou a fazer parte do legado esportivo da região, com iniciativas voltadas ao treinamento e à popularização da modalidade. A Prefeitura anunciou sua reinauguração em 2024, acompanhada da oferta de atividades para novos praticantes.", importancia: null, endereco: "Complexo Esportivo de Deodoro — Deodoro", imagem: {"src": "assets/img/centro-olimpico-de-bmx.jpg", "alt": "Centro Olímpico de BMX", "fonte": "partiu__lugaresss.docx"} },
    { id: "estadio-de-canoagem-slalom", nome: "Estádio de Canoagem Slalom", bairro: "deodoro", lat: -22.848171, lng: -43.402673, categoria: "Esportes", descricao: "O Estádio de Canoagem Slalom, localizado no Complexo Esportivo de Deodoro, foi construído para receber as competições de canoagem slalom dos Jogos Olímpicos Rio 2016. O percurso artificial possui obstáculos e correntezas que simulam as condições encontradas em rios, exigindo dos atletas controle, velocidade e precisão para completar o trajeto. Depois dos Jogos, o canal passou a ser utilizado também para treinamentos, contribuindo para a preparação de atletas brasileiros da modalidade.", importancia: null, endereco: "Complexo Esportivo de Deodoro — Deodoro", imagem: {"src": "assets/img/estadio-de-canoagem-slalom.jpg", "alt": "Estádio de Canoagem Slalom", "fonte": "partiu__lugaresss.docx"} },
    { id: "centro-olimpico-de-hipismo", nome: "Centro Olímpico de Hipismo", bairro: "deodoro", lat: -22.867922, lng: -43.405505, categoria: "Esportes", descricao: "O Centro Olímpico de Hipismo, localizado em Deodoro, recebeu as competições de adestramento, saltos e concurso completo de equitação durante os Jogos Olímpicos Rio 2016. A estrutura já existia antes do evento e passou por adaptações para atender às exigências das competições internacionais. O espaço integra o conjunto de instalações esportivas do Complexo de Deodoro e está ligado à tradição do hipismo na região, que também recebeu provas de eventos esportivos anteriores.", importancia: null, endereco: "Complexo Esportivo de Deodoro — Deodoro", imagem: {"src": "assets/img/centro-olimpico-de-hipismo.jpg", "alt": "Centro Olímpico de Hipismo", "fonte": "partiu__lugaresss.docx"} },
    { id: "centro-olimpico-de-hoquei", nome: "Centro Olímpico de Hóquei", bairro: "deodoro", lat: -22.862141, lng: -43.402277, categoria: "Esportes", descricao: "O Centro Olímpico de Hóquei foi utilizado nas competições de hóquei sobre a grama dos Jogos Olímpicos Rio 2016. Localizado no Complexo Esportivo de Deodoro, o espaço foi construído originalmente para os Jogos Pan-Americanos de 2007 e passou por adaptações para receber as disputas olímpicas. O conjunto possui campos específicos para a modalidade e representa uma importante estrutura para o desenvolvimento do hóquei sobre a grama no Brasil.", importancia: null, endereco: "Complexo Esportivo de Deodoro — Deodoro", imagem: {"src": "assets/img/centro-olimpico-de-hoquei.jpg", "alt": "Centro Olímpico de Hóquei", "fonte": "partiu__lugaresss.docx"} },
    { id: "centro-esportivo-miecimo-da-silva", nome: "Centro Esportivo Miécimo da Silva", bairro: "campo-grande", lat: -22.914945, lng: -43.553987, categoria: "Esportes", descricao: "O Centro Esportivo Miécimo da Silva é um dos principais complexos públicos de esporte e lazer da Zona Oeste do Rio de Janeiro. Localizado em Campo Grande, foi inaugurado em 1982 e oferece instalações para diversas modalidades, como natação, atletismo, judô, basquete, tênis e ginástica. O espaço atende crianças, jovens, adultos e idosos por meio de atividades esportivas e projetos gratuitos, além de receber eventos e competições. Sua atuação contribui para ampliar o acesso ao esporte e à convivência comunitária.", importancia: null, endereco: "Rua Olinda Ellis, 470 — Campo Grande", imagem: {"src": "assets/img/centro-esportivo-miecimo-da-silva.jpg", "alt": "Centro Esportivo Miécimo da Silva", "fonte": "partiu__lugaresss.docx"} },
    { id: "vila-olimpica-oscar-schmidt", nome: "Vila Olímpica Oscar Schmidt", bairro: "santa-cruz", lat: -22.922926, lng: -43.693873, categoria: "Esportes", descricao: "A Vila Olímpica Oscar Schmidt, localizada em Santa Cruz, é um equipamento público voltado à democratização do esporte e à oferta de atividades gratuitas para a população. Seu nome homenageia Oscar Schmidt, um dos maiores nomes da história do basquete brasileiro. O espaço oferece diferentes instalações esportivas, incluindo piscina, pista de atletismo, quadras e campo de futebol. Ao longo de sua trajetória, também contribuiu para revelar atletas, como a velocista Lorraine Martins, que iniciou sua formação esportiva no local.", importancia: null, endereco: "Rua das Palmeiras Imperiais, 83 — Santa Cruz", imagem: {"src": "assets/img/vila-olimpica-oscar-schmidt.jpg", "alt": "Vila Olímpica Oscar Schmidt", "fonte": "partiu__lugaresss.docx"} },
    { id: "cais-da-imperatriz", nome: "Cais da Imperatriz", bairro: "saude", lat: -22.897465, lng: -43.18676, categoria: "História/Patrimônio", descricao: "O Cais da Imperatriz foi construído em 1843 sobre a área do antigo Cais do Valongo, na região portuária do Rio de Janeiro, para receber Teresa Cristina de Bourbon-Duas Sicílias, futura esposa de Dom Pedro II. A construção modificou o espaço que, décadas antes, havia sido um dos principais pontos de desembarque de africanos escravizados nas Américas. Com as reformas urbanas do início do século XX, a área foi aterrada e acabou encoberta. Seus vestígios foram identificados durante escavações arqueológicas e hoje integram o sítio histórico do Cais do Valongo, reconhecido como Patrimônio Mundial pela UNESCO.", importancia: null, endereco: "Região do Cais do Valongo — Saúde", imagem: {"src": "assets/img/cais-da-imperatriz.jpg", "alt": "Cais da Imperatriz", "fonte": "partiu__lugaresss.docx"} },
    { id: "casa-dos-piloes-jardim-botanico", nome: "Casa dos Pilões — Jardim Botânico", bairro: "jardim-botanico", lat: -22.968205, lng: -43.22686, categoria: "História/Patrimônio", descricao: "A Casa dos Pilões é um dos vestígios da antiga Real Fábrica de Pólvora, instalada na região do atual Jardim Botânico em 1808, durante o período de chegada da Corte portuguesa ao Brasil. O edifício era utilizado no processo de fabricação da pólvora, especialmente na etapa de moagem e compactação dos materiais. A fábrica foi transferida para outra região em 1826, mas a construção permaneceu como registro da atividade industrial desenvolvida no local no início do século XIX. Atualmente, integra o patrimônio histórico do Jardim Botânico do Rio de Janeiro.", importancia: null, endereco: "Jardim Botânico — Rua Jardim Botânico", imagem: {"src": "assets/img/casa-dos-piloes-jardim-botanico.jpg", "alt": "Casa dos Pilões — Jardim Botânico", "fonte": "partiu__lugaresss.docx"} },
    { id: "fabrica-bhering", nome: "Fábrica Bhering", bairro: "santo-cristo", lat: -22.900728, lng: -43.203328, categoria: "Indústria/Urbanização", descricao: "A Fábrica Bhering é um importante exemplo da transformação dos antigos espaços industriais da Zona Portuária do Rio de Janeiro. Instalada em Santo Cristo na década de 1930, a fábrica produziu chocolates, doces e café, mantendo suas atividades industriais até a década de 1990. O edifício possui uma estrutura de grandes dimensões, com elementos metálicos e características da arquitetura fabril do período. Após o encerramento da produção, passou a receber ateliês, estúdios, lojas e iniciativas culturais, tornando-se um espaço de encontro entre patrimônio industrial e produção artística contemporânea.", importancia: null, endereco: "Rua Orestes, 28 — Santo Cristo", imagem: {"src": "assets/img/fabrica-bhering.jpg", "alt": "Fábrica Bhering", "fonte": "partiu__lugaresss.docx"} },
    { id: "galpoes-da-gamboa", nome: "Galpões da Gamboa", bairro: "gamboa", lat: -22.896727, lng: -43.199517, categoria: "Indústria/Urbanização", descricao: "Os Galpões da Gamboa são duas estruturas industriais construídas em 1880, na região portuária do Rio de Janeiro. Inicialmente utilizados como depósitos de sacas de café, tiveram papel importante no armazenamento e no transporte de mercadorias durante o período de expansão das atividades portuárias e ferroviárias. Posteriormente, também foram utilizados como depósitos de vagões e locomotivas. Construídos com tijolos maciços e elementos de ferro, representam a arquitetura industrial do século XIX e foram restaurados no contexto do projeto Porto Maravilha, contribuindo para a preservação da memória da região.", importancia: null, endereco: "Gamboa — Zona Portuária", imagem: {"src": "assets/img/galpoes-da-gamboa.jpg", "alt": "Galpões da Gamboa", "fonte": "partiu__lugaresss.docx"} },
    { id: "vila-operaria-da-gamboa", nome: "Vila Operária da Gamboa", bairro: "gamboa", lat: -22.900327, lng: -43.198969, categoria: "Indústria/Urbanização", descricao: "A Vila Operária da Gamboa é um conjunto habitacional projetado na década de 1930 para oferecer moradia popular a trabalhadores da região portuária. O projeto arquitetônico foi desenvolvido por Lúcio Costa e Gregori Warchavchik, dois nomes importantes da arquitetura moderna brasileira. O conjunto reúne 14 unidades habitacionais organizadas em um terreno pequeno e irregular, com soluções que aproveitam o espaço e favorecem a circulação entre os apartamentos. Tombada na década de 1980, a vila é um exemplo significativo da arquitetura moderna aplicada à habitação popular no Rio de Janeiro.", importancia: null, endereco: "Rua Barão da Gamboa, 150–160 — Gamboa", imagem: {"src": "assets/img/vila-operaria-da-gamboa.jpg", "alt": "Vila Operária da Gamboa", "fonte": "partiu__lugaresss.docx"} },
    { id: "armazem-5-do-porto-do-rio-de-janeiro", nome: "Armazém 5 do Porto do Rio de Janeiro", bairro: "centro", lat: -22.89289, lng: -43.188805, categoria: "Indústria/Urbanização", descricao: "O Armazém 5 integra o conjunto de estruturas portuárias construídas para apoiar as atividades de armazenamento e movimentação de mercadorias na região do Porto do Rio de Janeiro. Esses armazéns tiveram papel importante no funcionamento do porto, que durante décadas foi um dos principais pontos de entrada e saída de produtos do país. A presença dessas construções ajuda a compreender a relação entre o desenvolvimento econômico, a atividade portuária e a expansão urbana da região central da cidade.", importancia: null, endereco: "Zona Portuária — Centro", imagem: {"src": "assets/img/armazem-5-do-porto-do-rio-de-janeiro.jpg", "alt": "Armazém 5 do Porto do Rio de Janeiro", "fonte": "partiu__lugaresss.docx"} },
    { id: "parque-natural-municipal-do-jardim-do-carmo", nome: "Parque Natural Municipal do Jardim do Carmo", bairro: "jardim-do-carmo", lat: -22.808839, lng: -43.302835, categoria: "Natureza/Paisagens", descricao: "O Parque Natural Municipal do Jardim do Carmo é uma área protegida da Zona Norte do Rio de Janeiro, criada com o objetivo de conservar os ecossistemas naturais da região e ampliar os espaços verdes da cidade. Sua proposta envolve a recuperação ambiental, a proteção da fauna e da flora e a possibilidade de atividades de lazer e educação ambiental. A unidade integra o conjunto de áreas de conservação reconhecidas pela Prefeitura do Rio, contribuindo para a proteção da biodiversidade em uma região bastante urbanizada.", importancia: null, endereco: "Jardim do Carmo", imagem: {"src": "assets/img/parque-natural-municipal-do-jardim-do-carmo.jpg", "alt": "Parque Natural Municipal do Jardim do Carmo", "fonte": "partiu__lugaresss.docx"} },
    { id: "parque-natural-municipal-do-mendanha", nome: "Parque Natural Municipal do Mendanha", bairro: "macico-do-mendanha", lat: -22.835284, lng: -43.49907, categoria: "Natureza/Paisagens", descricao: "O Parque Natural Municipal da Serra do Mendanha protege uma extensa área de Mata Atlântica no município do Rio de Janeiro, na região de Bangu. Criado em 1993, possui aproximadamente 1.445 hectares e faz parte do Maciço do Gericinó-Mendanha, um dos importantes remanescentes florestais da Região Metropolitana. Entre seus atrativos estão trilhas, cachoeiras e piscinas naturais, que permitem o contato com a natureza. Além do lazer, o parque tem papel importante na proteção das nascentes, da vegetação e dos animais que habitam a região.", importancia: null, endereco: "Campo Grande / Bangu", imagem: {"src": "assets/img/parque-natural-municipal-do-mendanha.jpg", "alt": "Parque Natural Municipal do Mendanha", "fonte": "partiu__lugaresss.docx"} },
    { id: "parque-natural-municipal-da-serra-da-capoeira-grande", nome: "Parque Natural Municipal da Serra da Capoeira Grande", bairro: "guaratiba", lat: -22.986767, lng: -43.641013, categoria: "Natureza/Paisagens", descricao: "O Parque Natural Municipal da Serra da Capoeira Grande está localizado em Guaratiba e protege um dos importantes remanescentes de vegetação nativa da região. Sua área reúne diferentes ambientes naturais, como Mata Atlântica, manguezais e restingas, que abrigam diversas espécies de plantas e animais. Entre os destaques está a variedade de aves, incluindo espécies residentes e migratórias. O parque também possui trilhas, nascentes e cachoeiras, contribuindo para a conservação ambiental e para a valorização das paisagens naturais da Zona Oeste.", importancia: null, endereco: "Guaratiba", imagem: {"src": "assets/img/parque-natural-municipal-da-serra-da-capoeira-grande.jpg", "alt": "Parque Natural Municipal da Serra da Capoeira Grande", "fonte": "partiu__lugaresss.docx"} },
    { id: "parque-estadual-da-pedra-branca", nome: "Parque Estadual da Pedra Branca", bairro: "jacarepagua", lat: -22.942293, lng: -43.49345, categoria: "Natureza/Paisagens", descricao: "O Parque Estadual da Pedra Branca é uma das maiores áreas de proteção ambiental localizadas dentro de uma cidade no Brasil, com mais de 12 mil hectares de extensão. Criado em 1974, protege um dos maiores remanescentes de Mata Atlântica do município do Rio de Janeiro, abrangendo áreas de diversos bairros da Zona Oeste. O parque conserva nascentes, rios, florestas e uma grande diversidade de espécies da fauna e da flora. Também possui trilhas, cachoeiras e construções históricas, sendo um importante espaço para a pesquisa científica, a educação ambiental e o contato com a natureza.", importancia: null, endereco: "Zona Oeste — abrangendo áreas como Jacarepaguá, Vargem e Guaratiba", imagem: {"src": "assets/img/parque-estadual-da-pedra-branca.jpg", "alt": "Parque Estadual da Pedra Branca", "fonte": "partiu__lugaresss.docx"} },
    { id: "parque-estadual-do-mendanha", nome: "Parque Estadual do Mendanha", bairro: "macico-do-mendanha", lat: -22.837596, lng: -43.554355, categoria: "Natureza/Paisagens", descricao: "O Parque Estadual do Mendanha é uma unidade de conservação que protege parte do Maciço do Gericinó-Mendanha, abrangendo áreas dos municípios do Rio de Janeiro, Nova Iguaçu e Mesquita. Criado em 2013, tem como objetivo preservar os remanescentes de Mata Atlântica, proteger nascentes e conservar espécies nativas da região. A área possui grande importância para o equilíbrio ambiental da Baixada Fluminense e integra um maciço reconhecido pela UNESCO como parte da Reserva da Biosfera da Mata Atlântica.", importancia: null, endereco: "Zona Oeste", imagem: {"src": "assets/img/parque-estadual-do-mendanha.jpg", "alt": "Parque Estadual do Mendanha", "fonte": "partiu__lugaresss.docx"} },
    { id: "reserva-biologica-e-arqueologica-de-guaratiba", nome: "Reserva Biológica e Arqueológica de Guaratiba", bairro: "guaratiba", lat: -22.994297, lng: -43.592696, categoria: "Natureza/Paisagens", descricao: "A Reserva Biológica Estadual de Guaratiba, anteriormente conhecida como Reserva Biológica e Arqueológica de Guaratiba, protege uma extensa área de manguezais e outros ambientes naturais na Zona Oeste do Rio de Janeiro. Criada em 1974 e recategorizada em 2010, conserva ecossistemas fundamentais para a reprodução e alimentação de diversas espécies, incluindo aves migratórias. Os manguezais também desempenham um papel importante na proteção da costa e na manutenção da vida marinha. Por ser uma reserva biológica, a visitação é restrita a atividades educativas e pesquisas científicas autorizadas.", importancia: null, endereco: "Guaratiba", imagem: {"src": "assets/img/reserva-biologica-e-arqueologica-de-guaratiba.jpg", "alt": "Reserva Biológica e Arqueológica de Guaratiba", "fonte": "partiu__lugaresss.docx"} },
    { id: "reserva-biologica-do-camorim", nome: "Reserva Biológica do Camorim", bairro: "jacarepagua", lat: -22.966291, lng: -43.418397, categoria: "Natureza/Paisagens", descricao: "A Reserva Biológica do Camorim é uma unidade de conservação municipal localizada na região de Jacarepaguá, integrada ao conjunto de áreas protegidas do Maciço da Pedra Branca. Sua importância está relacionada à preservação da Mata Atlântica, dos recursos hídricos e dos ambientes naturais próximos ao Açude do Camorim. A área contribui para a proteção das nascentes e da biodiversidade local, além de fazer parte de um importante corredor ecológico da Zona Oeste. Por sua categoria de reserva biológica, a conservação da natureza é sua prioridade, e o acesso não deve ser tratado como o de um parque público de visitação livre.", importancia: null, endereco: "Jacarepaguá", imagem: {"src": "assets/img/reserva-biologica-do-camorim.jpg", "alt": "Reserva Biológica do Camorim", "fonte": "partiu__lugaresss.docx"} },
    { id: "refugio-de-vida-silvestre-dos-campos-de-sernambetiba", nome: "Refúgio de Vida Silvestre dos Campos de Sernambetiba", bairro: "barra-da-tijuca", lat: null, lng: null, categoria: "Natureza/Paisagens", descricao: "O Refúgio de Vida Silvestre dos Campos de Sernambetiba é uma unidade de conservação municipal criada em 2022 para proteger áreas úmidas remanescentes da Baixada de Jacarepaguá, na região das Vargens e do Recreio dos Bandeirantes. Esses ambientes abrigam espécies de fauna e flora adaptadas a áreas alagadas, incluindo animais ameaçados de extinção. A preservação dos campos também é importante para o equilíbrio hídrico da região, contribuindo para a conservação da biodiversidade e para a proteção de áreas naturalmente sujeitas a alagamentos.", importancia: null, endereco: "Barra da Tijuca / Recreio", imagem: {"src": "assets/img/refugio-de-vida-silvestre-dos-campos-de-sernambetiba.jpg", "alt": "Refúgio de Vida Silvestre dos Campos de Sernambetiba", "fonte": "partiu__lugaresss.docx"} },
    { id: "cidade-do-samba-joaosinho-trinta", nome: "Cidade do Samba Joãosinho Trinta", bairro: "santo-cristo", lat: -22.895322, lng: -43.197878, categoria: "Personalidades/Memória", descricao: "A Cidade do Samba Joãosinho Trinta foi inaugurada em 2006, na região portuária do Rio de Janeiro, para reunir os barracões das escolas de samba do Grupo Especial. O espaço recebeu o nome do carnavalesco Joãosinho Trinta, um dos nomes mais importantes da história do Carnaval carioca, conhecido por revolucionar os desfiles com alegorias grandiosas e propostas criativas. Além de concentrar parte da produção do Carnaval, a Cidade do Samba valoriza o trabalho de artistas, escultores, costureiros e profissionais que mantêm viva essa manifestação cultural.", importancia: null, endereco: "Rua Rivadávia Corrêa, 60 — Santo Cristo", imagem: {"src": "assets/img/cidade-do-samba-joaosinho-trinta.jpg", "alt": "Cidade do Samba Joãosinho Trinta", "fonte": "partiu__lugaresss.docx"} },
    { id: "instituto-de-pesquisa-e-memoria-pretos-novos-ipn", nome: "Instituto de Pesquisa e Memória Pretos Novos — IPN", bairro: "gamboa", lat: -22.895738, lng: -43.192944, categoria: "Personalidades/Memória", descricao: "O Instituto de Pesquisa e Memória Pretos Novos (IPN) é uma instituição dedicada à preservação da memória da população africana escravizada e de seus descendentes no Brasil. Está instalado no local onde foram encontrados, em 1996, vestígios do antigo Cemitério dos Pretos Novos, utilizado entre os séculos XVIII e XIX para o sepultamento de africanos escravizados que chegavam ao Rio de Janeiro. Por meio de pesquisas, exposições e atividades educativas, o instituto contribui para o reconhecimento da história da escravidão e para a valorização da memória e da cultura afro-brasileira.", importancia: null, endereco: "Rua Pedro Ernesto, 32–34 — Gamboa", imagem: {"src": "assets/img/instituto-de-pesquisa-e-memoria-pretos-novos-ipn.jpg", "alt": "Instituto de Pesquisa e Memória Pretos Novos — IPN", "fonte": "partiu__lugaresss.docx"} },
    { id: "arquivo-geral-da-cidade-do-rio-de-janeiro", nome: "Arquivo Geral da Cidade do Rio de Janeiro", bairro: "cidade-nova", lat: -22.909193, lng: -43.202349, categoria: "Personalidades/Memória", descricao: "O Arquivo Geral da Cidade do Rio de Janeiro é responsável pela preservação e organização de documentos que registram a história e a administração da cidade. Criado em 1567, pouco depois da fundação do Rio de Janeiro, reúne um acervo formado por mapas, fotografias, plantas, manuscritos e registros oficiais de diferentes períodos. Esse material permite conhecer as transformações urbanas, políticas, sociais e culturais da cidade, além de apoiar pesquisas e iniciativas de preservação da memória carioca.", importancia: null, endereco: "Rua Amoroso Lima, 15 — Cidade Nova", imagem: {"src": "assets/img/arquivo-geral-da-cidade-do-rio-de-janeiro.jpg", "alt": "Arquivo Geral da Cidade do Rio de Janeiro", "fonte": "partiu__lugaresss.docx"} }
