        { id: 'sul5', texto: "Por que o patrimônio natural da Zona Sul é importante para a identidade do Rio de Janeiro?", opcoes: ["Porque impede completamente o crescimento urbano", "Porque todas as áreas naturais da região são intocadas", "Porque substitui o patrimônio histórico construído", "Porque as montanhas, florestas, praias e paisagens fazem parte da imagem e da história da cidade"], correta: 3, explicacao: null },
        { id: 'sul6', texto: "A diversidade de espaços culturais e instituições presentes na Zona Sul mostra que a região:", opcoes: ["Também participa da produção e preservação cultural do Rio", "Possui apenas função residencial", "Não possui relação com a história artística carioca", "Concentra somente atrações naturais"], correta: 0, explicacao: null },
        { id: 'sul7', texto: "A relação entre montanhas e áreas urbanizadas é uma característica marcante da Zona Sul porque:", opcoes: ["As montanhas foram totalmente removidas para permitir a urbanização", "A região não possui relevo significativo", "A ocupação urbana se desenvolveu em meio a uma paisagem natural bastante presente", "A urbanização ocorreu apenas em áreas distantes do litoral"], correta: 2, explicacao: null },
        { id: 'sul8', texto: "O turismo na Zona Sul está fortemente relacionado:", opcoes: ["Somente à existência de centros comerciais", "Principalmente às áreas industriais históricas", "À ausência de espaços naturais", "À combinação entre paisagens naturais, praias, patrimônio e atrações culturais"], correta: 3, explicacao: null },
        { id: 'sul9', texto: "O conceito de paisagem cultural ajuda a compreender a Zona Sul porque:", opcoes: ["Mostra como natureza e ação humana podem formar uma paisagem com valor cultural", "Considera apenas prédios históricos", "Exclui áreas urbanizadas da ideia de patrimônio", "Defende que natureza e cidade devem permanecer completamente separadas"], correta: 0, explicacao: null },
        { id: 'sul10', texto: "Considerando história, cultura, natureza e urbanização, qual síntese melhor representa a Zona Sul do Rio de Janeiro?", opcoes: ["Uma região formada exclusivamente por áreas de preservação ambiental", "Uma região onde paisagens naturais e vida urbana se relacionam de forma marcante", "Uma região cuja importância surgiu apenas com o turismo moderno", "Uma região sem patrimônio cultural construído"], correta: 1, explicacao: null }
